window.AB620_VIDEO = {"L05":{"src":"video/L05.mp4","duration":500.085,"scenes":[{"start":0},{"start":27.677},{"start":48.603},{"start":77.021},{"start":104.691},{"start":137.415},{"start":165.427},{"start":195.589},{"start":223.302},{"start":250.951},{"start":281.185},{"start":312.605},{"start":348.926},{"start":379.658},{"start":406.833},{"start":441.093},{"start":468.595}],"cues":[[0.8,2.707,"Monday morning at Contoso."],[2.787,5.958,"A maker builds an HR agent and, to test faster,"],[5.958,9.195,"switches authentication to No authentication."],[9.275,10.819,"Then the link gets shared."],[10.899,15.664,"Now anyone with that link can chat with an agent that knows HR policies."],[15.744,17.181,"Who should have stopped this?"],[17.261,19.541,"Copilot Studio has two safety nets,"],[19.541,23.584,"and admins have tools to govern hundreds of agents at once."],[23.664,27.427,"By the end of this class you will know exactly which one stops what."],[28.127,29.799,"Here is the picture to keep."],[29.879,31.977,"The security scan is an alarm."],[32.057,35.884,"It rings when you weaken a setting, but you can still walk through the door."],[35.964,37.977,"A data policy is a guard."],[38.057,42.225,"The administrator posts it at the door, and it simply does not let you pass."],[42.305,44.255,"One warns, the other prevents."],[44.335,48.353,"Many governance questions on the exam come down to this difference."],[49.053,50.64,"Let's watch the alarm."],[50.72,55.4,"Our maker switches from Authenticate with Microsoft to No authentication."],[55.48,56.768,"The scan warns."],[56.848,59.303,"If tools switch from end user credentials"],[59.303,62.317,"to the maker's own credentials, it warns again."],[62.397,65.604,"If the agent is shared with the whole organization,"],[65.604,69.829,"it warns too, because by default an agent is shared with nobody."],[69.909,71.283,"Notice the pattern."],[71.363,73.803,"Each warning means a default was weakened."],[73.883,76.771,"And notice the limit: the maker can still publish."],[77.471,78.673,"Now the guard."],[78.753,83.817,"The administrator defines data policies in Power Platform, for each environment."],[83.897,86.252,"A data policy works on connectors."],[86.332,90.991,"Here is the key idea: almost everything an agent does rides on a connector."],[91.071,95.132,"Channels, knowledge sources, tools, even MCP servers."],[95.212,97.342,"So when the admin blocks a connector,"],[97.342,101.513,"that capability simply disappears for every maker in the environment."],[101.593,103.372,"It does not warn, it blocks."],[103.452,104.441,"Blocked."],[105.141,109.011,"A data policy sorts every connector into one of three groups."],[109.091,111.36,"Business, Non-business, and Blocked."],[111.44,114.285,"Blocked connectors can't be used by any agent."],[114.365,117.62,"Business and Non-business connectors can both be used,"],[117.62,119.749,"but never together in one agent."],[119.829,124.205,"Picture an agent that reads SharePoint, which the admin put in Business,"],[124.205,128.051,"and posts to a social network the admin put in Non-business."],[128.131,132.491,"The moment the maker adds the second one, an error appears, in real time."],[132.571,137.165,"If a maker needs a blocked connector, ask the admin to move it to another group."],[137.865,138.94,"Your turn."],[139.02,142.548,"An agent works perfectly in the development environment."],[142.628,146.348,"In production, adding the same tool fails at once with an error."],[146.428,149.124,"Is the scan to blame, or a data policy?"],[149.204,150.94,"Decide before I answer."],[151.02,155.167,"It is a data policy, and it belongs to the production environment."],[155.247,158.223,"Policies are set per environment, so a connector can"],[158.223,161.399,"be allowed in development and blocked in production."],[161.479,165.177,"Check the target environment while you design, not on launch day."],[165.877,168.68,"Admins have a second lever, beyond connectors."],[168.76,171.89,"In the Power Platform admin center there is a setting"],[171.89,174.571,"called Control maker provided credentials."],[174.651,176.987,"When it is enforced, makers can no longer"],[176.987,179.693,"set tools to run with their own credentials."],[179.773,183.429,"Every connection is signed in by the end user, at runtime."],[183.509,185.245,"One more limit for Teams."],[185.325,190.167,"If an agent there uses custom Active Directory authentication, single sign"],[190.167,195.339,"on does not work for connectors, so users sign in to each connector by hand."],[196.039,198.543,"Knowledge works the same way, with a twist."],[198.623,201.639,"Each type of knowledge source has its own connector."],[201.719,203.668,"Uploaded documents have one."],[203.748,206.124,"SharePoint and OneDrive have another."],[206.204,208.153,"Public websites have a third."],[208.233,212.657,"So an admin can block public websites and keep SharePoint fully working."],[212.737,215.049,"Blocking one never touches the others."],[215.129,218.104,"And if blocking a whole connector is too blunt,"],[218.104,223.052,"endpoint filtering lets the admin allow or deny specific addresses instead."],[223.752,225.232,"Back to Monday morning."],[225.312,229.779,"How does the admin make sure nobody ever publishes an agent without sign in?"],[229.859,232.464,"There is a connector for exactly that:"],[232.464,237.12,"Chat without Microsoft Entra ID authentication in Copilot Studio."],[237.2,239.128,"Block it in the data policy."],[239.208,241.797,"Now the No authentication option is gone."],[241.877,246.835,"Makers can only choose Authenticate with Microsoft, or Authenticate manually."],[246.915,248.928,"The alarm would only have warned."],[249.008,250.701,"The guard closes the door."],[251.401,253.308,"Here is how the exam asks it."],[253.388,257.961,"An admin must prevent any agent from being published without authentication."],[258.041,260.695,"Option one, rely on the security scan."],[260.775,266.415,"Option two, block the Chat without Microsoft Entra ID authentication connector."],[266.495,270.151,"Option three, enforce Control maker provided credentials."],[270.231,271.305,"Decide."],[271.385,273.1,"The answer is option two."],[273.18,277.775,"The scan only warns, and that setting controls credentials, not sign in."],[277.855,280.935,"When the question says prevent, think data policy."],[281.635,282.88,"Now zoom out."],[282.96,287.469,"A large company has hundreds of agents, and they don't all need the same rules."],[287.549,291.824,"Zoned governance sorts them into three zones by purpose and risk."],[291.904,294.244,"Zone one is for citizens: private,"],[294.244,298.781,"read only agents made in Agent Builder or as SharePoint agents."],[298.861,302.334,"Zone two is for partnered makers, approved by IT,"],[302.334,305.44,"with a coach, in IT managed environments."],[305.52,308.638,"Zone three is for professional developers: ALM,"],[308.638,312.355,"the strongest controls, and service level agreements."],[313.055,316.412,"Each zone takes effect through its environment and policies."],[316.492,321.72,"Zone one allows only Microsoft three sixty five and Power Platform connectors,"],[321.72,323.798,"runs in the user's own context,"],[323.798,328.02,"lives in developer environments, and has sharing turned off."],[328.1,333.137,"Zone two adds advanced connector policies, approved data sources, environment"],[333.137,338.177,"groups and rules, deployment pipelines, and IT approval before publishing."],[338.257,343.431,"Zone three keeps advanced connector policies, adds Microsoft Purview, and shares"],[343.431,348.676,"agents through Integrated apps in the Microsoft three sixty five admin center."],[349.376,351.923,"To place any agent, ask four questions."],[352.003,353.205,"Who builds it?"],[353.285,354.531,"Who will use it?"],[354.611,356.88,"What data and permissions does it need?"],[356.96,358.376,"How critical is it?"],[358.456,359.488,"Try one."],[359.568,365.216,"An HR benefits agent, built by an IT approved maker, used by other departments,"],[365.216,369.133,"with shared HR data, and no service level agreement."],[369.213,370.309,"Which zone?"],[370.389,371.464,"Decide."],[371.544,372.597,"Zone two."],[372.677,376.141,"Not zone one, because others use it and the data is shared."],[376.221,379.408,"Not zone three, because nothing demands an SLA."],[380.108,382.484,"Environment groups apply rules at scale."],[382.564,387.308,"An environment belongs to one group only, and groups can't overlap or nest."],[387.388,392.552,"When a tenant admin sets rules on a group, such as agent sharing, generative AI"],[392.552,397.785,"settings, or transcript access, every environment inherits them as read only."],[397.865,399.132,"Here is the trap."],[399.212,402.207,"An environment admin can't override them locally."],[402.287,406.583,"If a change is needed, it goes through a tenant admin, at the group level."],[407.283,409.616,"Last piece: seeing every agent."],[409.696,415.315,"Microsoft Agent three sixty five gives admins one place to see and control them."],[415.395,420.16,"Copilot Studio agents join automatically, with no setup from the maker."],[420.24,423.568,"Admins find drafts and published agents in the Power"],[423.568,426.776,"Platform admin center, under Manage, Inventory."],[426.856,431.173,"The registry lives in the Microsoft three sixty five admin center."],[431.253,435.155,"An admin can block an agent: nobody can use it in any channel,"],[435.155,437.747,"but makers can still open and test it."],[437.827,440.843,"Microsoft Purview logs every governance action."],[441.543,442.596,"One more."],[442.676,447.079,"Our Monday agent, still set to No authentication, is used all week."],[447.159,449.748,"The admin opens the activity dashboards."],[449.828,451.991,"What does the admin see for those chats?"],[452.071,453.145,"Decide."],[453.225,454.172,"Nothing."],[454.252,456.884,"Telemetry needs an authenticated session,"],[456.884,461.577,"at least one qualifying license, and an agent that is not multitenant."],[461.657,466.316,"So an agent without sign in is not only exposed, it is also invisible."],[466.396,468.345,"Two reasons to close that door."],[469.045,470.227,"Let's close."],[470.307,472.448,"The scan is the alarm, it warns."],[472.528,474.97,"The data policy is the guard, it blocks,"],[474.97,478.04,"per environment, by connector, in three groups."],[478.12,480.645,"Each knowledge source has its own connector."],[480.725,484.317,"To stop agents without sign in, block that one connector."],[484.397,486.63,"Zones sort agents by who builds them,"],[486.63,489.909,"who uses them, the data, and how critical they are."],[489.989,494.499,"And Agent three sixty five sees everything, as long as users sign in."],[494.579,496.485,"Now Monday morning can't happen."]],"quiz":[{"at":149.204,"question":"An agent works in development. In production, adding the same tool fails at once with an error. What stopped it?","options":["The security scan","The development data policy","The production data policy"],"right":2,"trap":0,"answerAt":151.02},{"at":270.231,"question":"An admin must prevent any agent from being published without authentication. What do you do?","options":["Rely on the security scan","Block the Chat without Microsoft Entra ID authentication connector","Enforce Control maker-provided credentials"],"right":1,"trap":0,"answerAt":271.385},{"at":370.389,"question":"HR benefits agent: IT-approved maker, used by other departments, shared HR data, no SLA. Which zone?","options":["Zone 1 · Citizen","Zone 2 · Partnered","Zone 3 · Professional"],"right":1,"trap":0,"answerAt":371.544},{"at":452.071,"question":"An agent set to No authentication is used all week. What do admins see for those chats?","options":["Full conversation telemetry","Aggregated counts only","Nothing for unauthenticated sessions"],"right":2,"trap":0,"answerAt":453.225}],"poster":"video/L05.jpg"},"L14":{"src":"video/L14.mp4","duration":310.184,"scenes":[{"start":0},{"start":23.917},{"start":43.71},{"start":66.229},{"start":87.019},{"start":119.542},{"start":138.823},{"start":156.094},{"start":190.345},{"start":220.077},{"start":247.235},{"start":282.105}],"cues":[[0.8,3.409,"Marta wants to know the status of her ticket,"],[3.409,6.972,"but the tickets live in another system, outside the agent."],[7.053,10.559,"The service manager wants the agent to check by itself."],[10.64,14.722,"Valeria has the answer: the Send HTTP request node."],[14.803,17.674,"It lets a topic call an API on the internet,"],[17.674,21.658,"like asking another system for a piece of data by message."],[21.739,23.666,"Nexo gets a courier badge."],[24.367,26.528,"Think of a letter leaving the mail room."],[26.609,29.112,"You type the endpoint address, the URL."],[29.193,32.763,"You choose the method: get, post, patch, put, or delete."],[32.844,35.923,"You add headers if needed, such as Authorization."],[36.004,39.424,"Then you define the body, what goes inside the envelope."],[39.505,43.459,"By default the body is No Content, which is typical for a get."],[44.16,47.836,"When there is something to send, the body has two kinds of content."],[47.917,54.047,"With JSON content, you send a JSON object, typical for post or put."],[54.128,60.599,"With Edit JSON and Formula, you write it as a Power Fx object that uses variables."],[60.68,65.978,"With Raw content, you send a text string, also written with a Power Fx formula."],[66.679,69.544,"The other system answers with a reply letter."],[69.625,73.313,"In Response data type, Valeria pastes a sample"],[73.313,77.12,"JSON and chooses Get schema from sample JSON."],[77.201,80.365,"Copilot Studio generates a variable with that shape,"],[80.365,83.182,"so the topic knows the fields of the reply."],[83.263,86.768,"In Save user response as, she chooses where to store it."],[87.469,88.543,"Your turn."],[88.624,91.319,"Valeria adds the node to read one ticket."],[91.4,94.138,"She uses get and leaves the body as it is."],[94.219,96.274,"What does the body hold by default?"],[96.355,98.282,"An object with the ticket data?"],[98.363,100.375,"No Content, nothing is sent?"],[100.456,102.383,"Or a text string with the ticket?"],[102.464,104.199,"Decide before I answer."],[107.78,109.878,"No Content, nothing is sent."],[109.959,113.912,"The body is No Content by default, which is typical for a get."],[113.993,119.291,"AJSON object is for post or put, and a text string is Raw content."],[119.992,122.388,"Sometimes the letter comes back unanswered."],[122.469,124.994,"By default the node uses Raise an error."],[125.075,128.602,"The agent stops, and the On Error system topic fires."],[128.683,130.802,"The rest of the topic does not run."],[130.883,135.818,"Many authors leave this default and then do not understand why On Error appears."],[135.899,138.572,"Valeria wants a calmer path for Contoso."],[139.273,142.694,"With Continue on error, the node does not stop the agent."],[142.775,147.667,"The status code and the error body are saved in variables, and the topic goes on."],[147.748,151.488,"The error is of type Any, so you convert it with a Parse value node."],[151.569,155.843,"One more setting to know: the default request timeout is thirty seconds."],[156.544,157.618,"Your turn."],[157.699,161.546,"Marta asks about a missing ticket, and the tickets API fails."],[161.627,165.26,"The service manager wants the topic to reply and go on."],[165.341,167.674,"What should Valeria choose in Error handling?"],[167.755,169.746,"Keep the default, Raise an error?"],[169.827,171.818,"Set a longer request timeout?"],[171.899,173.826,"Or switch to Continue on error?"],[173.907,175.642,"Decide before I answer."],[179.223,181,"Switch to Continue on error."],[181.081,186.08,"It saves the status code and the error body in variables, and the topic goes on."],[186.161,190.094,"The default, Raise an error, stops the agent and fires On Error."],[190.795,193.81,"Contoso queries its tickets API with a get."],[193.891,195.951,"The body stays as No Content,"],[195.951,200.767,"and the response is saved in a variable built from a sample JSON."],[200.848,205.534,"Contoso chose Continue on error, so if the API returns a four oh four,"],[205.534,211.223,"the code goes into Topic Status Code and the error body into Topic Error Response."],[211.304,215.087,"The topic replies, I could not find that ticket, without stopping."],[215.168,219.826,"To create tickets, Contoso uses a post with JSON content."],[220.527,222.902,"Here are the steps in Copilot Studio."],[222.983,225.294,"Open a topic and select Add node."],[225.375,228.838,"Point to Advanced and choose Send HTTP request."],[228.919,231.016,"Type the URL and choose get."],[231.097,233.28,"Select Edit in Headers and body."],[233.361,238.616,"In Response data type, choose From sample data and paste a sample JSON."],[238.697,241.755,"In Save user response as, create a variable."],[241.836,244.339,"In Error handling, choose Continue on error"],[244.339,246.984,"and define the status and error variables."],[247.685,248.759,"Your turn."],[248.84,253.092,"Valeria chose Continue on error, so the error body waits in a variable."],[253.173,255.676,"It is of type Any, and she wants its fields."],[255.757,258.495,"Which node converts it into a structured record?"],[258.576,260.439,"Parse value, into a record?"],[260.52,262.639,"Send a message, as plain text?"],[262.72,264.583,"Or the On Error system topic?"],[264.664,266.399,"Decide before I answer."],[269.98,271.843,"Parse value, into a record."],[271.924,277.35,"Parse value converts a value of type Any into a structured record the topic can use."],[277.431,281.854,"On Error only runs when an error is not handled, so it converts nothing."],[282.555,286.092,"Back in the mail room, Marta's question now gets an answer,"],[286.092,288.45,"even when the ticket does not exist."],[288.531,289.967,"Remember three things."],[290.048,293.034,"The node sends a letter with an address, a method,"],[293.034,296.22,"headers, and a body that is No Content by default."],[296.301,299.594,"Raise an error is the default, and it fires On Error."],[299.675,304.503,"Continue on error saves the status and the error body, and Parse value reads it."],[304.584,306.682,"Next, tools inside a topic."]],"quiz":[{"at":102.464,"answerAt":107.78,"question":"Valeria reads one ticket with a GET and leaves the body as it is. What does the body hold by default?","options":["An object with the ticket data","No Content, nothing is sent","A text string with the ticket"],"right":1,"trap":0},{"at":173.907,"answerAt":179.223,"question":"Marta asks about a ticket that does not exist, the tickets API fails, and the topic stops. The service manager wants the topic to reply and go on. What should Valeria choose in Error handling?","options":["Keep the default, Raise an error","Set a longer request timeout","Switch to Continue on error"],"right":2,"trap":0},{"at":264.664,"answerAt":269.98,"question":"With Continue on error, the error body waits in a variable of type Any. Which node converts it into a structured record?","options":["Parse value, into a record","Send a message, as plain text","The On Error system topic"],"right":0,"trap":2}],"poster":"video/L14.jpg"},"L15":{"src":"video/L15.mp4","duration":367.516,"scenes":[{"start":0},{"start":23.727},{"start":45.721},{"start":69.461},{"start":108.191},{"start":132.022},{"start":158.279},{"start":193.682},{"start":220.03},{"start":246.863},{"start":271.158},{"start":300.685},{"start":336.706}],"cues":[[0.8,4.754,"Marta asks the Contoso agent about the stock of a product."],[4.835,8.234,"Nexo needs a tool for that, the Check inventory tool."],[8.315,10.306,"A tool can be called in two ways."],[10.387,12.731,"You can call it explicitly from a topic,"],[12.731,16.623,"or the agent can call it by itself when it decides it needs it."],[16.704,18.823,"The difference is who is in control."],[18.904,23.476,"It is like a driver who follows a fixed route, versus one who chooses the way."],[24.177,25.742,"First, the fixed route."],[25.823,29.84,"In classic orchestration, generative orchestration is turned off."],[29.921,32.296,"The agent answers only with topics."],[32.377,35.518,"Tools are called only explicitly, from inside a topic,"],[35.518,37.696,"at the step where you placed them."],[37.777,39.406,"Nobody else picks them."],[39.487,43.44,"Valeria draws the route, and Nexo follows it, stop by stop."],[43.521,45.47,"You keep full control of the flow."],[46.171,48.311,"Now the driver who chooses the way."],[48.392,50.258,"With generative orchestration,"],[50.258,54.5,"the orchestrator picks the most suitable tool or topic by itself."],[54.581,57.948,"The orchestrator is the part that decides which topic,"],[57.948,60.455,"tool, or knowledge to use to respond."],[60.536,63.999,"To choose a tool, it reads the tool's name and description."],[64.08,66.967,"So the description must say clearly what the tool does."],[67.048,69.21,"A vague one leaves Nexo guessing."],[69.911,70.984,"Your turn."],[71.065,74.912,"Valeria turns generative orchestration off for a test agent."],[74.993,77.304,"The Check inventory tool must still run."],[77.385,80.422,"In classic orchestration, how is a tool called?"],[80.503,82.686,"By the orchestrator, by description?"],[82.767,85.035,"Explicitly, from inside a topic?"],[85.116,87.32,"Or by the user, from the chat window?"],[87.401,89.136,"Decide before I answer."],[92.717,95.007,"Explicitly, from inside a topic."],[95.088,98.99,"In classic orchestration the agent answers only with topics,"],[98.99,101.986,"so tools run only where a topic calls them."],[102.067,106.068,"Picking a tool by name and description is generative orchestration,"],[106.068,107.94,"and that is turned off here."],[108.641,110.099,"Back on the fixed route."],[110.18,113.456,"To call a tool from a topic, Valeria selects Add node,"],[113.456,115.84,"then Add a tool, and picks the tool."],[115.921,118.254,"An Action node appears in the topic."],[118.335,120.283,"That node is the explicit call."],[120.364,122.76,"One more rule, and the exam loves it."],[122.841,124.79,"Trigger phrases start topics."],[124.871,127.267,"They only select topics, never tools."],[127.348,131.771,"You can use tools inside topics, but a trigger phrase never picks a tool."],[132.472,134.25,"Each tool has its details."],[134.331,139.202,"Allow agent to decide dynamically lets the agent pick the tool by itself."],[139.283,142.924,"Ask the end user before running asks for confirmation first,"],[142.924,144.58,"and it is No by default."],[144.661,149.468,"Authentication sets whether the tool runs with end user or maker credentials."],[149.549,152.095,"And Fill using sets how the inputs are filled."],[152.176,154.488,"Check inventory can show stock data,"],[154.488,158.028,"so Contoso turns on Ask the end user before running."],[158.729,159.803,"Your turn."],[159.884,163.24,"The service manager is worried about a sensitive tool."],[163.321,166.507,"Before it runs, the agent must get the user's okay."],[166.588,168.664,"Which setting should Valeria turn on?"],[168.745,170.694,"Ask the end user before running?"],[170.775,172.787,"A trigger phrase that asks first?"],[172.868,175.627,"Or Authentication with maker credentials?"],[175.708,177.443,"Decide before I answer."],[181.024,182.994,"Ask the end user before running."],[183.075,185.558,"That setting asks the user for confirmation"],[185.558,188.415,"before the tool runs, and it is No by default."],[188.496,193.431,"A trigger phrase only selects topics, never tools, so it cannot guard a tool."],[194.132,198,"When the tool finishes, After running sets how the agent responds."],[198.081,199.603,"There are four choices."],[199.684,201.91,"Don't respond, which is the default."],[201.991,204.302,"Write the response with generative AI."],[204.383,206.096,"Send specific response."],[206.177,207.976,"Or Send an adaptive card."],[208.057,212.438,"Tools run in the user's context, so authentication must be enabled."],[212.519,216.082,"At Contoso, Check inventory uses end user credentials,"],[216.082,219.779,"so each employee sees only what their account allows."],[220.48,224.903,"Inside one aisle, Valeria opens a small booth with two special tools."],[224.984,229.727,"They exist only inside topics, and you add them with Add a tool in a topic."],[229.808,234.423,"They do not appear on the agent's Tools page, and the orchestrator cannot call them."],[234.504,236.516,"The first is Create search query."],[236.597,239.012,"It rewrites the user's latest message,"],[239.012,242.834,"plus the conversation context, into a clear query string."],[242.915,246.612,"A follow up like, what about sick leave, becomes a full question."],[247.313,249.603,"The second is Perform custom search."],[249.684,252.915,"It searches the knowledge sources you set on the node,"],[252.915,256.646,"and returns the raw results, not summarized, in a variable."],[256.727,260.467,"Then you can filter them, apply business rules, or feed a prompt."],[260.548,263.222,"The two tools are often used in sequence."],[263.303,268.344,"Compare the Generative answers node, which finds and writes the answer in one step."],[268.425,270.907,"Here, retrieval and response are separate."],[271.608,273.983,"Here are the steps in Copilot Studio."],[274.064,276.802,"Open your agent and go to the Tools page."],[276.883,280.367,"Select Add a tool, choose a tool, then Add and configure."],[280.448,283.099,"In its settings, review the Name and Description,"],[283.099,285.895,"written so the orchestrator can understand them."],[285.976,290.228,"Turn on Ask the end user before running if the action is sensitive."],[290.309,294.114,"Now open a topic, select Add node, and choose Add a tool."],[294.195,296.911,"Select the tool, and an Action node appears."],[296.992,300.434,"Test in the chat, and check whether it asks for confirmation."],[301.135,302.208,"Your turn."],[302.289,305.518,"Valeria wants the raw search results in a variable."],[305.599,308.379,"Then the topic will filter them with business rules."],[308.46,310.856,"Which tool should she add inside the topic?"],[310.937,312.416,"Create search query?"],[312.497,314.147,"Generative answers node?"],[314.228,315.92,"Or Perform custom search?"],[316.001,317.736,"Decide before I answer."],[321.317,322.882,"Perform custom search."],[322.963,327.019,"It searches the knowledge sources set on the node and returns raw,"],[327.019,329.37,"unsummarized results in a variable."],[329.451,333.1,"Generative answers finds and writes the answer in one step,"],[333.1,336.455,"and Create search query only rewrites the question."],[337.156,341.984,"Back on the warehouse floor, Marta confirms, and Nexo brings her stock answer."],[342.065,343.502,"Remember three things."],[343.583,346.139,"Classic means an explicit call from a topic,"],[346.139,350.288,"and generative means the orchestrator picks by name and description."],[350.369,352.577,"Trigger phrases select only topics,"],[352.577,356.435,"and Ask the end user before running asks for confirmation."],[356.516,361.387,"Create search query and Perform custom search work only inside topics."],[361.468,364.014,"Next, agent flows inside a topic."]],"quiz":[{"at":87.401,"answerAt":92.717,"question":"Valeria turns generative orchestration off, and the Check inventory tool must still run. In classic orchestration, how is a tool called?","options":["By the orchestrator, by description","Explicitly, from inside a topic","By the user, from the chat window"],"right":1,"trap":0},{"at":175.708,"answerAt":181.024,"question":"Before a sensitive tool runs, the agent must get the user's okay. Which setting should Valeria turn on?","options":["Ask the end user before running","A trigger phrase that asks first","Authentication with maker credentials"],"right":0,"trap":1},{"at":316.001,"answerAt":321.317,"question":"Valeria wants the raw search results in a variable, so the topic can filter them with business rules. Which tool should she add inside the topic?","options":["Create search query","Generative answers node","Perform custom search"],"right":2,"trap":1}],"poster":"video/L15.jpg"},"L16":{"src":"video/L16.mp4","duration":336.138,"scenes":[{"start":0},{"start":23.661},{"start":46.953},{"start":68.09},{"start":101.509},{"start":125.441},{"start":150.65},{"start":175.326},{"start":212.115},{"start":237.178},{"start":265.531},{"start":302.854}],"cues":[[0.8,5.095,"Marta has a problem with her laptop, and she tells the Contoso agent."],[5.176,7.466,"Nexo needs to create a ticket for her."],[7.547,10.557,"An agent flow is an automatic recipe of steps,"],[10.557,13.57,"like creating a ticket or sending an email."],[13.651,17.412,"You can give it to the whole agent, which uses it when it sees fit."],[17.493,20.411,"Or you can place it at an exact point in a topic,"],[20.411,23.41,"like a step that always goes in the same place."],[24.111,25.76,"First, the exact point."],[25.841,29.88,"When you add a flow to a topic, it is available only to that topic."],[29.961,34.555,"It runs exactly at the point on the canvas where you put it, like an Action node."],[34.636,39.379,"At Contoso, the CreateTicket flow goes inside the Report problem topic."],[39.46,43.606,"It runs right after the agent collects the title and the urgency."],[43.687,46.702,"Then it returns the ticket number, shown in a message."],[47.403,48.754,"Now the other way."],[48.835,53.684,"If you add the flow from the agent's Tools page, it becomes an agent-level tool."],[53.765,58.295,"The orchestrator can pick it directly at run time, without a topic calling it."],[58.376,62.052,"So the flow is no longer tied to one moment in one topic."],[62.133,64.999,"It becomes the agent's choice, not a fixed step."],[65.08,67.839,"Nexo can reach for it whenever it sees fit."],[68.54,69.614,"Your turn."],[69.695,73.286,"The service manager wants a ticket at one exact moment."],[73.367,75.571,"No tickets in other conversations."],[75.652,78.24,"Where should Valeria add the CreateTicket flow?"],[78.321,80.291,"On the agent's own Tools page?"],[80.372,82.214,"In the Report problem topic?"],[82.295,84.371,"Or in all topics of the agent?"],[84.452,86.187,"Decide before I answer."],[89.768,91.631,"In the Report problem topic."],[91.712,94.785,"A flow in a topic is available only to that topic,"],[94.785,97.074,"and runs exactly where you put it."],[97.155,101.258,"On the Tools page, the orchestrator could pick it in any conversation."],[101.959,105.571,"But what if Contoso also adds the flow as an agent tool?"],[105.652,109.499,"Then Valeria turns off Allow agent to decide dynamically."],[109.58,112.325,"With that setting off, the agent uses the flow"],[112.325,114.792,"only when a topic calls it explicitly."],[114.873,116.758,"Watch out for a common trap."],[116.839,120.579,"Ask the end user before running does not block the selection."],[120.66,125.19,"It only asks for confirmation, and the orchestrator can still pick the flow."],[125.891,127.775,"Not every flow can be a tool."],[127.856,130.827,"It must have the When an agent calls the flow trigger,"],[130.827,132.898,"and a Respond to the agent action."],[132.979,137.828,"It must be published, respond in real time, and do so within one hundred seconds."],[137.909,142.162,"It must also be a solution flow, or it does not appear in the tool picker."],[142.243,146.19,"Good news: if you create the flow as a new tool from the agent,"],[146.19,150.399,"Copilot Studio adds the trigger and the response action for you."],[151.1,153.966,"Some jobs take longer than one hundred seconds."],[154.047,158.342,"Respond to the agent is the line between synchronous and asynchronous."],[158.423,161.093,"Actions placed after it run asynchronously,"],[161.093,164.894,"up to Power Automate's flow duration limit of thirty days."],[164.975,168.799,"So for long work, start the job and return a job ID quickly,"],[168.799,170.72,"within one hundred seconds."],[170.801,175.075,"Then a polling topic or a follow-up message gives the final result."],[175.776,176.85,"Your turn."],[176.931,179.668,"CreateTicket is now an agent tool too."],[179.749,182.252,"It must run only when a topic calls it."],[182.333,184.303,"Which setting should Valeria change?"],[184.384,187.164,"Turn off Allow agent to decide dynamically?"],[187.245,189.642,"Turn on Ask the end user before running?"],[189.723,192.759,"Or remove the flow from the Report problem topic?"],[192.84,194.575,"Decide before I answer."],[198.156,200.979,"Turn off Allow agent to decide dynamically."],[201.06,205.803,"With it off, the agent uses the flow only when a topic calls it explicitly."],[205.884,209.364,"Ask the end user before running only asks for confirmation,"],[209.364,211.864,"and the orchestrator can still pick it."],[212.565,218.14,"Microsoft also documents a newer, separate option, called Asynchronous response On."],[218.221,221.727,"It is a callback for flows that run longer than two minutes."],[221.808,225.164,"It works only in environments on the new infrastructure."],[225.245,230.266,"It is fully supported in Teams, but not in Microsoft Copilot or telephony."],[230.347,232.295,"But it is not the tool pattern."],[232.376,236.927,"For a flow used as a tool, keep it Off, and use the job ID approach."],[237.628,240.003,"Here are the steps in Copilot Studio."],[240.084,242.8,"Create a simple agent flow and publish it."],[242.881,247.838,"Open your agent, go to the Topics page, and open the Report problem topic."],[247.919,250.208,"Select Add node under the node you want."],[250.289,252.92,"Choose Add a tool and select CreateTicket."],[253.001,255.611,"An Action node appears at that exact point."],[255.692,259.902,"Map the inputs to topic variables, and use the outputs in a Message."],[259.983,265.28,"If you also added it as an agent tool, turn off Allow agent to decide dynamically."],[265.981,267.055,"Your turn."],[267.136,270.62,"A Contoso flow starts a job that runs for hours."],[270.701,274.036,"As a tool, it must respond within one hundred seconds."],[274.117,275.618,"What should Valeria do?"],[275.699,278.095,"Turn on the Asynchronous response option?"],[278.176,280.508,"Move every action before the response?"],[280.589,283.242,"Or reply early, work after the response?"],[283.323,285.058,"Decide before I answer."],[288.639,291.163,"Reply early, work after the response."],[291.244,293.748,"Return a job ID at Respond to the agent,"],[293.748,298.142,"and place the long actions after it, where they run asynchronously."],[298.223,302.603,"Asynchronous response On is a separate callback, so for a tool keep it Off."],[303.304,307.258,"Back at the plant, Marta reads her ticket number, and Nexo moves on."],[307.339,308.775,"Remember three things."],[308.856,312.911,"A flow that must run at an exact point goes inside the topic,"],[312.911,318.164,"and turning off Allow agent to decide dynamically means explicit calls only."],[318.245,322.178,"Ask the end user before running only asks for confirmation."],[322.259,325.314,"And for a job longer than one hundred seconds,"],[325.314,329.498,"return a job ID at Respond to the agent, in a solution flow."],[329.579,332.636,"Next, create an agent flow and its parameters."]],"quiz":[{"at":84.452,"answerAt":89.768,"question":"CreateTicket must run at one exact moment, and Contoso does not want tickets created in other conversations. Where should Valeria add the flow?","options":["On the agent's own Tools page","In the Report problem topic","In all topics of the agent"],"right":1,"trap":0},{"at":192.84,"answerAt":198.156,"question":"CreateTicket is also an agent tool, and the service manager wants it used only when a topic calls it. Which setting should Valeria change?","options":["Turn off Allow agent to decide dynamically","Turn on Ask the end user before running","Remove the flow from the Report problem topic"],"right":0,"trap":1},{"at":283.323,"answerAt":288.639,"question":"A Contoso flow starts a job that runs for hours, but as a tool it must respond within 100 seconds. What should Valeria do?","options":["Turn on the Asynchronous response option","Move every action before the response","Reply early, work after the response"],"right":2,"trap":0}],"poster":"video/L16.jpg"},"L17":{"src":"video/L17.mp4","duration":327.485,"scenes":[{"start":0},{"start":22.573},{"start":42.513},{"start":67.639},{"start":91.614},{"start":126.014},{"start":150.266},{"start":176.803},{"start":212.355},{"start":236.567},{"start":262.678},{"start":297.889}],"cues":[[0.8,4.754,"Marta tells the Contoso agent that her laptop will not turn on."],[4.835,8.831,"Nexo needs to open a ticket, and Valeria builds the tool for it."],[8.912,13.57,"An agent flow is a sequence of automatic steps that the agent can run."],[13.651,17.434,"Think of a recipe, with input ingredients and an output dish."],[17.515,22.322,"For the agent to use it, the recipe must start and end in a very specific way."],[23.023,26.614,"The start is the trigger called When an agent calls the flow."],[26.695,29.859,"The end is the action called Respond to the agent."],[29.94,33.552,"In between go the actions you want, the steps that do the work."],[33.633,38.078,"Other triggers belong to other scenarios, such as Power Apps or schedules."],[38.159,42.262,"Without this start and this end, Nexo cannot use the flow as a tool."],[42.963,44.25,"Now the inputs."],[44.331,47.602,"Inputs are defined in the trigger, at the start of the flow."],[47.683,51.295,"CreateTicket needs two of them, a title and an urgency."],[51.376,53.185,"With generative orchestration,"],[53.185,56.823,"the agent fills the inputs from the conversation context."],[56.904,60.644,"When something is missing, it generates questions to ask for it."],[60.725,63.126,"Marta said her laptop will not turn on,"],[63.126,67.388,"so Nexo takes the title from her message and asks for the urgency."],[68.089,71.168,"But what if every ticket starts with the same urgency?"],[71.249,74.819,"The service manager says all new tickets begin as Medium."],[74.9,78.278,"Valeria sets a Custom value on the urgency input."],[78.359,82.91,"A Custom value is a fixed value that replaces the automatic filling."],[82.991,86.539,"Once it is set, the agent no longer asks for that input."],[86.62,91.363,"Nexo only takes the title from Marta, and the urgency is always Medium."],[92.064,93.138,"Your turn."],[93.219,96.916,"The service manager wants every ticket to start as Medium."],[96.997,100.802,"Today, Nexo still asks Marta for the urgency each time."],[100.883,102.383,"What should Valeria do?"],[102.464,104.647,"Add a Question node for urgency?"],[104.728,106.655,"Set a Custom value of Medium?"],[106.736,108.855,"Or remove urgency from the trigger?"],[108.936,110.671,"Decide before I answer."],[114.252,116.179,"Set a Custom value of Medium."],[116.26,120.534,"With a fixed Custom value, the agent no longer asks for that input."],[120.615,122.801,"A Question node would still ask Marta,"],[122.801,125.763,"which is exactly what the manager wants to stop."],[126.464,127.772,"Now the other end."],[127.853,130.847,"Outputs are defined in Respond to the agent."],[130.928,134.348,"CreateTicket returns one output, the ticket ID."],[134.429,137.568,"Inside the flow there can be many internal variables,"],[137.568,139.663,"but they do not reach the agent."],[139.744,143.506,"Only the outputs you define in Respond to the agent arrive."],[143.587,146.731,"They appear as variables in the tool node of a topic,"],[146.731,150.015,"or the orchestrator uses them to write the response."],[150.716,154.03,"A few more conditions before Nexo can use the flow."],[154.111,155.952,"First, it must be published."],[156.033,158.579,"Second, it must respond in real time."],[158.66,161.376,"So the Asynchronous response option must be Off."],[161.457,165.219,"You find it under Networking, inside Respond to the agent."],[165.3,169.638,"The flow must also answer within the action limit of one hundred seconds."],[169.719,174.254,"A separate callback feature with Asynchronous response On exists for long flows,"],[174.254,176.552,"but it is not the pattern for a tool."],[177.253,178.327,"Your turn."],[178.408,182.404,"Valeria's flow keeps the ticket ID in an internal variable."],[182.485,186.14,"Nexo runs the flow, but never shares the number with Marta."],[186.221,187.722,"What should Valeria do?"],[187.803,190.114,"Ask Nexo to read the flow variable?"],[190.195,192.271,"Copy the variable into the topic?"],[192.352,194.514,"Or add it to Respond to the agent?"],[194.595,196.33,"Decide before I answer."],[199.911,201.859,"Add it to Respond to the agent."],[201.94,206.918,"Only the outputs defined there reach the agent, as variables or for the response."],[206.999,212.104,"Internal variables never arrive, so Nexo cannot read them, no matter how you ask."],[212.805,214.988,"Here is the whole Contoso case."],[215.069,217.679,"Marta writes that her laptop will not turn on."],[217.76,221.607,"Nexo calls CreateTicket and fills the title from her message."],[221.688,226.132,"The urgency comes from the Custom value, Medium, so nobody asks."],[226.213,228.268,"The middle actions create the ticket."],[228.349,231.772,"At the end, Respond to the agent returns the ticket ID,"],[231.772,233.839,"and Nexo shares it with Marta."],[233.92,236.316,"And the flow was published before it was added."],[237.017,239.392,"Here are the steps in Copilot Studio."],[239.473,243.832,"Create a new agent flow, with the designer or with natural language."],[243.913,247.05,"Check that the trigger is When an agent calls the flow,"],[247.05,249.36,"and add the inputs title and urgency."],[249.441,251.624,"Add the middle actions that do the work."],[251.705,256.32,"At the end, add Respond to the agent and define the output ticket ID."],[256.401,258.691,"Check that Asynchronous response is Off."],[258.772,262.427,"Then publish the flow, and add it from Tools, Add a tool, Flow."],[263.128,264.202,"Your turn."],[264.283,268.556,"Valeria's new flow has the right trigger and Respond to the agent."],[268.637,272.868,"Asynchronous response is Off, but the flow does not show up as a tool."],[272.949,274.45,"What should Valeria do?"],[274.531,276.436,"Publish the flow, then add it?"],[276.517,278.466,"Turn on Asynchronous response?"],[278.547,280.772,"Or set a Custom value on each input?"],[280.853,282.588,"Decide before I answer."],[286.169,288.096,"Publish the flow, then add it."],[288.177,292.003,"A flow must be published before the agent can use it as a tool."],[292.084,295.085,"Asynchronous response on breaks the real time rule,"],[295.085,297.638,"and Custom values do not make it appear."],[298.339,302.783,"Back at the rail yard, Marta reads her ticket ID, and Nexo moves on."],[302.864,304.151,"Remember the rules."],[304.232,306.497,"The flow starts with When an agent calls"],[306.497,309.188,"the flow and ends with Respond to the agent."],[309.269,313.159,"Inputs live in the trigger, and a Custom value stops the questions."],[313.24,315.722,"Only explicit outputs reach the agent."],[315.803,318.685,"It must be published, with Asynchronous response Off,"],[318.685,320.951,"and answer within one hundred seconds."],[321.032,323.983,"Next, actions, connectors, and express mode."]],"quiz":[{"at":108.936,"answerAt":114.252,"question":"The service manager wants every ticket to start as Medium, but Nexo still asks Marta for the urgency each time. What should Valeria do?","options":["Add a Question node for urgency","Set a Custom value of Medium","Remove urgency from the trigger"],"right":1,"trap":0},{"at":194.595,"answerAt":199.911,"question":"Valeria's flow keeps the ticket ID in an internal variable. Nexo runs the flow, but never shares the number with Marta. What should Valeria do?","options":["Ask Nexo to read the flow variable","Copy the variable into the topic","Add it to Respond to the agent"],"right":2,"trap":0},{"at":280.853,"answerAt":286.169,"question":"Valeria's new flow has the right trigger and Respond to the agent, and Asynchronous response is Off, but it does not show up as a tool. What should Valeria do?","options":["Publish the flow, then add it","Turn on Asynchronous response","Set a Custom value on each input"],"right":0,"trap":1}],"poster":"video/L17.jpg"},"L34":{"src":"video/L34.mp4","duration":445.365,"scenes":[{"start":0},{"start":24.455},{"start":51.185},{"start":77.893},{"start":104.019},{"start":126.205},{"start":159.346},{"start":184.363},{"start":207.186},{"start":235.235},{"start":269.438},{"start":292.218},{"start":315.723},{"start":337.287},{"start":359.574},{"start":384.442},{"start":415.575}],"cues":[[0.8,2.408,"Monday at Contoso."],[2.488,7.083,"The manager asks the team a simple question about Nexo, the IT agent."],[7.163,10.157,"What do employees really ask it, and is it working?"],[10.237,12.549,"The team opens the numbers and frowns."],[12.629,16.157,"Half of the conversations are their own tests from last week."],[16.237,18.357,"The other half nobody can explain."],[18.437,21.093,"By the end of this class you will know the two tools"],[21.093,24.205,"that answer that question, and how to keep the tests out."],[24.905,26.577,"Here is the picture to keep."],[26.657,28.692,"An airplane has a black box."],[28.772,33.239,"It records everything, and later an investigator queries it in detail."],[33.319,36.249,"That is Application Insights, an Azure service."],[36.329,38.558,"The airplane also has a cockpit dashboard,"],[38.558,40.988,"with the health of the flight at a glance."],[41.068,44.867,"That is the Monitor tab of the Microsoft Copilot harness,"],[44.867,47.199,"formerly GitHub Copilot harness."],[47.279,50.935,"One records for deep analysis, the other shows health now."],[51.635,53.179,"First the black box."],[53.259,58.429,"In Azure, create an Application Insights resource and copy its Connection string."],[58.509,60.693,"That string identifies your resource."],[60.773,64.38,"Then, in Copilot Studio, open Nexo and go to Settings,"],[64.38,68.12,"then Advanced, then the Application Insights section."],[68.2,71.536,"Paste the Connection string and turn on Enable logging."],[71.616,75.251,"From now on, every conversation leaves a record in Azure."],[75.331,77.643,"Nothing else in the agent changes."],[78.343,81.295,"Below Enable logging there are three more switches."],[81.375,86.055,"Log conversation details adds the user, the name, and the message text."],[86.135,90.9,"Log sensitive Activity properties adds sensitive details of each activity."],[90.98,94.961,"Node execution events adds one event for every node that runs,"],[94.961,97.857,"so you can follow the path inside a topic."],[97.937,100.602,"More detail means more personal data stored,"],[100.602,103.769,"so turn each one on only when you really need it."],[104.469,106.013,"Where does the data land?"],[106.093,108.128,"In a table called customEvents."],[108.208,113.4,"Each event carries a set of dimensions, and one of them matters a lot: designMode."],[113.48,116.712,"It is True when the conversation happened in the test canvas,"],[116.712,118.608,"the chat you use while building."],[118.688,120.488,"It is False for real users."],[120.568,123.648,"This small label is the answer to the Monday mess."],[123.728,125.955,"The tests are there, but they are marked."],[126.655,127.729,"Your turn."],[127.809,131.508,"Nexo's numbers mix the team's tests with real employees."],[131.588,134.049,"The manager wants only real traffic."],[134.129,135.289,"What do you do?"],[135.369,138.3,"Delete the old events from the customEvents table?"],[138.38,141.503,"Filter designMode equal to False in the query?"],[141.583,144.727,"Or publish the agent again to reset the counters?"],[144.807,146.543,"Decide before I answer."],[150.123,152.499,"Filter designMode equal to False."],[152.579,155.68,"The tests stay recorded but drop out of the query."],[155.76,159.096,"Deleting loses data, and publishing resets nothing."],[159.796,164.327,"The language for those queries is KQL, the query language of Azure."],[164.407,165.908,"The idea is short."],[165.988,170.534,"Start from customEvents, keep only the rows where designMode is False,"],[170.534,174.956,"and then group them, for example by the message text or by topic."],[175.036,178.131,"Now Contoso sees what employees really ask Nexo,"],[178.131,180.911,"and which questions come back every day."],[180.991,184.113,"That is the deep analysis the black box is for."],[184.813,186.827,"You do not have to start from zero."],[186.907,189.83,"Inside Application Insights, under Workbooks,"],[189.83,194.381,"there is a ready panel called Copilot Studio Dashboard, in preview."],[194.461,197.115,"It already charts the main numbers of your agent."],[197.195,199.144,"The manager wants to see it too."],[199.224,203.285,"To share it, give the Reader role on the Application Insights resource."],[203.365,206.936,"Reader lets people look at the data without changing anything."],[207.636,209.244,"Now the security side."],[209.324,212.695,"Contoso's security team wants to be sure no agent"],[212.695,215.647,"sends telemetry to Application Insights."],[215.727,220.001,"Switching off the toggles inside one agent is not an admin control."],[220.081,222.201,"Any maker could switch them on again."],[222.281,226.278,"The admin control is a data policy that blocks the connector"],[226.278,229.543,"called Application Insights in Copilot Studio."],[229.623,234.985,"There is also environment level telemetry, in preview, which uses traces and spans."],[235.685,236.76,"Your turn."],[236.84,241.438,"The security team must guarantee that no agent in the environment can"],[241.438,246.235,"send telemetry to Application Insights, not today and not next month."],[246.315,247.603,"What do they use?"],[247.683,249.995,"Block its connector in a data policy?"],[250.075,252.621,"Turn off Enable logging in every agent?"],[252.701,255.248,"Or remove the Reader role from every maker?"],[255.328,257.064,"Decide before I answer."],[260.644,265.9,"Block the Application Insights in Copilot Studio connector in a data policy."],[265.98,269.188,"Toggles can come back, and Reader is only for viewing."],[269.888,271.219,"Now the cockpit."],[271.299,275.829,"On the Microsoft Copilot harness, open the agent and select Monitor."],[275.909,277.304,"Set the date range."],[277.384,281.36,"Each percentage compares with the previous period of the same length."],[281.44,283.436,"If the agent was never published,"],[283.436,286.781,"the metrics are empty, because only real use counts."],[286.861,291.968,"And be patient: after a session ends, its data can take up to an hour to appear."],[292.668,294.873,"The overview shows the health at a glance."],[294.953,299.292,"Total sessions, total users, average duration, and success rate."],[299.372,303.327,"A session is one conversation between a user and the agent."],[303.407,308.3,"If the agent also works on its own, you see autonomous runs and their fail rate."],[308.38,313.423,"For Contoso this answers the second half of the Monday question: is Nexo working?"],[313.503,315.473,"The success rate says it plainly."],[316.173,319.893,"The Reactions card counts thumbs up and thumbs down from users."],[319.973,324.205,"One morning the card shows no numbers and asks you to turn on feedback."],[324.285,326.725,"That means the User feedback setting is off."],[326.805,329.821,"You find it in Settings, under Safety and access."],[329.901,334.005,"Turn it on, and employees can react to every answer Nexo gives."],[334.085,337.037,"Reactions are the cheapest signal you will ever get."],[337.737,340.092,"Below the cards is the Sessions list."],[340.172,342.42,"It shows only the past twenty eight days."],[342.5,346.186,"For each session you see the status, which is completed, failed,"],[346.186,350.188,"or in progress, the tools that were used, and the credits it cost."],[350.268,352.695,"Open one and you get the full transcript,"],[352.695,355.737,"with every tool call and every use of knowledge."],[355.817,359.324,"A failed session tells you exactly where Nexo got lost."],[360.024,364.107,"One card matters to finance: Total estimated credits used."],[364.187,366.2,"That is the number used for billing."],[366.28,370.304,"It updates a few times a day, and you can split it by experience:"],[370.304,372.795,"production, Preview, and evaluations."],[372.875,377.171,"So you see how much the building and testing cost, apart from real use."],[377.251,379.377,"And the black box still works here:"],[379.377,384.192,"environment level telemetry in Application Insights works on both harnesses."],[384.892,385.967,"Your turn."],[386.047,390.727,"Finance wants the credits Contoso will be billed for this month on Nexo."],[390.807,392.351,"Where do you get the figure?"],[392.431,395.063,"Add up the credits shown for each listed session?"],[395.143,398.116,"Query the credit events in Application Insights?"],[398.196,401.468,"Or read Total estimated credits used on Monitor?"],[401.548,403.284,"Decide before I answer."],[406.864,410.157,"Total estimated credits used, on the Monitor tab."],[410.237,412.144,"It is the billing source of truth."],[412.224,415.325,"The sessions list is only a view of single sessions."],[416.025,417.271,"Back to Monday."],[417.351,421.839,"Contoso filters designMode equal to False, and the tests disappear."],[421.919,426.833,"The workbook shows what employees ask, and the Monitor tab shows Nexo is healthy."],[426.913,428.372,"Remember for the exam."],[428.452,430.828,"Connection string in Settings, Advanced."],[430.908,432.601,"Data in customEvents."],[432.681,436.081,"Block telemetry with a data policy on the connector."],[436.161,438.583,"Monitor keeps twenty eight days of sessions,"],[438.583,441.865,"data can take an hour, and its credits are what you pay."]],"quiz":[{"at":144.807,"question":"Nexo's numbers mix the team's tests with real employees. The manager wants only real traffic. What do you do?","options":["Delete the old events from the customEvents table","Filter designMode equal to False in the query","Publish the agent again to reset the counters"],"right":1,"trap":0,"answerAt":150.123},{"at":255.328,"question":"The security team must guarantee that no agent in the environment can send telemetry to Application Insights, not today and not next month. What do they use?","options":["Block its connector in a data policy","Turn off Enable logging in every agent","Remove the Reader role from every maker"],"right":0,"trap":1,"answerAt":260.644},{"at":401.548,"question":"Finance wants the credits Contoso will be billed for this month on Nexo. Where do you get the figure?","options":["Add up the credits shown for each listed session","Query the credit events in Application Insights","Read Total estimated credits used on Monitor"],"right":2,"trap":0,"answerAt":406.864}],"poster":"video/L34.jpg"},"L41":{"src":"video/L41.mp4","duration":464.5,"scenes":[{"start":0},{"start":29.343},{"start":54.838},{"start":79.194},{"start":102.27},{"start":132.325},{"start":162.899},{"start":189.053},{"start":217.825},{"start":242.159},{"start":270.369},{"start":298.119},{"start":324.502},{"start":352.669},{"start":377.243},{"start":403.823},{"start":433.566}],"cues":[[0.8,2.792,"Tuesday morning at Contoso."],[2.872,5.248,"The HR agent gets three questions."],[5.328,8.387,"An employee asks about the parental leave policy."],[8.467,11.611,"The sales director asks for revenue by region."],[11.691,15.325,"A manager asks which meetings this week mention a renewal."],[15.405,18.592,"None of these answers lives in Copilot Studio."],[18.672,21.019,"The policy, the numbers and the meetings"],[21.019,23.8,"are kept by other teams, on other platforms."],[23.88,26.475,"By the end of this class you will know which"],[26.475,29.093,"Microsoft IQ capability answers each one."],[29.793,31.465,"Here is the picture to keep."],[31.545,36.353,"Microsoft IQ is like three expert colleagues sitting next to your agent."],[36.433,39.065,"The first one knows the official policies."],[39.145,41.585,"The second one knows the business numbers."],[41.665,44.673,"The third one knows how your teams work every day,"],[44.673,47.22,"their files, email, meetings and chats."],[47.3,49.463,"Your agent does not learn what they know."],[49.543,50.745,"It asks them."],[50.825,54.588,"Their names are Foundry IQ, Fabric IQ and Work IQ."],[55.288,56.981,"The key idea is reuse."],[57.061,61.891,"With a knowledge source, you pick and upload the content yourself in Copilot Studio."],[61.971,66.719,"With an IQ capability, the context already exists outside Copilot Studio,"],[66.719,70.171,"and someone else maintains it on another platform."],[70.251,72.054,"Your agent simply points to it,"],[72.054,75.336,"and you can select only the items you have access to."],[75.416,78.944,"Note that Fabric IQ and Work IQ are still in preview."],[79.644,81.871,"Where do these colleagues join the agent?"],[81.951,84.019,"On the Microsoft Copilot harness,"],[84.019,88.167,"which until late October was called the GitHub Copilot harness."],[88.247,92.073,"Same harness, new name, so the exam may still use the old one."],[92.153,96.407,"You open the Build tab and add each capability as a tool, in Tools."],[96.487,99.153,"The orchestrator then decides when to call it,"],[99.153,102.02,"based only on the tool's name and description."],[102.72,105.245,"Foundry IQ is the policy expert."],[105.325,109.843,"It brings curated knowledge, such as policies and authoritative documents,"],[109.843,113.035,"from a knowledge base built in Microsoft Foundry."],[113.115,114.829,"Remember two exam facts."],[114.909,118.373,"An agent can have only one Foundry IQ connection."],[118.453,123.106,"And the connection uses one of four authentication types: API key,"],[123.106,128.381,"client certificate, service principal, or Microsoft Entra ID integrated."],[128.461,132.075,"Every type needs the Foundry IQ search service endpoint."],[132.775,133.849,"Your turn."],[133.929,135.955,"The HR agent uses Foundry IQ,"],[135.955,139.996,"but its answers about leave are strange and incomplete."],[140.076,141.407,"Where do you fix it?"],[141.487,144.183,"By removing the connection and adding it again?"],[144.263,147.769,"In Copilot Studio, by editing the agent instructions?"],[147.849,151.655,"Or in Microsoft Foundry, together with the knowledge base owner?"],[151.735,153.471,"Decide before I answer."],[153.551,156.567,"You tune it in Microsoft Foundry, with the owner."],[156.647,158.393,"The knowledge base lives there,"],[158.393,162.649,"and removing the connection in Copilot Studio does not change it at all."],[163.349,166.982,"Because the orchestrator chooses tools from their descriptions,"],[166.982,169.373,"a vague description is a real problem."],[169.453,173.707,"Two tools may both claim the same question, or neither one gets called."],[173.787,176.483,"So rewrite every description in three parts."],[176.563,177.829,"When to use it."],[177.909,179.133,"What it returns."],[179.213,180.864,"And what it does not handle."],[180.944,185.51,"For example: use for HR policy questions, returns policy text,"],[185.51,188.803,"does not handle salaries or personal data."],[189.503,192.604,"Fabric IQ, in preview, is the numbers expert."],[192.684,196.43,"It grounds your agent in the Microsoft Fabric semantic model,"],[196.43,199.455,"with its measures, hierarchies and dimensions."],[199.535,201.661,"Because the agent uses that model,"],[201.661,206.177,"you do not rebuild the same metrics or data models in Copilot Studio."],[206.257,210.852,"Revenue by region already exists in Fabric, so the agent reuses it."],[210.932,214.03,"You need an agent on the Microsoft Copilot harness"],[214.03,217.575,"and access to the Fabric workspace and semantic model."],[218.275,219.776,"How do you know it worked?"],[219.856,222.834,"Open the Preview tab, keep End user preview off,"],[222.834,226.819,"ask a test question and read the activity trace step by step."],[226.899,230.789,"If there is no Fabric IQ call, check Tools and the description."],[230.869,235.357,"If a different tool was called, the borders between descriptions need to be clearer."],[235.437,238.81,"If you see an error, it is often a failed authentication,"],[238.81,241.909,"so check that the tool's credentials are current."],[242.609,243.684,"Your turn."],[243.764,246.353,"You ask the agent for revenue by region."],[246.433,251.241,"The activity trace shows that the policy tool was called instead of Fabric IQ."],[251.321,252.609,"What do you change?"],[252.689,256.004,"Make the tool descriptions clearer about what each one handles?"],[256.084,259.143,"Remove Fabric IQ and use a knowledge source?"],[259.223,262.751,"Or rebuild the revenue metrics inside Copilot Studio?"],[262.831,264.567,"Decide before I answer."],[264.647,266.276,"Clarify the descriptions."],[266.356,270.119,"The orchestrator picked the wrong tool because the borders were vague."],[270.819,273.813,"Work IQ, in preview, is the teamwork expert."],[273.893,279.135,"It gives the agent context about how people work in Microsoft three six five:"],[279.135,281.581,"files, email, meetings and chats."],[281.661,285.979,"You add it as a Model Context Protocol tool, an MCP tool."],[286.059,289.879,"And it is read-only, unless an administrator turns on write"],[289.879,293.704,"operations in the Microsoft three six five admin center."],[293.784,295.349,"Reading is the default."],[295.429,297.869,"Writing is a deliberate admin choice."],[298.569,301.5,"Work IQ also needs some admin work first."],[301.58,305.343,"A Global Administrator enables it once for the whole tenant."],[305.423,309.633,"The tenant needs a usage based billing plan in Copilot Studio."],[309.713,314.009,"And admins create a separate spending policy for Work IQ usage."],[314.089,319.166,"One more limit: every MCP server counts toward the agent's tool total, and extra"],[319.166,324.252,"servers are skipped for a turn, so keep the number of attached servers small."],[324.952,326.027,"Your turn."],[326.107,328.717,"A maker wants meeting and email context."],[328.797,333.435,"Instead of Work IQ, they add the separate Mail, Teams and OneDrive tools."],[333.515,335.379,"Is that the recommended choice?"],[335.459,338.773,"Is it required, because Work IQ cannot read email?"],[338.853,341.368,"Is it wrong, because those tools are a legacy"],[341.368,344.195,"experience on the standard harness and billing?"],[344.275,347.163,"Or is it fine, because they read the same data?"],[347.243,348.979,"Decide before I answer."],[349.059,350.667,"It is the legacy path."],[350.747,352.419,"Use Work IQ instead."],[353.119,354.535,"So how do you choose?"],[354.615,356.671,"Ask who maintains the context."],[356.751,360.044,"Policies tuned by another team point to Foundry IQ."],[360.124,364.548,"Business measures in a Fabric semantic model point to Fabric IQ."],[364.628,367.559,"Email, files and meetings point to Work IQ."],[367.639,371.785,"Documents you write and update yourself fit a normal knowledge source."],[371.865,376.993,"And a whole domain run by another Copilot Studio agent fits a connected agent."],[377.693,379.003,"Here are the steps."],[379.083,383.827,"Open your agent on the Microsoft Copilot harness and go to the Build tab."],[383.907,385.899,"In Tools, select Add a tool."],[385.979,390.125,"For Foundry IQ, create a new connection, pick the authentication type,"],[390.125,394.115,"enter the search service endpoint and choose the knowledge base."],[394.195,396.741,"For Fabric IQ, select it and add it."],[396.821,400.328,"For Work IQ, go to MCP and pick Work IQ."],[400.408,403.573,"Then rewrite each description and test in Preview."],[404.273,405.348,"Your turn."],[405.428,408.088,"The sales director wants revenue by region,"],[408.088,412.433,"and those measures are already modelled in a Fabric semantic model."],[412.513,414.74,"Which capability should the agent use?"],[414.82,417.516,"A knowledge source with an exported spreadsheet?"],[417.596,420.975,"Work IQ, because the director asks in a Teams chat?"],[421.055,424.839,"Or Fabric IQ, because the measures live in the semantic model?"],[424.919,426.655,"Decide before I answer."],[426.735,428.044,"Fabric IQ."],[428.124,433.316,"The numbers expert reuses the model, so nobody copies or rebuilds the metrics."],[434.016,435.944,"Back to Tuesday at Contoso."],[436.024,441.28,"The leave policy comes from Foundry IQ, tuned by the compliance team in Foundry."],[441.36,446.189,"Revenue by region comes from Fabric IQ and the existing semantic model."],[446.269,448.775,"The renewal meetings come from Work IQ,"],[448.775,452.187,"read-only because the admin did not enable writes."],[452.267,455.841,"Remember for the exam: one Foundry IQ connection,"],[455.841,461,"Work IQ is an MCP tool, and you choose by who maintains the context."]],"quiz":[{"at":151.735,"question":"The agent's Foundry IQ answers about leave are strange and incomplete. Where do you fix it?","options":["Remove the connection and add it again","In Copilot Studio, edit the agent instructions","In Microsoft Foundry, with the knowledge base owner"],"right":2,"trap":1,"answerAt":153.551},{"at":262.831,"question":"You ask for revenue by region. The trace shows the policy tool was called instead of Fabric IQ. What do you change?","options":["Make the tool descriptions clearer","Replace Fabric IQ with a knowledge source","Rebuild the revenue metrics in Copilot Studio"],"right":0,"trap":2,"answerAt":264.647},{"at":347.243,"question":"A maker wants email and meeting context and adds the separate Mail, Teams and OneDrive tools instead of Work IQ. Is that the recommended choice?","options":["Yes, Work IQ cannot read email","No, they are a legacy experience on the standard harness and billing","Yes, they read the same data"],"right":1,"trap":2,"answerAt":349.059},{"at":424.919,"question":"The sales director wants revenue by region, and the measures are already modelled in a Fabric semantic model. Which capability?","options":["A knowledge source with an exported spreadsheet","Work IQ, because the question came in a Teams chat","Fabric IQ"],"right":2,"trap":1,"answerAt":426.735}],"poster":"video/L41.jpg"},"L02":{"src":"video/L02.mp4","duration":434.569,"scenes":[{"start":0},{"start":27.887},{"start":51.011},{"start":75.282},{"start":101.217},{"start":124.975},{"start":158.41},{"start":183.257},{"start":208.383},{"start":231.523},{"start":267.179},{"start":291.706},{"start":319.006},{"start":345.135},{"start":375.605},{"start":402.849}],"cues":[[0.8,3.112,"Contoso builds two agents this week."],[3.192,7.232,"The first one helps employees with IT support, inside Teams."],[7.312,11.861,"The second one helps customers track their orders on the company's web portal,"],[11.861,14.744,"and those customers have no Microsoft account."],[14.824,18.352,"In a hurry, the maker leaves both on No authentication."],[18.432,21.847,"One question decides whether this is fine or a disaster:"],[21.847,23.816,"who is talking to your agent?"],[23.896,27.637,"By the end of this class you will choose the right answer for each one."],[28.337,30.009,"Here is the picture to keep."],[30.089,32.7,"Authentication is the door of a building."],[32.78,35.625,"You can leave the door open, so anyone walks in."],[35.705,39.553,"You can use the company's badge reader, so only employees get in."],[39.633,43.055,"Or you can fit your own lock, with keys you hand out yourself."],[43.135,47.303,"A wrong door either lets strangers in, or locks your real users out."],[47.383,50.761,"Copilot Studio gives you exactly these three doors."],[51.461,53.88,"The first door is No authentication."],[53.96,56.938,"Anyone who has the link can chat with the agent,"],[56.938,59.557,"and the agent has no idea who they are."],[59.637,63.933,"That can be fine for a public agent that only answers general questions."],[64.013,66.532,"But leaving No authentication on an agent"],[66.532,69.803,"that touches internal data is the classic mistake."],[69.883,72.303,"The link gets shared, and strangers now talk"],[72.303,75.032,"to an agent that knows your company's secrets."],[75.732,78.791,"The second door is Authenticate with Microsoft."],[78.871,81.151,"It is the simplest secure option,"],[81.151,86.324,"because Copilot Studio sets up Microsoft Entra ID for you automatically."],[86.404,89.067,"Entra ID is Microsoft's identity service,"],[89.067,92.385,"the badge reader that checks who each person is."],[92.465,95.091,"And in Teams the user is already identified,"],[95.091,97.679,"so they never even see a sign-in screen."],[97.759,100.967,"They just start chatting, and the agent knows who they are."],[101.667,103.509,"Now a rule the exam loves."],[103.589,106.735,"The Teams channel and the Microsoft three six five"],[106.735,110.019,"channel only support Authenticate with Microsoft."],[110.099,113.435,"Not manual authentication, and not your own provider."],[113.515,117.747,"So if the agent must live in Teams, the door is already chosen for you."],[117.827,121.453,"Keep this in mind, because the exam often hides the channel"],[121.453,124.725,"inside a long scenario and expects you to spot it."],[125.425,126.5,"Your turn."],[126.58,132.028,"The IT support agent is for Contoso employees, and it will be published in Teams."],[132.108,134.847,"Which authentication option should the maker choose?"],[134.927,136.876,"Authenticate with Microsoft?"],[136.956,140.804,"Authenticate manually with a generic OAuth two provider?"],[140.884,145.308,"Or No authentication, since everyone in Teams is an employee anyway?"],[145.388,147.124,"Decide before I answer."],[150.704,152.675,"Authenticate with Microsoft."],[152.755,154.626,"Teams only supports that option,"],[154.626,158.16,"and employees are signed in without ever seeing a screen."],[158.86,161.449,"The third door is Authenticate manually."],[161.529,164.839,"You use it when your users do not have a Microsoft account,"],[164.839,167.788,"for example the customers of your own web portal."],[167.868,173.039,"You set up an identity provider yourself, such as a generic OAuth two provider."],[173.119,177.155,"OAuth two is a standard that lets people sign in through an identity"],[177.155,180.679,"provider without sharing their password with your agent."],[180.759,183.007,"It is your own lock, with your own keys."],[183.707,187.789,"Once a door checks people, the agent gets variables about the user."],[187.869,190.245,"User dot ID identifies them."],[190.325,194.515,"User dot display name gives their name, so a topic can greet them."],[194.595,197.931,"User dot is logged in tells you whether sign-in happened."],[198.011,201.383,"And User dot access token holds their access token,"],[201.383,204.227,"which exists with manual authentication."],[204.307,208.133,"You can check in any topic which of these variables are available."],[208.833,210.292,"Why does all this matter?"],[210.372,213.58,"Because identity travels with the whole conversation."],[213.66,216.033,"Thanks to it, the agent can look up orders"],[216.033,218.831,"for the right customer, not for somebody else."],[218.911,221.948,"And it can call tools with that user's own permissions,"],[221.948,225.02,"so people only reach what they are allowed to reach."],[225.1,228.961,"Without identity, the agent cannot tell one person from another,"],[228.961,231.273,"so it cannot protect anyone's data."],[231.973,233.048,"Your turn."],[233.128,237.104,"The order tracking agent lives on Contoso's customer portal."],[237.184,240.034,"Customers sign in with the portal's own accounts,"],[240.034,242.269,"and they have no Microsoft account."],[242.349,243.765,"Which option fits?"],[243.845,247.117,"No authentication, because it is a public website?"],[247.197,251.451,"Authenticate with Microsoft, because it is the simplest secure choice?"],[251.531,255.699,"Or Authenticate manually with a generic OAuth two provider?"],[255.779,257.515,"Decide before I answer."],[261.095,262.703,"Authenticate manually."],[262.783,266.929,"These users have no Microsoft account, so you bring your own provider."],[267.629,270.581,"People have an identity, and now agents do too."],[270.661,274.311,"Since May twenty twenty six, when you create an agent,"],[274.311,279.309,"Copilot Studio automatically creates a Microsoft Entra Agent ID for it."],[279.389,282.981,"It happens when the agent is created, not when you publish it."],[283.061,287.379,"You cannot turn this off for an environment, and you cannot bring your own ID."],[287.459,291.456,"Think of it as the agent getting its own employee badge on day one."],[292.156,296.26,"An Agent ID is a service principal with the subtype Agent."],[296.34,301.703,"The OAuth sign-in flow underneath stays the same, so nothing changes for your users."],[301.783,303.625,"What changes is governance."],[303.705,308.933,"Admins can see the agent in the Microsoft Entra admin center, read its audit logs,"],[308.933,311.93,"manage its life cycle, and target its connector"],[311.93,314.999,"permissions with Conditional Access policies."],[315.079,318.756,"Makers find the ID in Settings, Advanced, Metadata."],[319.456,320.979,"Two limits to remember."],[321.059,327.915,"First, agents made in Agent Builder do not use app registration I Ds or Agent I Ds."],[327.995,330.477,"Only Copilot Studio agents get them."],[330.557,334.149,"Second, every Agent ID is a directory object."],[334.229,337.612,"So if the tenant has reached its directory object quota,"],[337.612,340.168,"the new agent cannot be created at all."],[340.248,344.885,"On the exam, an agent that fails to be created can point to this quota."],[345.585,346.66,"Your turn."],[346.74,352.167,"A maker says: I will worry about the Agent ID later, it only appears when I publish."],[352.247,357.033,"When does Copilot Studio really create the Microsoft Entra Agent ID?"],[357.113,359.617,"When the agent is published to its first channel?"],[359.657,361.543,"Or when the agent is created?"],[361.597,364.677,"Only after an admin enables it for the environment?"],[364.823,366.559,"Decide before I answer."],[370.139,371.875,"When the agent is created."],[371.955,375.355,"It is automatic, and there is no environment opt out."],[376.055,377.364,"Here are the steps."],[377.444,379.799,"Open your agent and go to Settings."],[379.879,382.873,"In the Security section, select Authentication."],[382.953,388.188,"Choose No authentication, Authenticate with Microsoft, or Authenticate manually."],[388.268,392.116,"If you choose manual, fill in the OAuth two provider details."],[392.196,393.655,"Save your changes."],[393.735,396.142,"Then publish the agent, because the change"],[396.142,398.863,"only reaches the channels after you publish."],[398.943,402.599,"Finally, check in a topic which user variables are available."],[403.299,404.757,"Back to Contoso."],[404.837,407.275,"The IT support agent lives in Teams,"],[407.275,412.419,"so it uses Authenticate with Microsoft, and nobody sees a sign-in screen."],[412.499,416.922,"The customer portal agent uses Authenticate manually with OAuth two,"],[416.922,419.269,"and greets each customer by name."],[419.349,425.073,"Remember for the exam: Teams means Microsoft, no Microsoft account means manual,"],[425.073,431.069,"the Agent ID comes at creation, and No authentication never guards internal data."]],"quiz":[{"at":145.388,"question":"An IT support agent for Contoso employees will be published in Teams. Which authentication option?","options":["Authenticate with Microsoft","Authenticate manually with a generic OAuth 2 provider","No authentication, everyone in Teams is an employee"],"right":0,"trap":1,"answerAt":150.704},{"at":255.779,"question":"Customers sign in to the Contoso portal with the portal's own accounts and have no Microsoft account. Which option fits?","options":["No authentication, it is a public website","Authenticate with Microsoft, the simplest secure choice","Authenticate manually with a generic OAuth 2 provider"],"right":2,"trap":1,"answerAt":261.095},{"at":364.823,"question":"When does Copilot Studio create the Microsoft Entra Agent ID?","options":["When the agent is published to its first channel","When the agent is created","After an admin enables it for the environment"],"right":1,"trap":0,"answerAt":370.139}],"poster":"video/L02.jpg"},"L04":{"src":"video/L04.mp4","duration":459.084,"scenes":[{"start":0},{"start":24.455},{"start":48.11},{"start":72.127},{"start":94.371},{"start":117.258},{"start":149.93},{"start":174.435},{"start":200.007},{"start":232.869},{"start":258.422},{"start":284.938},{"start":317.97},{"start":343.649},{"start":377.278},{"start":401.335},{"start":427.809}],"cues":[[0.8,2.472,"Friday at Contoso."],[2.552,4.736,"The HR agent has a rough day."],[4.816,7.213,"Someone sends it an offensive message."],[7.293,11.162,"Another employee asks about a policy that is not in its sources,"],[11.162,13.296,"and the agent invents an answer."],[13.376,17.075,"A third person asks for a coworker's leave balance, and gets it."],[17.155,20.149,"Three bad answers, and each one has a different fix."],[20.229,24.205,"By the end of this class you will know which control stops which problem."],[24.905,26.577,"Here is the picture to keep."],[26.657,30.036,"A generative agent is a tap that writes new answers."],[30.116,34.476,"Responsible AI is the set of controls you add so it speaks safely."],[34.556,39.279,"Content moderation is the filter on the tap: you decide how fine it is."],[39.359,42.35,"Grounding is a different valve: it only lets out water"],[42.35,45.596,"that comes from your own pipes, your sources and tools."],[45.676,47.86,"Two controls, two different jobs."],[48.56,51.875,"Content filtering checks two points in every exchange."],[51.955,53.776,"First, what the user sends."],[53.856,55.891,"Second, what the agent answers."],[55.971,60.995,"If either one is harmful, the exchange is blocked, and the user sees the message:"],[60.995,64.917,"the content was filtered due to Responsible AI restrictions."],[64.997,67.821,"Behind it, the error code is Content Filtered."],[67.901,71.877,"Remember that name, because you will search for it later when you troubleshoot."],[72.577,74.164,"Where do you set the filter?"],[74.244,75.895,"It depends on the harness."],[75.975,80.23,"On the standard harness you can set the moderation level in three places:"],[80.23,84.452,"for the whole agent, for a generative answers node, and for a prompt."],[84.532,88.572,"When they disagree, at runtime the topic's level takes precedence."],[88.652,91.441,"So a strict node inside a topic stays strict,"],[91.441,94.121,"even if the agent level is more relaxed."],[94.821,98.477,"Now the direction of the scale, which the exam loves to twist."],[98.557,103.429,"Highest applies the strictest filter, so the agent generates fewer responses."],[103.509,107.976,"Lowest generates more responses, with more risk of harmful content."],[108.056,110.091,"Highest does not mean more answers."],[110.171,112.845,"It means a finer filter, so less gets through."],[112.925,117.008,"Picture the tap again: the finer the filter, the less water comes out."],[117.708,118.783,"Your turn."],[118.863,122.775,"A maker complains that the agent refuses too many questions."],[122.855,127.556,"They want the level that generates the most responses, and they accept more risk."],[127.636,129.991,"Which content moderation level is that?"],[130.071,133.129,"Medium, because it balances answers and safety?"],[133.209,135.884,"Highest, because it unlocks the most answers?"],[135.964,137.081,"Or Lowest?"],[137.161,138.897,"Decide before I answer."],[142.477,143.488,"Lowest."],[143.568,147.565,"It generates more responses, with more risk of harmful content."],[147.645,149.68,"Highest is the strictest filter."],[150.38,152.446,"On the Microsoft Copilot harness,"],[152.446,156.276,"formerly called the GitHub Copilot harness, it is simpler."],[156.356,159.34,"There is one moderation level for the whole agent,"],[159.34,162.465,"on the AI and behavior tab of the agent settings."],[162.545,166.159,"The levels are minimum, low, medium, high and maximum."],[166.239,169.34,"The change takes effect after you save and publish."],[169.42,174.185,"And because it is one dial, lowering it for one task lowers it for every task."],[174.885,176.813,"Here is a trap from real life."],[176.893,182.069,"On the standard harness, when moderation filters a generative answers node, the node"],[182.069,187.013,"simply returns no answer, and it gives no sign that moderation was the cause."],[187.093,189.149,"The user just sees nothing useful."],[189.229,192.78,"To find out what happened, open the conversation transcripts"],[192.78,196.235,"or Application Insights, and look for Content Filtered."],[196.315,199.757,"That code tells you the filter, not a bug, ate the answer."],[200.457,201.532,"Your turn."],[201.612,204.841,"An agent runs on the Microsoft Copilot harness."],[204.921,209.388,"The maker lowers the moderation level to help one creative writing task."],[209.468,210.82,"What is the effect?"],[210.9,213.809,"Nothing changes until an admin approves it?"],[213.889,219.145,"Every task of the agent uses the lower level, once the maker saves and publishes?"],[219.225,222.241,"Or only that task's node uses the lower level?"],[222.321,224.057,"Decide before I answer."],[227.637,228.861,"Every task."],[228.941,232.619,"On this harness the level is one setting for the whole agent."],[233.319,234.799,"Now the second valve."],[234.879,237.852,"The setting is called allow ungrounded responses."],[237.932,240.893,"An ungrounded response is one that does not"],[240.893,244.191,"rely on any source or tool used in that turn."],[244.271,247.897,"Turn the setting off, and if the agent used no source or tool,"],[247.897,251.724,"the response is blocked and the fallback is triggered instead."],[251.804,253.945,"The fallback is a backup reply."],[254.025,258.172,"This stops the agent from making things up without relying on your data."],[258.872,262.763,"Keep the jobs apart, because the exam mixes them on purpose."],[262.843,266.904,"Allow ungrounded responses does not filter harmful content."],[266.984,270.128,"Temperature does not filter harmful content either."],[270.208,272.093,"Moderation filters harm."],[272.173,274.464,"The grounding setting requires sources."],[274.544,278.669,"So if the problem is invented answers, moderation will not fix it."],[278.749,281.14,"And if the problem is offensive content,"],[281.14,284.688,"turning off ungrounded responses will not fix it either."],[285.388,286.463,"Your turn."],[286.543,291.11,"The HR agent answers questions about policies that are not in its sources,"],[291.11,293.1,"and the answers are invented."],[293.18,294.532,"What fixes this?"],[294.612,297.009,"Turn off allow ungrounded responses?"],[297.089,298.548,"Lower the temperature?"],[298.628,301.132,"Or raise content moderation to Highest?"],[301.212,302.948,"Decide before I answer."],[306.528,308.989,"Turn off allow ungrounded responses."],[309.069,313.835,"With no source or tool in the turn, the response is blocked and the fallback runs."],[313.915,317.72,"Moderation only screens for harm, not for made-up facts."],[318.42,321.948,"Back to the third bad answer: a coworker's leave balance."],[322.028,325.876,"Nothing in that request is harmful, so moderation lets it through."],[325.956,328.311,"Moderation only screens for harm."],[328.391,331.94,"It does not check whether a request fits your company's policies."],[332.02,337.057,"For that you use other controls: instructions that say what the agent must not do,"],[337.057,339.636,"a narrow knowledge scope, the right tools,"],[339.636,343.399,"and permissions, so each user only reaches their own data."],[344.099,345.173,"Your turn."],[345.253,349.27,"Any employee can ask the HR agent for a coworker's leave balance,"],[349.27,350.829,"and the agent answers."],[350.909,352.859,"Which controls should stop this?"],[352.939,355.336,"Turn off allow ungrounded responses?"],[355.416,358.837,"Or instructions, knowledge scope, tools and permissions?"],[358.917,361.336,"Raise content moderation to maximum?"],[361.416,363.152,"Decide before I answer."],[366.732,369.94,"Instructions, knowledge scope, tools and permissions."],[370.02,373.953,"The request is not harmful, so moderation does not see a problem."],[374.033,377.028,"This is a policy question, not a harm question."],[377.728,379.144,"One more good habit."],[379.224,382.667,"Tell users they are talking to an AI, right at the start."],[382.747,387.325,"The recommended practice is to put a notice in the Conversation Start topic,"],[387.325,390.477,"the topic that runs when the conversation begins."],[390.557,394.141,"Something like: I am an artificial intelligence assistant,"],[394.141,396.133,"and my answers are generated."],[396.213,398.705,"The employee then knows who they are talking to,"],[398.705,401.085,"and reads the answers with the right care."],[401.785,404.055,"Here are the steps on the standard harness."],[404.135,407.791,"Open your agent and go to Settings, then Generative AI."],[407.871,411.804,"Under content moderation, choose the level, for example Highest."],[411.884,416.308,"Turn off allow ungrounded responses if you want to require sources."],[416.388,417.335,"Save."],[417.415,420.457,"In the test panel, ask an awkward question and another"],[420.457,423.417,"one outside your sources, and watch what happens."],[423.497,427.559,"Finally, add an AI notice in the Conversation Start topic."],[428.259,430.208,"Back to Friday at Contoso."],[430.288,434.52,"The offensive message is stopped by moderation, at both checkpoints."],[434.6,437.317,"The invented policy is stopped by turning off"],[437.317,440.475,"allow ungrounded responses, so the fallback runs."],[440.555,444.979,"The leave balance is stopped by instructions, knowledge scope and permissions."],[445.059,450.352,"Remember for the exam: Highest filters more, the topic level wins on the standard"],[450.352,455.584,"harness, and one dial rules the whole agent on the Microsoft Copilot harness."]],"quiz":[{"at":137.161,"question":"A maker wants the content moderation level that generates the most responses and accepts more risk. Which one?","options":["Medium, it balances answers and safety","Highest, it unlocks the most answers","Lowest"],"right":2,"trap":1,"answerAt":142.477},{"at":222.321,"question":"On the Microsoft Copilot harness, a maker lowers the moderation level to help one creative task. What is the effect?","options":["Nothing changes until an admin approves it","Every task, after you save and publish","Only that task's node uses the lower level"],"right":1,"trap":2,"answerAt":227.637},{"at":301.212,"question":"The HR agent invents answers about policies that are not in its sources. What fixes it?","options":["Turn off Allow ungrounded responses","Lower the temperature of the model","Raise content moderation to Highest"],"right":0,"trap":2,"answerAt":306.528},{"at":361.416,"question":"Any employee can ask the HR agent for a coworker's leave balance, and it answers. Which controls should stop this?","options":["Turn off Allow ungrounded responses in settings","Instructions, knowledge scope, tools, permissions","Raise content moderation to Maximum for all topics"],"right":1,"trap":2,"answerAt":366.732}],"poster":"video/L04.jpg"},"L06":{"src":"video/L06.mp4","duration":492.992,"scenes":[{"start":0},{"start":26.567},{"start":48.577},{"start":75.743},{"start":98.115},{"start":121.495},{"start":153.778},{"start":181.382},{"start":213.067},{"start":241.053},{"start":268.243},{"start":298.557},{"start":332.935},{"start":357.011},{"start":380.983},{"start":414.551},{"start":435.302},{"start":460.245}],"cues":[[0.8,4.776,"Contoso has three agents: IT, HR and Sales."],[4.856,9.259,"Each one needs the same greeting and the same way to escalate to a human."],[9.339,13.144,"So a maker copies the topics from one agent into the other two."],[13.224,16.624,"A month later, someone fixes a bug in the IT greeting."],[16.704,19.613,"The HR and Sales copies still have the bug."],[19.693,22.517,"Three agents, three versions of the same piece."],[22.597,26.317,"By the end of this class you will know how to share pieces the right way."],[27.017,28.689,"Here is the picture to keep."],[28.769,33.121,"Imagine a box of Lego pieces that every team in the company can use,"],[33.121,35.177,"but nobody can bend or break."],[35.257,37.185,"That is a component collection."],[37.265,39.43,"You package ready made pieces once,"],[39.43,43.652,"and reuse them in several agents, instead of copying and pasting."],[43.732,48.327,"Fix a piece in the box, and every agent that uses the box gets the fix."],[49.027,51.275,"What can a component collection contain?"],[51.355,52.429,"Topics."],[52.509,53.563,"Tools."],[53.643,54.696,"Knowledge."],[54.776,55.808,"Flows."],[55.888,56.92,"Entities."],[57,58.288,"Child agents."],[58.368,60.125,"And MCP servers."],[60.205,63.136,"You make the piece once and use it in many agents."],[63.216,68.114,"For Contoso, one collection called Greeting and escalation holds two topics,"],[68.114,72.76,"Greeting and Escalate to a human, plus one tool called Create ticket."],[72.84,75.493,"All three agents add that one collection."],[76.193,77.844,"Who can change the pieces?"],[77.924,80.547,"Once the collection is available in an agent,"],[80.547,85.527,"all the authors of that agent can use its components, but they cannot change them."],[85.607,87.724,"Only the creator of the collection,"],[87.724,91.311,"or a system customizer or an administrator, can edit it."],[91.391,93.55,"This way nobody breaks the shared piece"],[93.55,96.241,"by accident while working on their own agent."],[96.321,97.865,"The box stays clean."],[98.565,100.387,"Why not just copy and paste?"],[100.467,103.077,"Because copies duplicate and fall out of sync."],[103.157,107.731,"When you fix the original, the copies stay old, exactly like at Contoso."],[107.811,110.08,"Two other ideas also fall short."],[110.16,114.349,"A child agent is not shared between agents, it belongs to one."],[114.429,119.109,"And exporting a whole agent is far too much when you only want a few pieces."],[119.189,121.245,"The collection is the clean answer."],[121.945,123.02,"Your turn."],[123.1,127.792,"Contoso wants the same topics and tool in its IT, HR and Sales agents,"],[127.792,132.281,"and the authors of those agents must not be able to change them."],[132.361,133.863,"What should the maker use?"],[133.943,135.465,"A component collection?"],[135.545,138.156,"Copy the topics by hand into each agent?"],[138.236,142.041,"Or export the whole IT agent and import it three times?"],[142.121,143.857,"Decide before I answer."],[147.437,149.003,"A component collection."],[149.083,153.528,"One source, used everywhere, and consumers cannot edit its components."],[154.228,155.964,"Now the collection grows."],[156.044,159.316,"It starts to include connectors and environment variables."],[159.396,161.196,"How do you move it to production?"],[161.276,164.676,"The recommendation is to use a solution as the carrier."],[164.756,167.254,"A solution is the Power Platform container"],[167.254,170.012,"for moving components between environments."],[170.092,172.276,"You add the collection to a solution,"],[172.276,175.369,"export the solution, and import it in the target."],[175.449,178.81,"Exporting the collection directly packages it as managed,"],[178.81,181.132,"and that is meant for simpler cases."],[181.832,182.907,"Your turn."],[182.987,187.22,"Contoso's collection now includes connectors and environment variables,"],[187.22,190.163,"and it must go from development to production."],[190.243,191.616,"What is recommended?"],[191.696,194.2,"Rebuild the components by hand in production?"],[194.28,197.723,"Export the collection directly, since it is already a package?"],[197.803,202.205,"Or add the collection to a solution, then export and import that solution?"],[202.285,204.021,"Decide before I answer."],[207.601,209.636,"Use a solution as the carrier."],[209.716,212.817,"A direct export is meant for simpler collections."],[213.517,216.64,"On the standard harness you share pieces with a collection."],[216.72,218.952,"On the Microsoft Copilot harness,"],[218.952,223.683,"formerly the GitHub Copilot harness, the reusable piece is a skill."],[223.763,228.165,"A skill has a name, a description, and instructions written in Markdown."],[228.245,232.883,"The orchestrator activates it when a user's request matches the description."],[232.963,235.467,"A skill can also carry supporting files."],[235.547,237.957,"You write it once, add it to many agents,"],[237.957,240.803,"and share it as a Markdown file or a package."],[241.503,244.561,"The description is written for the model, not for people."],[244.641,248.596,"It is the signal the orchestrator matches, so write it for routing."],[248.676,252.104,"The name uses lowercase letters, numbers and hyphens,"],[252.104,256.961,"never starts or ends with a hyphen, and must be unique inside one agent."],[257.041,259.929,"You add a skill in the Build tab, under Skills,"],[259.929,262.263,"as a Markdown file with a front matter"],[262.263,264.66,"block holding the name and description,"],[264.66,267.993,"or as a zip with a skill file and supporting files."],[268.693,270.557,"When is a skill the right choice?"],[270.637,275.234,"When the task is a repeatable pattern, it must run the same way each time,"],[275.234,277.856,"and it will be reused beyond one agent."],[277.936,279.672,"Otherwise pick something else."],[279.752,283.109,"A one off need belongs in the agent instructions."],[283.189,285.523,"A single external action is a tool."],[285.603,289.463,"A fixed sequence with defined inputs and outputs is a workflow,"],[289.463,293.952,"because a workflow enforces the order more strictly than Markdown can."],[294.032,298.307,"A capability with its own owner and life cycle is a connected agent."],[299.007,300.081,"Your turn."],[300.161,304.161,"A process has five steps that must always run in the same order,"],[304.161,308.361,"with defined inputs and outputs, and the order must be enforced."],[308.441,310.647,"A maker wants to write it as a skill."],[310.727,312.015,"What should they use?"],[312.095,313.361,"A single tool?"],[313.441,314.559,"A workflow?"],[314.639,317.292,"Or a skill, because it runs consistently?"],[317.372,319.108,"Decide before I answer."],[322.688,323.805,"A workflow."],[323.885,328.8,"It enforces the order more strictly than Markdown instructions in a skill can."],[328.88,332.685,"A skill guides behavior, a workflow guarantees the sequence."],[333.385,337.297,"A skill travels to other agents, so write portable instructions."],[337.377,340.101,"Restate the tone, the audience and the policy"],[340.101,342.783,"the skill needs, inside the skill itself."],[342.863,345.85,"And avoid hard coding one agent's tools or data,"],[345.85,349.783,"because assumptions from one agent do not travel to another."],[349.863,353.306,"A skill that says use the HR lookup tool breaks the day"],[353.306,356.761,"it lands in the Sales agent, which has no such tool."],[357.461,358.963,"How do you fix a skill?"],[359.043,362.219,"If the upload fails, check for invalid front matter,"],[362.219,365.472,"or a name or description that is missing or empty."],[365.552,369.466,"If the skill fires when it should not, or does not fire when it should,"],[369.466,373.304,"refine the description, because the description is what routes it."],[373.384,377.253,"If it fires but gives the wrong output, refine the instructions."],[377.333,380.733,"To update a skill, edit the source file and use Replace."],[381.433,382.508,"Your turn."],[382.588,386.744,"A refunds skill keeps activating when users ask about shipping times,"],[386.744,388.932,"a request it was never built for."],[389.012,392.263,"Its output for real refund requests is perfect."],[392.343,393.993,"What should the maker refine?"],[394.073,396.385,"The name, so it sounds more specific?"],[396.465,398.543,"The instructions inside the skill?"],[398.623,399.911,"Or the description?"],[399.991,401.727,"Decide before I answer."],[405.307,406.488,"The description."],[406.568,409.733,"It is the routing signal the orchestrator matches."],[409.813,414.301,"Wrong output would mean the instructions, but here the routing is the problem."],[415.001,420.364,"One more feature of the Microsoft Copilot harness: memory, which is in preview."],[420.444,423.012,"The maker turns it on or off for each agent."],[423.092,427.281,"When it is on, the agent keeps a separate memory store for every user."],[427.361,431.615,"So what one person told the agent is never shared with another person."],[431.695,435.052,"Think of a locker per user, not one shared noticeboard."],[435.752,437.68,"Here are the steps for a collection."],[437.76,440.115,"Open your agent and go to Settings."],[440.195,442.379,"Find the component collections section."],[442.459,444.941,"Create a new collection and give it a name."],[445.021,448.571,"Add components, for example a greeting topic and a tool."],[448.651,450.067,"Save the collection."],[450.147,453.269,"Then open another agent and add that collection."],[453.349,457.24,"Finally, check that you can use its components, but not edit them."],[457.32,459.995,"That last check proves the box is protected."],[460.695,462.153,"Back to Contoso."],[462.233,466.601,"The greeting and escalation pieces now live in one collection,"],[466.601,471.521,"used by the IT, HR and Sales agents, and one fix reaches all three."],[471.601,476.217,"When connectors arrived, the collection moved to production inside a solution."],[476.297,480.636,"On the Microsoft Copilot harness, reusable behavior is a skill."],[480.716,485.688,"Remember for the exam: consumers cannot edit, solutions carry heavy collections,"],[485.688,489.492,"and a skill that fires wrongly needs a better description."]],"quiz":[{"at":142.121,"question":"Contoso wants the same topics and tool in its IT, HR and Sales agents, and their authors must not change them. What should the maker use?","options":["A component collection","Copy the topics by hand into each agent","Export the whole IT agent and import it three times"],"right":0,"trap":1,"answerAt":147.437},{"at":202.285,"question":"The collection now includes connectors and environment variables and must move to production. What is recommended?","options":["Rebuild the components by hand in production","Export the collection directly","Add the collection to a solution, then export and import the solution"],"right":2,"trap":1,"answerAt":207.601},{"at":317.372,"question":"Five steps must always run in the same order, with defined inputs and outputs, and the order must be enforced. What should the maker use?","options":["A single tool","A workflow","A skill, because it runs consistently"],"right":1,"trap":2,"answerAt":322.688},{"at":399.991,"question":"A refunds skill keeps activating for questions about shipping times. Its output for real refund requests is perfect. What should the maker refine?","options":["The name, so it sounds more specific","The instructions inside the skill","The description"],"right":2,"trap":1,"answerAt":405.307}],"poster":"video/L06.jpg"},"F03":{"src":"video/F03.mp4","duration":490.727,"scenes":[{"start":0},{"start":28.189},{"start":52.099},{"start":76.775},{"start":99.913},{"start":130.226},{"start":163.922},{"start":187.897},{"start":216.098},{"start":248.17},{"start":273.766},{"start":300.469},{"start":321.899},{"start":352.997},{"start":377.801},{"start":407.291},{"start":438.159},{"start":463.289}],"cues":[[0.8,2.408,"Monday at Contoso."],[2.488,7.109,"An employee writes to Nexo, the IT agent: my laptop will not turn on,"],[7.109,10.389,"and I want to know how my other case is going."],[10.469,12.269,"One message, two wishes."],[12.349,17.072,"Nexo has a topic that creates tickets, and another that checks ticket status."],[17.152,20.04,"Something has to decide what to do with this message."],[20.12,22.539,"That decision is called orchestration."],[22.619,25.877,"By the end of this class you will know the two ways to make it,"],[25.877,27.939,"and the three harnesses behind them."],[28.639,30.311,"Here is the picture to keep."],[30.391,32.596,"Orchestration is a receptionist."],[32.676,35.521,"The classic receptionist has a list of phrases."],[35.601,38.502,"A visitor says something, and the receptionist sends"],[38.502,41.604,"them to the one department whose phrases match best."],[41.684,45.5,"The generative receptionist understands what the person wants,"],[45.5,49.393,"and can send them to several departments, one after another."],[49.473,51.849,"Same building, very different service."],[52.549,55.373,"In standard harness agents there are two modes."],[55.453,59.04,"With classic orchestration, the agent triggers the topic whose"],[59.04,62.48,"trigger phrases are most similar to what the user typed."],[62.56,66.502,"A trigger phrase is an example sentence you write on the topic,"],[66.502,69.267,"like check my ticket or where is my case."],[69.347,74.496,"Nexo's message matches one topic better than the other, so only one topic runs."],[74.576,76.525,"The second wish is simply lost."],[77.225,82.082,"With generative orchestration, the agent uses AI to decide which topic,"],[82.082,85.361,"tool, other agent or knowledge source to use."],[85.441,88.905,"New agents use generative orchestration by default."],[88.985,91.611,"If you create the agent from a prebuilt one,"],[91.611,94.497,"its configuration decides which mode is used."],[94.577,96.477,"So unless something says otherwise,"],[96.477,99.663,"your new agent starts with the generative receptionist."],[100.363,102.013,"What changes in practice?"],[102.093,106.795,"Topics: generative picks them by description, classic by trigger phrases."],[106.875,110.222,"Tools: generative calls them by name and description,"],[110.222,113.453,"classic only calls them explicitly from a topic."],[113.533,116.605,"Knowledge: generative can search it proactively,"],[116.605,120.133,"classic uses it as a fallback when no topic matches."],[120.213,123.976,"Several items: generative combines them in one answer."],[124.056,127.2,"Missing data: generative asks for it on its own."],[127.28,129.976,"And generative writes the response itself."],[130.676,131.751,"Your turn."],[131.831,134.42,"An agent uses classic orchestration."],[134.5,137.86,"A maker adds a tool with a perfect name and description,"],[137.86,141.719,"and expects the agent to choose it on its own when users ask."],[141.799,142.873,"Will it work?"],[142.953,145.457,"Yes, because the description is very clear?"],[145.537,148.319,"No, classic only calls tools from a topic?"],[148.399,151.18,"Or yes, but only as a fallback choice here?"],[151.26,152.996,"Decide before I answer."],[156.576,157.437,"No."],[157.517,161.259,"In classic orchestration tools are only called from a topic."],[161.339,163.672,"Choosing them is a generative skill."],[164.372,167.944,"In generative mode, the most important factor for choosing"],[167.944,172.209,"is the description of each topic, tool, agent or knowledge source."],[172.289,175.86,"The name and the input and output parameters also matter."],[175.94,180.151,"A good description is short, one or two sentences, in active voice."],[180.231,182.479,"It includes keywords the user would say."],[182.559,184.764,"And it also says what it does not do."],[184.844,187.647,"That last part draws the border between neighbours."],[188.347,189.891,"Here is what goes wrong."],[189.971,193.449,"If two descriptions are similar, the agent picks only one,"],[193.449,195.568,"and the result is unpredictable."],[195.648,198.088,"So Contoso writes clearly different ones."],[198.168,203.061,"Ticket status: checks the status of an existing ticket, does not create tickets."],[203.141,207.288,"Create ticket: creates a new ticket, does not check existing ones."],[207.368,210.699,"And when you turn on generative mode in an older agent,"],[210.699,214.715,"Copilot Studio generates descriptions from the trigger phrases."],[214.795,215.848,"Review them."],[216.548,217.623,"Your turn."],[217.703,222.319,"A generative agent has two topics, reset password and unlock account."],[222.399,225.927,"Sometimes one runs, sometimes the other, for the same request."],[226.007,227.551,"What should the maker fix?"],[227.631,230.775,"Switch the agent to classic orchestration instead?"],[230.855,233.487,"Add many more trigger phrases to both topics?"],[233.567,236.156,"Or rewrite both descriptions so they differ?"],[236.236,237.972,"Decide before I answer."],[241.552,243.117,"Rewrite the descriptions."],[243.197,247.92,"In generative mode, overlapping descriptions make selection unpredictable."],[248.62,251.124,"Now watch Nexo in generative mode."],[251.204,252.94,"It detects two intentions."],[253.02,257.316,"It calls Ticket status with the case number it took from the conversation."],[257.396,261.735,"Then it calls Create ticket, and asks only for the data that is still missing."],[261.815,265.663,"Finally it writes a single response that covers both wishes."],[265.743,270.507,"A topic can even return its result as an output variable instead of a message,"],[270.507,273.516,"so the agent combines it with everything else."],[274.216,275.547,"Where is the switch?"],[275.627,280.973,"In Settings, in the generative AI section, under orchestration, an option asks"],[280.973,286.451,"whether to use generative orchestration for the agent's responses: yes or no."],[286.531,290.221,"In a topic's trigger, generative mode shows the agent chooses,"],[290.221,293.515,"with its description, instead of user says a phrase."],[293.595,298.125,"To see what the agent decided, open the test pane and the activity map."],[298.205,300.219,"It shows the plan in real time."],[300.919,303.252,"One more switch, and it is not yours."],[303.332,307.831,"If an administrator turns off generative orchestration in an environment,"],[307.831,311.297,"agents in that environment can only use classic mode."],[311.377,314.741,"So if a maker cannot find generative behavior anywhere,"],[314.741,318.489,"even with the agent setting on yes, check the environment."],[318.569,321.649,"The environment rule wins over the agent's wish."],[322.349,327.499,"Copilot Studio builds agents on more than one harness, the runtime under the agent."],[327.579,331.107,"The standard harness uses rule based topics and flows."],[331.187,333.209,"The Microsoft Copilot harness,"],[333.209,338.13,"formerly called the GitHub Copilot harness, is built for reasoning heavy,"],[338.13,341.77,"multistep work, with skills, memory, a secure sandbox,"],[341.77,344.869,"and usage based billing in Copilot Credits."],[344.949,348.669,"Despite the old name, it is not the GitHub Copilot service."],[348.749,352.747,"The Copilot chat harness extends Microsoft Copilot Chat."],[353.447,356.015,"An agent cannot move between harnesses."],[356.095,359.355,"A Microsoft Copilot harness agent cannot be transferred"],[359.355,362.46,"to the standard harness, and the other way round."],[362.54,367.476,"A working standard agent does not need to move just because a new harness exists."],[367.556,372.577,"Treat a move as re architecture, a rebuild, and do it only for a clear benefit."],[372.657,377.551,"Learn describes the Microsoft Copilot harness as a production ready preview."],[378.251,379.325,"Your turn."],[379.405,382.165,"Contoso's standard harness agent works well."],[382.245,386.285,"A team member wants to switch it to the Microsoft Copilot harness."],[386.365,387.504,"What is true?"],[387.584,390.472,"It cannot be transferred, a move means rebuilding?"],[390.552,393.461,"It moves by itself when the harness leaves preview?"],[393.541,396.003,"Or there is a Settings button that converts it?"],[396.083,397.819,"Decide before I answer."],[401.399,402.985,"It cannot be transferred."],[403.065,407.041,"A move is re architecture, so only do it for a clear benefit."],[407.741,411.611,"On the Microsoft Copilot harness the agent has four tabs."],[411.691,415.944,"Build holds identity, knowledge, tools, skills, model and memory."],[416.024,417.632,"Preview is for testing."],[417.712,420.451,"Evaluate runs test sets that measure quality."],[420.531,425.552,"Monitor shows production health, outcomes, reactions, sessions and credit usage."],[425.632,429.139,"The life cycle is create, build, test, publish, monitor."],[429.219,433.557,"And this harness uses one enhanced orchestration model for all agents,"],[433.557,437.909,"so you cannot configure orchestration like on the standard harness."],[438.609,439.919,"Here are the steps."],[439.999,442.353,"Open your agent and go to Settings."],[442.433,447.519,"In the generative AI section, find orchestration and check that it is set to yes."],[447.599,450.401,"Open a custom topic and look at its trigger."],[450.481,452.935,"Edit the description: one or two sentences"],[452.935,455.823,"that say what it does and what it does not do."],[455.903,457.937,"Check a tool's name and description."],[458.017,463.039,"Then type a request with two intentions in the test pane, and open the activity map."],[463.739,465.027,"Back to Nexo."],[465.107,468.878,"In generative mode, the employee's two wishes became one plan:"],[468.878,472.667,"check the old case, create the new ticket, and answer once."],[472.747,476.94,"Remember for the exam: generative chooses by description and name,"],[476.94,478.856,"classic by trigger phrases."],[478.936,481.76,"In classic, tools run only from topics."],[481.84,484.429,"Overlapping descriptions are unpredictable."],[484.509,487.227,"And agents never move between harnesses."]],"quiz":[{"at":151.26,"question":"An agent uses classic orchestration. A maker adds a tool with a perfect name and description and expects the agent to choose it on its own. Will it?","options":["Yes, because the description is very clear","No, classic only calls tools from a topic","Or yes, but only as a fallback choice here"],"right":1,"trap":0,"answerAt":156.576},{"at":236.236,"question":"A generative agent has two topics, Reset password and Unlock account. For the same request sometimes one runs, sometimes the other. What should the maker fix?","options":["Switch the agent to classic orchestration instead","Add many more trigger phrases to both topics","Or rewrite both descriptions so they differ"],"right":2,"trap":1,"answerAt":241.552},{"at":396.083,"question":"Contoso's standard harness agent works well. A team member wants to switch it to the Microsoft Copilot harness. What is true?","options":["It cannot be transferred, a move means rebuilding","It moves by itself when the harness leaves preview","Or there is a Settings button that converts it"],"right":0,"trap":2,"answerAt":401.399}],"poster":"video/F03.jpg"},"L21":{"src":"video/L21.mp4","duration":416.799,"scenes":[{"start":0},{"start":25.605},{"start":47.251},{"start":71.351},{"start":94.147},{"start":128.715},{"start":151.69},{"start":175.467},{"start":199.314},{"start":222.158},{"start":248.79},{"start":274.847},{"start":302.531},{"start":336.398},{"start":361.887},{"start":389.387}],"cues":[[0.8,2.472,"Thursday at Contoso."],[2.552,6.037,"Employees complain that some of their tickets were never created."],[6.117,10.669,"The IT agent calls a flow named Create ticket, and somewhere it fails."],[10.749,13.821,"On the same day, finance asks a second question:"],[13.821,16.709,"how much are these agent flows costing us?"],[16.789,19.059,"Two questions, one place to look."],[19.139,22.78,"By the end of this class you will know where to find the failed runs,"],[22.78,25.355,"how to fix them, and how the bill is counted."],[26.055,27.727,"Here is the picture to keep."],[27.807,30.887,"A flow in production needs a dashboard, like a car."],[30.967,34.18,"The dashboard tells you whether everything is running fine,"],[34.18,35.796,"and how much fuel you use."],[35.876,38.979,"In Copilot Studio that dashboard has three tabs,"],[38.979,44.481,"and the fuel is measured in Copilot Credits, the unit for Copilot Studio capacity."],[44.561,47.001,"Health on one side, fuel on the other."],[47.701,50.013,"The three tabs each have one job."],[50.093,53.411,"Overview shows the flow details: name, description,"],[53.411,56.864,"connections and owners, plus the most recent runs."],[56.944,60.323,"From Overview you can also turn the flow off or delete it."],[60.403,65.019,"Activity shows the run history, with the status and duration of each run."],[65.099,68.397,"Analytics summarizes the activity: the number of runs,"],[68.397,71.101,"the error rate, and the trends over time."],[71.801,73.516,"Activity is where you work."],[73.596,77.636,"Select a run to open its details and see exactly where it failed."],[77.716,81.057,"You can also select several runs at once to resubmit them,"],[81.057,85.404,"which means sending them again, or to cancel the ones still in progress."],[85.484,89.532,"One more detail for the exam: Analytics can take up to thirty minutes"],[89.532,93.897,"to reflect new runs, so a missing number there is not always a problem."],[94.597,95.672,"Your turn."],[95.752,99.153,"The team wants to see each failed run of Create ticket,"],[99.153,103.248,"open its details, and send the failed runs again after the fix."],[103.328,104.957,"Which tab do they open?"],[105.037,107.733,"Activity, because it keeps all run details?"],[107.813,110.275,"Overview, because it lists the latest runs?"],[110.355,113.051,"Or Analytics, because it charts the error rate?"],[113.131,114.867,"Decide before I answer."],[118.447,119.543,"Activity."],[119.623,124.132,"It holds the full run history, the details of each run, and Resubmit."],[124.212,128.465,"Analytics only gives the numbers, and Overview only the latest runs."],[129.165,130.752,"Watch Contoso do it."],[130.832,133.549,"They open the Activity tab of Create ticket."],[133.629,135.643,"Two runs have the status failed."],[135.723,140.616,"They open the details, and both stopped at the same step: the Dataverse connection."],[140.696,144.821,"They fix the connection, select the two failed runs, and resubmit them."],[144.901,146.573,"The tickets are created."],[146.653,151.44,"Then they open Analytics to watch the error rate come down over the next half hour."],[152.14,153.343,"Now the fuel."],[153.423,156.533,"Each action in an agent flow consumes capacity:"],[156.533,160.108,"thirteen Copilot Credits for every hundred actions."],[160.188,162.822,"Tests in the designer or in the test chat,"],[162.822,165.657,"called test runs, do not consume capacity."],[165.737,170.468,"And users with a Microsoft three six five Copilot license are not charged when"],[170.468,175.217,"the flow is triggered with the trigger called when an agent calls the flow."],[175.917,177.995,"Let us do the math the exam likes."],[178.075,182.264,"Contoso's flow has twenty actions, and it runs five hundred times."],[182.344,185.637,"Twenty times five hundred is ten thousand actions."],[185.717,189.186,"Ten thousand divided by a hundred is a hundred blocks,"],[189.186,191.827,"and each block costs thirteen credits."],[191.907,194.923,"So about one thousand three hundred Copilot Credits."],[195.003,199.064,"The tests they ran earlier in the designer added nothing to that number."],[199.764,202.46,"What happens when prepaid capacity runs out?"],[202.54,204.041,"New runs are blocked."],[204.121,206.668,"The runs already in progress finish normally."],[206.748,210.873,"And the agent keeps responding in interactions that do not use flows."],[210.953,214.567,"The agent does not stop working completely, that is the trap."],[214.647,218.118,"To avoid interruptions, you can link a pay as you go plan,"],[218.118,221.908,"so the flows keep running when the prepaid capacity is gone."],[222.608,223.683,"Your turn."],[223.763,227.461,"In the middle of the day, Contoso's prepaid capacity runs out."],[227.541,228.659,"What happens?"],[228.739,232.139,"The agent stops answering until capacity is added?"],[232.219,234.893,"All runs in progress are cancelled right away?"],[234.973,238.075,"Or new flow runs are blocked, the agent talks on?"],[238.155,239.891,"Decide before I answer."],[243.471,244.631,"The third one."],[244.711,246.724,"Only new flow runs are blocked."],[246.804,248.54,"The agent keeps talking."],[249.24,252.995,"Copilot Credits are the single unit across all three harnesses,"],[252.995,254.923,"but what counts is different."],[255.003,258.176,"On the standard harness, credits are metered per event,"],[258.176,260.856,"at defined rates for each interaction type."],[260.936,263.191,"On the Microsoft Copilot harness,"],[263.191,267.291,"formerly the GitHub Copilot harness, billing is usage based:"],[267.291,270.297,"the language model tokens, the tools called,"],[270.297,274.597,"including knowledge and MCP, and the harness runtime itself."],[275.297,276.863,"The timing differs too."],[276.943,280.988,"Standard and Copilot chat agents accrue credits at runtime only,"],[280.988,283.969,"when a published agent handles interactions."],[284.049,289.284,"The Microsoft Copilot harness is the only one that bills from build time as well."],[289.364,293.212,"So authoring, previewing and evaluating also use credits."],[293.292,297.213,"And the Microsoft three six five Copilot license exception"],[297.213,302.281,"for authenticated users does not apply to the Microsoft Copilot harness."],[302.981,304.056,"Your turn."],[304.136,308.219,"Contoso's makers spent a week authoring and previewing a new agent."],[308.299,311.976,"Nothing was published yet, but Copilot Credits were consumed."],[312.056,314.027,"Which harness is the agent on?"],[314.107,316.077,"The standard harness for agents?"],[316.157,318.213,"The Microsoft Copilot harness?"],[318.293,320.157,"Or the Copilot chat harness?"],[320.237,321.973,"Decide before I answer."],[325.553,327.652,"The Microsoft Copilot harness."],[327.732,330.516,"It is the only one that bills from build time,"],[330.516,333.863,"so authoring, previewing and evaluating use credits."],[333.943,336.148,"The other two bill at runtime only."],[336.848,341.037,"On the Microsoft Copilot harness, four things drive consumption."],[341.117,344.837,"The model, because reasoning models meter premium tokens."],[344.917,347.955,"The organizational context the agent draws in."],[348.035,349.941,"The number of tools and actions."],[350.021,352.824,"And the complexity of the task and orchestration."],[352.904,357.553,"A Copilot Credits estimator helps you plan from representative scenarios,"],[357.553,361.637,"but treat its results as directional, a compass, not a quote."],[362.337,363.647,"Here are the steps."],[363.727,368.129,"In Copilot Studio, open the flows list and select your agent flow."],[368.209,372.271,"Review Overview: name, connections, owners and recent runs."],[372.351,376.433,"Go to Activity and review the status and duration of each run."],[376.513,379.252,"Select a failed run and open its details."],[379.332,382.007,"Select the failed runs and use Resubmit."],[382.087,385.359,"Open Analytics for the number of runs and the error rate."],[385.439,389.137,"Then estimate the cost at thirteen credits per hundred actions."],[389.837,391.296,"Back to Contoso."],[391.376,393.626,"The missing tickets were found in Activity,"],[393.626,395.971,"fixed at the connection, and resubmitted."],[396.051,398.478,"Finance got its number: about one thousand"],[398.478,401.221,"three hundred credits for five hundred runs."],[401.301,405.142,"Remember for the exam: Activity is history and resubmit,"],[405.142,407.543,"an empty tank blocks only new runs,"],[407.543,413.299,"test runs are free, and only the Microsoft Copilot harness bills from build time."]],"quiz":[{"at":113.131,"question":"The team wants to see each failed run of Create ticket, open its details, and send the failed runs again after the fix. Which tab do they open?","options":["Activity, because it keeps all run details","Overview, because it lists the latest runs","Analytics, because it charts the error rate"],"right":0,"trap":2,"answerAt":118.447},{"at":238.155,"question":"In the middle of the day, Contoso's prepaid capacity runs out. What happens?","options":["The agent stops answering until capacity is added","All runs in progress are cancelled right away","New flow runs are blocked, the agent talks on"],"right":2,"trap":0,"answerAt":243.471},{"at":320.237,"question":"Contoso's makers spent a week authoring and previewing a new agent. Nothing was published yet, but Copilot Credits were consumed. Which harness is the agent on?","options":["The standard harness for agents","The Microsoft Copilot harness","The Copilot chat harness"],"right":1,"trap":0,"answerAt":325.553}],"poster":"video/L21.jpg"},"L35":{"src":"video/L35.mp4","duration":420.441,"scenes":[{"start":0},{"start":23.922},{"start":45.827},{"start":69.413},{"start":93.641},{"start":117.423},{"start":149.157},{"start":173.297},{"start":194.045},{"start":216.95},{"start":249.019},{"start":273.869},{"start":296.006},{"start":322.303},{"start":350.246},{"start":385.579}],"cues":[[0.8,2.408,"Monday at Contoso."],[2.488,6.933,"On Friday the team gave Nexo, the IT agent, new instructions."],[7.013,9.795,"This morning someone says the answers got worse."],[9.875,11.781,"Someone else says they got better."],[11.861,15.965,"Nobody can prove anything, because nobody measured before the change."],[16.045,17.44,"Everyone is guessing."],[17.52,20.838,"By the end of this class you will know how to build a test set,"],[20.838,23.672,"so the next change is measured instead of guessed."],[24.372,26.044,"Here is the picture to keep."],[26.124,28.201,"A test set is a student's exam."],[28.281,31.101,"Each case is a question, and sometimes it also"],[31.101,34.305,"carries the expected answer, like the answer key."],[34.385,38.084,"The trick is to give the same exam again after every change."],[38.164,42.183,"If the student scores better on the same exam, the student improved."],[42.263,45.577,"If you change the exam each time, the scores say nothing."],[46.277,48.035,"A case comes in two kinds."],[48.115,51.584,"A single response case is one question and one answer,"],[51.584,53.968,"like where do I reset my password."],[54.048,58.686,"A conversation case has several turns, like a user who asks for a laptop,"],[58.686,62.952,"then answers a question about the model, then asks for delivery."],[63.032,64.967,"Use single responses for facts,"],[64.967,69.163,"and conversations when the agent must keep context across turns."],[69.863,72.58,"The fastest way to fill a test set is a file."],[72.66,79.004,"You import a CSV or a TXT file with two headers: Question and Expected response."],[79.084,80.756,"There are limits to remember."],[80.836,82.903,"Up to one hundred questions per file,"],[82.903,85.729,"and up to one thousand characters per question."],[85.809,88.749,"Contoso exports forty real support questions,"],[88.749,93.391,"writes the expected answer next to each, and imports them in one go."],[94.091,96.232,"Here is the detail the exam loves."],[96.312,99.413,"Expected responses are optional when you import."],[99.493,101.656,"The file is accepted without them."],[101.736,105.992,"But some test methods compare the agent's answer with the expected one:"],[105.992,109.189,"Compare meaning, Text similarity, and Exact match."],[109.269,112.925,"Without an answer key, those methods have nothing to compare with."],[113.005,117.173,"General quality is different, it grades the answer without needing one."],[117.873,118.948,"Your turn."],[119.028,122.961,"Contoso imported a CSV with only the Question column."],[123.041,125.14,"Now they want to use Exact match."],[125.22,126.892,"What must they fix first?"],[126.972,129.967,"Split the file into two smaller TXT files?"],[130.047,132.721,"Change each case into a conversation case?"],[132.801,135.476,"Or fill an Expected response for each row?"],[135.556,137.292,"Decide before I answer."],[140.872,143.376,"Fill an Expected response for each row."],[143.456,145.832,"Exact match compares with the answer key."],[145.912,148.907,"File size and case type are not the problem."],[149.607,151.684,"You can also generate cases."],[151.764,155.801,"Quick question set writes ten questions from the agent description,"],[155.801,157.809,"a good first draft in seconds."],[157.889,161.64,"Or generate from knowledge: text, Word, Excel, PDF,"],[161.64,166.473,"or SharePoint files, up to five megabytes each, and no folders."],[166.553,169.991,"The questions then come from the content Nexo really knows,"],[169.991,173.047,"so you test its sources and not only its wording."],[173.747,176.357,"The best questions come from real users."],[176.437,180.479,"On the Monitor page, in preview, you can take the real topics people"],[180.479,184.424,"talk about and use the Evaluate action to turn them into cases."],[184.504,189.056,"Now the exam looks like Monday morning, not like the makers' imagination."],[189.136,193.795,"A good test set starts from real traffic, and prefers coverage over polish."],[194.495,196.807,"Not every agent can take the exam."],[196.887,202.612,"Only agents with No authentication or Authenticate with Microsoft are evaluated."],[202.692,204.88,"If the agent needs a signed in user,"],[204.88,208.908,"you choose a test user profile, and the run uses that identity."],[208.988,214.287,"And one kind of agent is out completely: Fabric data agents cannot be evaluated."],[214.367,216.7,"Check this before you build a single case."],[217.4,218.475,"Your turn."],[218.555,222.68,"Contoso has three agents and wants to evaluate one of them today."],[222.76,224.517,"Which one can take the exam?"],[224.597,227.357,"The one using Authenticate with Microsoft?"],[227.437,230.155,"The one where makers Authenticate manually?"],[230.235,233.251,"Or the Fabric data agent of the finance team?"],[233.331,235.067,"Decide before I answer."],[238.647,243.071,"The one using Authenticate with Microsoft, with a test user profile."],[243.151,248.769,"Manual authentication is not supported, and Fabric data agents cannot be evaluated."],[249.469,251.845,"So far this is the standard harness."],[251.925,256.59,"On the Microsoft Copilot harness, formerly GitHub Copilot harness,"],[256.59,260.253,"evaluation lives in the Evaluate tab, in preview."],[260.333,261.771,"The cycle is a loop."],[261.851,265.301,"Create a test set, configure and run it, review the results,"],[265.301,268.088,"change the agent, and run the same set again."],[268.168,271.653,"Reusing the same set is what makes two runs comparable."],[271.733,273.619,"Same exam, every time."],[274.319,276.225,"That tab uses its own words."],[276.305,280.623,"A test set is a collection of conversations, also called test cases."],[280.703,286.087,"A conversation has user messages and, optionally, an expected agent response."],[286.167,290.1,"And an evaluation is a named test set plus a test method."],[290.18,292.343,"So when a question says evaluation,"],[292.343,295.756,"think of the pair: which exam, and how it is graded."],[296.456,298.896,"There are three ways to add conversations."],[298.976,303.4,"Upload a CSV, up to five megabytes, and a template is available."],[303.48,307.809,"Generate with AI: Quick conversation set creates ten conversations"],[307.809,311.616,"from the agent's description, instructions, and topics."],[311.696,317.165,"After a first run, the menu also offers Generate twenty five and Generate fifty."],[317.245,322.053,"Or write the questions yourself, which is still the best way to cover edge cases."],[322.753,324.361,"Two practical details."],[324.441,328.887,"Actions that cost money show a badge that says Uses Copilot Credits."],[328.967,334.381,"And identity: the agent must use No authentication or Authenticate with Microsoft,"],[334.381,338.212,"and Authenticate manually is not supported here either."],[338.292,341.028,"The User profile setting decides who runs"],[341.028,344.231,"the evaluation and invokes the agent's tools."],[344.311,346.644,"By default it is the signed in user."],[346.724,349.996,"Do not mix these limits with the standard harness numbers."],[350.696,351.771,"Your turn."],[351.851,355.218,"Nexo now runs on the Microsoft Copilot harness,"],[355.218,360.648,"and Contoso wants to upload a file of real questions to the Evaluate tab."],[360.728,362.123,"Which limit applies?"],[362.203,365.283,"One hundred questions of one thousand characters?"],[365.363,369.04,"A single CSV file up to five megabytes in size?"],[369.12,372.349,"Or twenty five conversations until the first run?"],[372.429,374.165,"Decide before I answer."],[377.745,380.015,"A CSV up to five megabytes."],[380.095,385.329,"One hundred questions is the standard harness, and twenty five is a generate option."],[386.029,387.275,"Back to Monday."],[387.355,391.881,"This time Contoso ran the same test set before and after the new instructions,"],[391.881,394.808,"and the scores settle the argument in a minute."],[394.888,396.347,"Remember for the exam."],[396.427,400.351,"Standard harness: CSV or TXT, one hundred questions,"],[400.351,405.757,"one thousand characters each, and expected responses for Exact match."],[405.837,411.627,"Only No authentication or Authenticate with Microsoft, no Fabric data agents."],[411.707,416.941,"Evaluate tab: five megabytes, ten conversations, then twenty five or fifty."]],"quiz":[{"at":135.556,"question":"Contoso imported a CSV with only the Question column. Now they want to use Exact match. What must they fix first?","options":["Split the file into two smaller TXT files","Change each case into a conversation case","Fill an Expected response for each row"],"right":2,"trap":0,"answerAt":140.872},{"at":233.331,"question":"Contoso has three agents and wants to evaluate one of them today. Which one can take the exam?","options":["The one using Authenticate with Microsoft","The one where makers Authenticate manually","The Fabric data agent of the finance team"],"right":0,"trap":1,"answerAt":238.647},{"at":372.429,"question":"Nexo now runs on the Microsoft Copilot harness, and Contoso wants to upload a file of real questions to the Evaluate tab. Which limit applies?","options":["One hundred questions of one thousand characters","A single CSV file up to five megabytes in size","Twenty five conversations until the first run"],"right":1,"trap":0,"answerAt":377.745}],"poster":"video/L35.jpg"},"L36":{"src":"video/L36.mp4","duration":443.976,"scenes":[{"start":0},{"start":26.445},{"start":49.505},{"start":74.181},{"start":100.054},{"start":123.386},{"start":156.695},{"start":178.299},{"start":204.429},{"start":228.166},{"start":251.586},{"start":284.514},{"start":310.902},{"start":336.493},{"start":356.771},{"start":379.357},{"start":412.111}],"cues":[[0.8,2.408,"Tuesday at Contoso."],[2.488,6.528,"Nexo, the IT agent, answers a question about an order."],[6.608,9.965,"The expected code is CT four four seven one."],[10.045,12.656,"Nexo says CT four four one seven."],[12.736,16.441,"The evaluation shows green, because the method graded the meaning,"],[16.441,18.269,"and the meaning looked close."],[18.349,20.576,"In real life, that is a wrong order."],[20.656,22.136,"The test set was fine."],[22.216,23.952,"The grading rule was wrong."],[24.032,26.195,"Today you learn to pick the right one."],[26.895,28.268,"Keep this picture."],[28.348,31.471,"Evaluating an agent is like grading an exam."],[31.551,33.909,"First you decide what you want to measure:"],[33.909,36.636,"the meaning, the exact words, a tool, safety."],[36.716,39.092,"Then you choose the grader with the right rule."],[39.172,42.252,"Some graders give a score, and you set the pass mark."],[42.332,44.388,"Others only say pass or fail."],[44.468,49.255,"Each test set can have several methods, and the wrong one gives misleading results."],[49.955,52.8,"The first grader is already on every test set."],[52.88,55.555,"General quality is turned on by default."],[55.635,58.899,"A language model grades each answer out of one hundred,"],[58.899,63.728,"looking at four things: relevance, groundedness, completeness, and abstention."],[63.808,67.205,"It needs no expected response, so it works from day one,"],[67.205,69.832,"even before anyone writes an answer key."],[69.912,73.931,"It is a good first check, but it judges quality, not exact facts."],[74.631,77.327,"The next two graders both read the answer key."],[77.407,80.896,"Compare meaning checks whether the answer has the same intent"],[80.896,84.241,"as the expected response, so different wording is fine."],[84.321,86.42,"Its default pass score is fifty."],[86.5,89.815,"Text similarity is stricter about the words themselves."],[89.895,94.532,"It measures how close the wording is, with a cosine score from zero to one."],[94.612,97.552,"Use meaning for policies explained in your own words,"],[97.552,99.804,"similarity when the phrasing matters."],[100.504,102.112,"Now the strict graders."],[102.192,105.392,"Exact match wants the answer character by character,"],[105.392,108.792,"so it is ideal for order codes, prices, and numbers."],[108.872,112.891,"Keyword match only looks for the words you list, and you choose Any or All."],[112.971,117.544,"With All, every expected word or phrase must appear for the case to pass."],[117.624,120.249,"These two give no score, only pass or fail,"],[120.249,123.136,"so use them when you need a clear yes or no."],[123.836,124.911,"Your turn."],[124.991,127.824,"Contoso wants to be sure Nexo returns the order"],[127.824,130.737,"code with every character in the right place."],[130.817,132.468,"Which method should they add?"],[132.548,135.692,"Compare meaning with its default pass score of fifty?"],[135.772,138.98,"Exact match with the code as expected response?"],[139.06,142.183,"Or General quality, which is turned on by default?"],[142.263,143.999,"Decide before I answer."],[147.579,148.824,"Exact match."],[148.904,151.301,"Codes must match character by character."],[151.381,156.445,"Compare meaning tolerates near misses, and General quality needs no answer key."],[157.145,160.46,"Some answers are right only if the agent did something."],[160.54,162.78,"When a user reports a broken laptop,"],[162.78,166.713,"Nexo should call the Create Ticket tool, not just say sorry."],[166.793,171.559,"Tool use checks whether the expected tools or topics were used in the response."],[171.639,174.569,"You list them on the case, and the grader looks for them."],[174.649,178.049,"Like Exact match, it gives pass or fail, with no score."],[178.749,180.677,"Next, the safety inspector."],[180.757,184.218,"Content safety checks answers for four kinds of harm:"],[184.218,187.421,"hate, sexual content, violence, and self harm."],[187.501,190.539,"You set a severity threshold from zero to seven."],[190.619,194.104,"Zero is the strictest, and seven is the most permissive."],[194.184,195.856,"It gives pass or fail."],[195.936,199.766,"One detail the exam likes: you add one Content safety method"],[199.766,204.179,"for each type of content, so checking all four means four methods."],[204.879,207.553,"When no built in grader fits, write your own."],[207.633,209.647,"A Custom method has two parts."],[209.727,214.108,"First, instructions that tell the grader what to judge, in plain language."],[214.188,218.569,"Second, at least two labels, and each label is marked as pass or fail."],[218.649,222.876,"Contoso writes, check that Nexo follows the HR privacy policy,"],[222.876,227.916,"with the labels Compliant, marked pass, and Non compliant, marked fail."],[228.616,229.883,"Here is the trap."],[229.963,234.216,"Some questions Nexo must refuse, like what does my manager earn."],[234.296,236.587,"A good refusal is the right answer."],[236.667,240.903,"But General quality can flag a correct refusal as needing improvement,"],[240.903,243.523,"even when it is exactly what you wanted."],[243.603,247.493,"So for cases where the agent should refuse, use a Custom method."],[247.573,251.336,"Your labels decide that a polite, correct refusal is a pass."],[252.036,253.111,"Your turn."],[253.191,257.124,"Nexo must refuse every question about salaries, and it does."],[257.204,261.649,"But General quality keeps marking those refusals as needing improvement."],[261.729,263.316,"What should Contoso do?"],[263.396,265.964,"Set the Content safety threshold to zero?"],[266.044,268.228,"Add Keyword match with the All option?"],[268.308,270.769,"Or create a Custom method with two labels?"],[270.849,272.585,"Decide before I answer."],[276.165,277.773,"Create a Custom method."],[277.853,280.357,"Expected refusals need your own rule."],[280.437,284.264,"Content safety and keywords do not judge a correct refusal."],[284.964,286.7,"A grader needs material."],[286.78,290.901,"If a case is missing what the method needs, an expected response,"],[290.901,293.828,"keywords, or tools, the result is not fail."],[293.908,295.153,"It is Invalid."],[295.233,296.905,"Also check the set type."],[296.985,300.011,"Compare meaning, Text similarity, Exact match,"],[300.011,303.5,"and Tool use work only with single response cases."],[303.58,308.089,"Keyword match and Custom work with single responses and conversations."],[308.169,310.652,"After a run, always look for Invalid."],[311.352,314.112,"Everything so far is the standard harness."],[314.192,318.76,"On the Microsoft Copilot harness, formerly GitHub Copilot harness,"],[318.76,323.459,"the Evaluate tab has only one test method today: General quality."],[323.539,328.337,"It is an AI based check of quality standards like relevance and completeness,"],[328.337,330.843,"and each test case gets pass or fail."],[330.923,336.243,"Compare meaning, Exact match, Tool use, and the rest belong to the standard harness."],[336.943,340.095,"Because the check is AI based, and the agent is too,"],[340.095,343.628,"the same case can pass on one run and fail on the next."],[343.708,345.423,"That is not a broken test."],[345.503,347.473,"It is how these systems behave."],[347.553,351.82,"So run your important scenarios more than once before you trust a result,"],[351.82,356.521,"and compare the runs on the same test set, as you learned in the last lesson."],[357.221,358.467,"One more limit."],[358.547,361.72,"A General quality pass does not show which knowledge"],[361.72,364.848,"sources Nexo used, or whether a tool really ran."],[364.928,367.688,"The answer could read well and still skip the tool."],[367.768,370.776,"For evidence, open the activity trace in the Preview"],[370.776,373.579,"tab and look at the Knowledge and Tool nodes."],[373.659,376.691,"The conversation history shows which model answered,"],[376.691,379.107,"and the Monitor tab shows the credits."],[379.807,380.881,"Your turn."],[380.961,385.343,"On the Microsoft Copilot harness, Nexo passes General quality."],[385.423,388.503,"The manager wants proof the Create Ticket tool ran."],[388.583,389.764,"Where do you look?"],[389.844,392.369,"The Tool node in the Preview activity trace?"],[392.449,395.401,"A Tool use method added to the Evaluate tab?"],[395.481,398.732,"Or a second evaluation run that also shows pass?"],[398.812,400.548,"Decide before I answer."],[404.128,405.821,"The Tool node in the trace."],[405.901,408.781,"The Evaluate tab offers only General quality,"],[408.781,411.861,"and a second pass proves nothing about tools."],[412.561,414.084,"Back to the order code."],[414.164,419.868,"Contoso adds Exact match, and CT four four one seven now fails, as it should."],[419.948,421.407,"Remember for the exam."],[421.487,423.713,"Codes and numbers, Exact match."],[423.793,426.447,"Same idea in other words, Compare meaning."],[426.527,428.284,"A tool call, Tool use."],[428.364,430.356,"Expected refusals, Custom."],[430.436,432.364,"Missing material, Invalid."],[432.444,434.436,"Safety, zero is strictest."],[434.516,436.994,"And on the Microsoft Copilot harness,"],[436.994,440.476,"General quality is the only method, pass or fail."]],"quiz":[{"at":142.263,"question":"Contoso wants to be sure Nexo returns the order code with every character in the right place. Which method should they add?","options":["Compare meaning with its default pass score of fifty","Exact match with the code as expected response","General quality, which is turned on by default"],"right":1,"trap":0,"answerAt":147.579},{"at":270.849,"question":"Nexo must refuse every question about salaries, and it does. General quality keeps marking those refusals as needing improvement. What should Contoso do?","options":["Set the Content safety threshold to zero","Add Keyword match with the All option","Create a Custom method with two labels"],"right":2,"trap":0,"answerAt":276.165},{"at":398.812,"question":"On the Microsoft Copilot harness, Nexo passes General quality. The manager wants proof the Create Ticket tool ran. Where do you look?","options":["The Tool node in the Preview activity trace","A Tool use method added to the Evaluate tab","A second evaluation run that also shows Pass"],"right":0,"trap":1,"answerAt":404.128}],"poster":"video/L36.jpg"},"L37":{"src":"video/L37.mp4","duration":413.016,"scenes":[{"start":0},{"start":23.727},{"start":46.449},{"start":70.829},{"start":102.925},{"start":123.459},{"start":147.647},{"start":170.019},{"start":201.729},{"start":231.125},{"start":255.939},{"start":289.147},{"start":309.407},{"start":329.118},{"start":360.529},{"start":381.471}],"cues":[[0.8,2.408,"Monday at Contoso."],[2.488,6.456,"Over the weekend, the maker rewrote the instructions of Nexo,"],[6.456,9.323,"the IT agent, and ran the test set again."],[9.403,11.885,"Monday morning, twelve cases are red."],[11.965,16.645,"The first instinct is to rewrite the instructions again, and run again, and hope."],[16.725,19.933,"But the real cause is not in the instructions at all."],[20.013,23.477,"Today you learn to read the results before you change anything."],[24.177,25.551,"Keep this picture."],[25.631,28.903,"Reading results is like reviewing a graded exam."],[28.983,30.676,"You don't only look at the score."],[30.756,32.364,"You ask three questions."],[32.444,34.351,"What result did each answer get?"],[34.431,36.124,"Why did it get that result?"],[36.204,39.199,"And did this exam improve compared with the last one?"],[39.279,42.576,"Copilot Studio gives you one tool for each question:"],[42.576,46.199,"the result itself, the activity map, and Compare with."],[46.899,49.147,"Every case gets one of four results."],[49.227,53.352,"Pass and Fail are the grades you expect: the method judged the answer."],[53.432,56.864,"Invalid means the case is missing what the method needs,"],[56.864,59.883,"like an expected response, keywords, or tools."],[59.963,64.557,"Error means an execution failure while evaluating, so there is no grade at all."],[64.637,67.568,"Only Pass and Fail say something about the answer."],[67.648,70.579,"Invalid and Error tell you to look at the run first."],[71.279,72.353,"Your turn."],[72.433,76.431,"Contoso raises the Compare meaning pass score to ninety five."],[76.511,80.615,"Cases that have an expected response now score below that bar."],[80.695,82.708,"What result do those cases get?"],[82.788,85.271,"Invalid, because the bar is too demanding?"],[85.351,87.748,"Error, because the method could not decide?"],[87.828,90.439,"Or Fail, because they scored below the bar?"],[90.519,92.255,"Decide before I answer."],[95.835,96.76,"Fail."],[96.84,100.176,"The case had everything the method needs, so it was graded."],[100.256,102.675,"Invalid is only for missing material."],[103.375,106.817,"When one case confuses you, open Show activity map."],[106.897,110.513,"It shows the sequence of decisions Nexo made in that case,"],[110.513,112.708,"step by step, until it answered."],[112.788,115.75,"Here, the user asked how to reconnect the VPN,"],[115.75,119.943,"and the map shows Nexo went to the Password reset topic first."],[120.023,123.209,"Now you know why the answer was wrong, instead of guessing."],[123.909,126.285,"To measure a change, use Compare with."],[126.365,129.808,"It puts two runs of the same test set side by side."],[129.888,132.021,"Arrows mark the cases that changed,"],[132.021,135.208,"from failing to passing, or the other way around."],[135.288,139.024,"Contoso edits the instructions, runs the same set again,"],[139.024,142.293,"and sees five cases improve and one get worse."],[142.373,144.536,"That one is the next case to open."],[144.616,147.397,"Compare with only makes sense on the same test set."],[148.097,149.94,"Results do not stay forever."],[150.02,154.316,"Copilot Studio keeps evaluation results for eighty nine days."],[154.396,157.753,"To keep them longer, export them to a CSV file."],[157.833,161.473,"Each row has the question, the expected response, the method,"],[161.473,165.372,"the score, the agent's response, the result, and the analysis."],[165.452,169.769,"That file is your history, for audits and for comparisons months later."],[170.469,171.544,"Your turn."],[171.624,177.264,"Contoso's auditors want this quarter's evaluation results available for a full year."],[177.344,178.845,"What should the maker do?"],[178.925,181.899,"Export the results to CSV after each run?"],[181.979,184.845,"Ask an admin to extend the result retention?"],[184.925,187.429,"Or use Compare with to merge the older runs?"],[187.509,189.245,"Decide before I answer."],[192.825,194.433,"Export to CSV."],[194.513,198.66,"Results stay eighty nine days, and exporting is how you keep them longer."],[198.74,201.479,"Compare with only puts two runs side by side."],[202.179,204.939,"Everything so far is the standard harness."],[205.019,209.456,"On the Microsoft Copilot harness, formerly GitHub Copilot harness,"],[209.456,211.875,"results live in the Evaluate tab."],[211.955,213.883,"Each run is saved separately."],[213.963,218.685,"To run a set again, open Recent results, then Evaluate test set again."],[218.765,221.865,"The summary shows Score, Duration, Test cases,"],[221.865,224.896,"Data type, User profile, and Credits used."],[224.976,228.845,"Duration is the whole run, not how fast the agent answered."],[228.925,230.875,"Measure latency in Preview."],[231.575,234.74,"On this harness, a fail can come from three places."],[234.82,238.263,"The evaluation setup, owned by the evaluation author."],[238.343,241.785,"The agent configuration, owned by the agent builder."],[241.865,245.223,"Or a platform limitation, owned by the platform team."],[245.303,246.868,"Check the setup first."],[246.948,248.748,"Are the dependencies healthy?"],[248.828,251.908,"Is the authentication valid for the user profile?"],[251.988,253.788,"Is it the right environment?"],[253.868,255.689,"Only then blame the agent."],[256.389,257.464,"Your turn."],[257.544,258.789,"Back to Monday."],[258.869,260.883,"Twelve cases fail overnight."],[260.963,263.244,"All of them call the Create Ticket tool,"],[263.244,266.752,"and the connection for the user profile expired yesterday."],[266.832,268.653,"What should the maker do first?"],[268.733,271.408,"Rewrite the instructions and run the set again?"],[271.488,274.184,"Restore the connection and rerun the same set?"],[274.264,276.853,"Or improve the Create Ticket tool description?"],[276.933,278.669,"Decide before I answer."],[282.249,284.22,"Restore the connection and rerun."],[284.3,286.996,"An expired connection is a setup issue."],[287.076,288.897,"Leave the instructions alone."],[289.597,293.296,"When the agent really is the cause, match the symptom to the fix."],[293.376,296.627,"Low General quality means improve the instructions."],[296.707,300.917,"Missing or incorrect tool use means improve the tool descriptions."],[300.997,304.312,"Incorrect information means check the knowledge sources."],[304.392,309.157,"Change one thing, run the same set again, and use Compare with to see the effect."],[309.857,312.127,"With many failures, you need an order."],[312.207,314.22,"First, safety and compliance."],[314.3,318.617,"Then the core business scenarios, the ones Contoso cannot work without."],[318.697,320.775,"Then the lowest scoring evaluation."],[320.855,323.231,"Last, the failures that keep coming back."],[323.311,326.113,"A low score on the cafeteria menu can wait."],[326.193,328.868,"An answer that breaks a privacy rule cannot."],[329.568,330.643,"Your turn."],[330.723,333.205,"After a run, Nexo has three failures."],[333.285,337.046,"A vague answer about the cafeteria menu, a wrong order status,"],[337.046,340.461,"and an answer that shares an employee's home address."],[340.541,342.384,"Which one do you triage first?"],[342.464,344.947,"The wrong order status in a core scenario?"],[345.027,347.488,"The vague menu answer with the lowest score?"],[347.568,350.051,"Or the answer sharing an employee's address?"],[350.131,351.867,"Decide before I answer."],[355.447,356.735,"The shared address."],[356.815,360.279,"Safety and compliance come first, then core scenarios."],[360.979,362.885,"One last number: credits."],[362.965,365.683,"Evaluation runs use Copilot Credits."],[365.763,370.635,"The credits you see in Evaluate and in Preview are estimates, close to real time."],[370.715,373.966,"The final, accurate consumption appears in the Monitor"],[373.966,377.357,"tab within a few hours, after the usage is processed."],[377.437,381.221,"So for the real number, check Monitor later, not the run summary."],[381.921,383.167,"Back to Monday."],[383.247,385.596,"The maker leaves the instructions alone,"],[385.596,388.908,"restores the connection, and runs the same set again."],[388.988,392.516,"Compare with shows the twelve cases going from fail to pass."],[392.596,394.055,"Remember for the exam."],[394.135,396.916,"Four results: Pass, Fail, Invalid, Error."],[396.996,400.012,"A demanding pass score gives Fail, not Invalid."],[400.092,402.297,"Activity map explains one case."],[402.377,404.199,"Compare with measures a change."],[404.279,406.484,"Eighty nine days, then CSV."],[406.564,409.516,"Check the setup first, and triage safety first."]],"quiz":[{"at":90.519,"question":"Contoso raises the Compare meaning pass score to 95. Cases that have an expected response now score below that bar. What result do those cases get?","options":["Invalid, because the bar is too demanding","Error, because the method could not decide","Fail, because they scored below the bar"],"right":2,"trap":0,"answerAt":95.835},{"at":187.509,"question":"Contoso's auditors want this quarter's evaluation results available for a full year. What should the maker do?","options":["Export the results to CSV after each run","Ask an admin to extend the result retention","Use Compare with to merge the older runs"],"right":0,"trap":1,"answerAt":192.825},{"at":276.933,"question":"Twelve cases fail overnight. All of them call the Create Ticket tool, and the user profile's connection expired yesterday. What should the maker do first?","options":["Rewrite the instructions and run the set again","Restore the connection and rerun the same set","Improve the Create Ticket tool description"],"right":1,"trap":0,"answerAt":282.249},{"at":350.131,"question":"After a run, Nexo has three failures: a vague answer about the cafeteria menu, a wrong order status, and an answer that shares an employee's home address. Which one do you triage first?","options":["The wrong order status in a core scenario","The vague menu answer with the lowest score","The answer sharing an employee's address"],"right":2,"trap":0,"answerAt":355.447}],"poster":"video/L37.jpg"},"F01":{"src":"video/F01.mp4","duration":312.676,"scenes":[{"start":0},{"start":25.354},{"start":50.329},{"start":75.157},{"start":105.671},{"start":129.819},{"start":159.679},{"start":186.041},{"start":222.297},{"start":246.226},{"start":280.797}],"cues":[[0.8,2.408,"Monday at Contoso."],[2.488,7.019,"The IT team has four people, and they answer the same questions all day."],[7.099,9.027,"My VPN will not connect."],[9.107,10.693,"I forgot my password."],[10.773,12.595,"The printer is offline again."],[12.675,17.141,"Every answer is already written in their guides, but someone still has to type it."],[17.221,21.645,"What if an assistant answered those questions for them, right inside Teams?"],[21.725,25.104,"Today you meet the tool that builds it: Copilot Studio."],[25.804,30.078,"Copilot Studio is the Microsoft tool where you build AI assistants,"],[30.078,32.639,"called agents, with very little code."],[32.719,34.54,"Picture an assembly workshop."],[34.62,38.071,"You choose the parts: instructions that say how to behave,"],[38.071,41.305,"knowledge to answer from, and tools to take action."],[41.385,43.875,"The workshop puts them together and publishes"],[43.875,46.343,"the result where your users already work."],[46.423,50.079,"It is a web app in your browser, so there is nothing to install."],[50.779,53.325,"In this one studio you build three things."],[53.405,57.275,"An agent is an AI assistant that chats and completes tasks."],[57.355,61.779,"It follows your instructions, uses the knowledge you connect, and calls tools."],[61.859,66.091,"A workflow is an automation you build with a drag and drop designer."],[66.171,71.32,"An agent flow is the classic Copilot Studio flow, similar to Power Automate."],[71.4,74.907,"It runs on its own, or hangs from an agent as a tool."],[75.607,76.681,"Your turn."],[76.761,80.087,"Contoso wants an assistant that chats with employees,"],[80.087,84.492,"answers from the IT guides, and opens a ticket when the steps fail."],[84.572,86.137,"Which piece do they build?"],[86.217,88.721,"A workflow from the drag and drop designer?"],[88.801,91.199,"An agent that chats and completes tasks?"],[91.279,94.145,"Or a classic agent flow that runs on its own?"],[94.225,95.961,"Decide before I answer."],[99.541,100.637,"An agent."],[100.717,103.413,"It chats, uses knowledge, and calls a tool."],[103.493,105.421,"A flow can be one of its tools."],[106.121,107.793,"Let us open the studio."],[107.873,110.207,"You sign in with your work or school account."],[110.287,114.199,"The Home page shows your agents and a box to describe a new one."],[114.279,118.468,"Select Create and describe, in plain language, what the agent should do."],[118.548,121.628,"Check the top bar to see which environment you are in."],[121.708,126.388,"Then walk through the sections: Overview, Knowledge, Tools, Topics, and Settings."],[126.468,129.569,"Finally, ask something in the Test your agent panel."],[130.269,132.44,"Everything you build runs on a harness,"],[132.44,135.312,"the engine that does the work behind the scenes."],[135.392,140.776,"It changes how the agent reasons, how complex its work can be, and how it is billed."],[140.856,145.643,"The standard harness is for rules and structured, repeatable conversations."],[145.723,150.101,"The Microsoft Copilot harness, formerly the GitHub Copilot harness,"],[150.101,153.176,"is for multi step work that needs reasoning."],[153.256,156.043,"The Copilot chat harness extends Microsoft"],[156.043,159.429,"Copilot Chat with your organization's knowledge."],[160.129,162.463,"This course uses the standard harness."],[162.543,167.137,"Here, the agent understands what the user asked and looks for the best topic."],[167.217,170.498,"A topic is a part of the conversation that you design,"],[170.498,173.007,"with steps, questions, and conditions."],[173.087,175.394,"If the request falls outside your topics,"],[175.394,179.644,"the agent can still generate an answer from the knowledge you connected."],[179.724,182.657,"That is why a new agent is useful from minute one:"],[182.657,185.791,"connect a SharePoint site, and it already answers."],[186.491,187.565,"Your turn."],[187.645,191.024,"Contoso builds an HR agent for leave requests."],[191.104,196.189,"Every conversation follows the same rules and the same questions, in the same order."],[196.269,197.664,"Which harness fits?"],[197.744,200.184,"The standard harness, for structured rules?"],[200.264,203.045,"The Microsoft Copilot harness, for reasoning?"],[203.125,206.269,"Or the Copilot chat harness, for Copilot Chat?"],[206.349,208.085,"Decide before I answer."],[211.665,213.124,"The standard harness."],[213.204,216.455,"Rules and repeatable conversations are its job."],[216.535,220.076,"The Microsoft Copilot harness is for multi step reasoning,"],[220.076,222.047,"and it is billed differently."],[222.747,227.727,"When the agent is ready, you publish it to the channels where people already work:"],[227.727,232.056,"Microsoft Teams, Microsoft Copilot, websites, mobile apps, and more."],[232.136,236.795,"Once it is in production, you operate it from the same studio, with three areas."],[236.875,239.229,"Analytics shows performance and sessions."],[239.309,242.453,"Evaluations runs test sets that measure quality."],[242.533,245.976,"Administration covers inventory, security, and costs."],[246.676,247.751,"Your turn."],[247.831,249.609,"Nexo is live in Teams."],[249.689,252.594,"Before each change, the IT lead wants to measure"],[252.594,255.457,"answer quality with a set of test questions."],[255.537,257.273,"Which area do they open?"],[257.353,259.729,"Analytics, for performance and sessions?"],[259.809,262.505,"Administration, for inventory and costs?"],[262.585,265.473,"Or Evaluations, for test sets and quality?"],[265.553,267.289,"Decide before I answer."],[270.869,272.136,"Evaluations."],[272.216,274.229,"Its test sets measure quality."],[274.309,276.762,"Analytics shows how real sessions went,"],[276.762,280.547,"and Administration covers inventory, security, and costs."],[281.247,282.705,"Back to Contoso."],[282.785,285.161,"The team builds an agent called Nexo."],[285.241,289.439,"They write a few instructions, connect the SharePoint site with the IT"],[289.439,294.017,"guides as knowledge, add a tool to open tickets, and publish it in Teams."],[294.097,297.327,"An employee types: my VPN will not connect."],[297.407,302.556,"Nexo replies with the steps from the guide, and if that fails, it opens the ticket."],[302.636,306.676,"The team stops answering repeats and focuses on the hard cases."]],"quiz":[{"at":94.225,"answerAt":99.541,"question":"Contoso wants an assistant that chats with employees, answers from the IT guides, and opens a ticket when the steps fail. Which piece do they build?","options":["A workflow from the drag and drop designer","An agent that chats and completes tasks","A classic agent flow that runs on its own"],"right":1,"trap":2},{"at":206.349,"answerAt":211.665,"question":"Contoso builds an HR agent for leave requests. Every conversation follows the same rules and the same questions, in the same order. Which harness fits?","options":["The standard harness, for structured rules","The Microsoft Copilot harness, for reasoning","The Copilot chat harness, for Copilot Chat"],"right":0,"trap":1},{"at":265.553,"answerAt":270.869,"question":"Nexo is live in Teams. Before each change, the IT lead wants to measure answer quality with a set of test questions. Which area do they open?","options":["Analytics, for performance and sessions","Administration, for inventory and costs","Evaluations, for test sets and quality"],"right":2,"trap":0}],"poster":"video/F01.jpg"},"F02":{"src":"video/F02.mp4","duration":295.183,"scenes":[{"start":0},{"start":24.221},{"start":48.71},{"start":76.058},{"start":106.755},{"start":138.489},{"start":168.759},{"start":202.175},{"start":229.353},{"start":262.022}],"cues":[[0.8,2.664,"Two weeks later at Contoso."],[2.744,7.424,"Nexo is live in Teams and answers VPN questions from the guides."],[7.504,9.091,"But new requests arrive."],[9.171,13.36,"An employee asks for the status of their ticket, and Nexo cannot see it."],[13.44,18.355,"Another reports a server outage, and Nexo forgets to ask which system is down."],[18.435,21.536,"Each problem lives in a different piece of the agent."],[21.616,23.971,"Today we open Nexo and look inside."],[24.671,27.153,"Every agent is built from four pieces."],[27.233,29.119,"Think of hiring a new employee."],[29.199,32.599,"You give them a job description: those are the instructions."],[32.679,36.015,"A folder of documents to read: that is the knowledge."],[36.095,39.047,"Access to the company systems: those are the tools."],[39.127,42.527,"And a few scripts for delicate calls: those are the topics."],[42.607,45.529,"Keep this picture, because almost any scenario"],[45.529,48.46,"question on the exam asks which piece fits."],[49.16,52.133,"Start with the instructions, the job description."],[52.213,56.744,"They are free text in plain language, written on the agent's Overview page."],[56.824,60.779,"They say who the agent is, how it talks, and what it must not do."],[60.859,65.773,"Nexo's instructions say: you are Nexo, the Contoso IT assistant."],[65.853,67.099,"Answer briefly."],[67.179,69.811,"If you do not know, offer to open a ticket."],[69.891,72.965,"Keep them short and clear, with no contradictions,"],[72.965,75.808,"because the model tries to obey every line."],[76.508,78.073,"Next, knowing and doing."],[78.153,83.452,"Knowledge is what the agent can look up: websites, files, SharePoint, or Dataverse."],[83.532,87.636,"It answers questions with your organization's real information."],[87.716,92.259,"Tools are what the agent can run: a connector, an agent flow,"],[92.259,96.407,"a prompt, a REST API, an MCP server, or computer use."],[96.487,98.863,"They take action or bring in live data."],[98.943,102.897,"Quick rule: if the answer is written in a document, it is knowledge."],[102.977,106.505,"If you must query a system or change something, it is a tool."],[107.205,108.28,"Your turn."],[108.36,112.08,"An employee asks Nexo for the current status of their ticket."],[112.16,116.093,"That status lives in the help desk system and changes all day."],[116.173,117.717,"Which piece do they add?"],[117.797,120.003,"Knowledge, with the help desk guides?"],[120.083,122.416,"A topic, with fixed ticket questions?"],[122.496,124.701,"Or a tool that queries the help desk?"],[124.781,126.517,"Decide before I answer."],[130.097,131.129,"A tool."],[131.209,135.441,"The status is live data inside a system, so Nexo must query it."],[135.521,138.239,"Knowledge only reads what is already written."],[138.939,142.296,"Last piece: topics, the scripts for delicate calls."],[142.376,144.923,"A topic is a conversation you design."],[145.003,148.488,"It starts with a trigger, the node that decides when it begins."],[148.568,153.099,"Then come nodes: a message, a question, a condition, a call to a tool."],[153.179,157.411,"Inside a topic you control exactly what is said and in what order."],[157.491,160.87,"Use one when you need precision: validating a value,"],[160.87,164.709,"following a fixed process, or returning an exact result."],[164.789,168.509,"For everything else, let the agent combine knowledge and tools."],[169.209,170.284,"Your turn."],[170.364,174.127,"For every serious incident, IT always needs the same data,"],[174.127,178.415,"asked in the same order: the affected system, then the urgency."],[178.495,180.252,"How should Nexo collect it?"],[180.332,182.644,"A topic with fixed questions in order?"],[182.724,185.249,"An instruction that asks for both details?"],[185.329,187.727,"Or a knowledge file listing the questions?"],[187.807,189.543,"Decide before I answer."],[193.123,194.219,"A topic."],[194.299,197.933,"An exact, repeatable process is designed step by step."],[198.013,201.925,"An instruction only guides the model, so a question can be skipped."],[202.625,205.343,"Let us find each piece in Copilot Studio."],[205.423,206.732,"Open Nexo."],[206.812,211.193,"On Overview, the Instructions box holds the role, the tone, and the scope."],[211.273,215.399,"Open Knowledge and add a source, such as a public website or a file."],[215.479,219.604,"Open Tools and select Add a tool to see the connectors you can add."],[219.684,224.833,"Open Topics to see the system topics and your own, and open one to read its nodes."],[224.913,229.103,"Finally, ask something in the test panel and notice which piece answered."],[229.803,230.877,"Your turn."],[230.957,233.834,"Nexo has a ticket tool, but it rarely chooses it,"],[233.834,236.853,"even though the instructions talk about tickets."],[236.933,238.648,"What should the maker improve?"],[238.728,240.891,"Stricter rules in the instructions?"],[240.971,242.899,"A clear description of the tool?"],[242.979,245.056,"Or more ticket guides as knowledge?"],[245.136,246.872,"Decide before I answer."],[250.452,252.359,"A clear description of the tool."],[252.439,257.012,"The agent reads the descriptions of tools and topics to choose what to use."],[257.092,261.772,"Instructions set the role and the tone, but they do not replace a good description."],[262.472,263.931,"Back to Contoso."],[264.011,266.963,"The team fixes each problem with the right piece."],[267.043,269.269,"The instructions keep answers brief."],[269.349,271.64,"The SharePoint guides stay as knowledge."],[271.72,274.928,"A new tool reads the ticket status from the help desk."],[275.008,278.046,"And a topic called Report serious incident always"],[278.046,281.16,"asks for the affected system, then the urgency."],[281.24,284.002,"Remember the rule: documents are knowledge,"],[284.002,287.477,"live systems are tools, exact processes are topics."],[287.557,291.683,"In the next lesson, you will see how Nexo decides which piece to use."]],"quiz":[{"at":124.781,"question":"An employee asks Nexo for the current status of their ticket. That status lives in the help desk system and changes all day. Which piece do they add?","options":["Knowledge, with the help desk guides","A topic, with fixed ticket questions","A tool that queries the help desk"],"right":2,"trap":0,"answerAt":130.097},{"at":187.807,"question":"For every serious incident, IT always needs the same data, asked in the same order: the affected system, then the urgency. How should Nexo collect it?","options":["A topic with fixed questions in order","An instruction that asks for both details","A knowledge file listing the questions"],"right":0,"trap":1,"answerAt":193.123},{"at":245.136,"question":"Nexo has a ticket tool, but it rarely chooses it, even though the instructions talk about tickets. What should the maker improve?","options":["Stricter rules in the instructions","A clear description of the tool","More ticket guides as knowledge"],"right":1,"trap":0,"answerAt":250.452}],"poster":"video/F02.jpg"},"F04":{"src":"video/F04.mp4","duration":273.695,"scenes":[{"start":0},{"start":29.154},{"start":53.089},{"start":80.159},{"start":110.409},{"start":146.558},{"start":172.645},{"start":211.61},{"start":238.147}],"cues":[[0.8,2.451,"Week three at Contoso."],[2.531,5.76,"An employee asks Nexo how to reset their password."],[5.84,8.238,"Nexo answers at once, sounding sure:"],[8.238,12.035,"open the Contoso portal, choose Security, press Reset."],[12.115,13.701,"There is no such portal."],[13.781,15.368,"The steps were invented."],[15.448,20.512,"Nobody gave Nexo the real password guide, so the model filled the gap with a guess."],[20.592,23.501,"The IT team does not want a smarter guess."],[23.581,27.109,"They want answers that come from Contoso's own documents."],[27.189,28.904,"That is what knowledge is for."],[29.604,31.084,"Picture a librarian."],[31.164,34.095,"A good librarian does not remember every book."],[34.175,38.364,"They know which shelf to check, they read the page, and they show you the book."],[38.444,40.223,"Knowledge works the same way."],[40.303,43.831,"It is the set of sources the agent looks up before it answers."],[43.911,47.14,"When an answer comes from your sources, we call it grounded."],[47.22,49.365,"Grounded answers make fewer things up,"],[49.365,52.839,"and the agent can cite where each piece of data came from."],[53.539,55.061,"Which shelves can you add?"],[55.141,59.821,"Public websites, searched with Bing, but only inside the addresses you give."],[59.901,62.768,"Files you upload, which are stored in Dataverse."],[62.848,64.776,"SharePoint sites and libraries."],[64.856,67.253,"Dataverse tables in your environment."],[67.333,72.397,"And enterprise data through Copilot connectors, indexed by Microsoft Search."],[72.477,76.804,"You add knowledge when you create the agent, later on the Knowledge page,"],[76.804,79.909,"or inside a topic with a generative answers node."],[80.609,82.559,"Now a detail the exam loves."],[82.639,87.511,"SharePoint, Dataverse and enterprise connectors use the user's own sign in."],[87.591,92.676,"When someone asks a question, Nexo only shows content that person can already open."],[92.756,97.351,"So an intern and a manager can ask the same thing and get different answers."],[97.431,100.703,"For this to work, you configure user authentication."],[100.783,103.799,"Answers also carry citations to their sources."],[103.879,107.834,"But if you customize the response, for example in an Adaptive Card,"],[107.834,110.159,"you must add the citations yourself."],[110.859,111.933,"Your turn."],[112.013,115.29,"Contoso keeps its HR policies in a SharePoint site,"],[115.29,117.867,"with permissions for each department."],[117.947,122.797,"Every employee must only get answers from documents they can already open."],[122.877,124.293,"How do they add them?"],[124.373,127.005,"Upload copies of the documents as files?"],[127.085,129.141,"Add the SharePoint site as knowledge?"],[129.221,131.704,"Or paste the policies into the instructions?"],[131.784,133.52,"Decide before I answer."],[137.1,138.644,"Add the SharePoint site."],[138.724,143.681,"SharePoint uses the user's sign in, so each person only sees what they can open."],[143.761,146.308,"Uploaded copies lose those permissions."],[147.008,148.36,"Next, the settings."],[148.44,150.987,"Open Settings, then Generative AI."],[151.067,154.083,"Allow ungrounded responses is the key switch."],[154.163,158.562,"Turn it off, and in any turn where the agent used no source and no tool,"],[158.562,162.917,"the generated answer is blocked and the Fallback topic runs instead."],[162.997,167.891,"Use information from the web lets the agent search the whole public web with Bing."],[167.971,172.395,"Content moderation goes from Lowest to Highest, and the default is High."],[173.095,174.169,"Your turn."],[174.249,177.147,"Sometimes Nexo still answers with no source at all,"],[177.147,179.847,"straight from the model's general knowledge."],[179.927,184.223,"IT wants those answers blocked, so the Fallback topic runs instead."],[184.303,185.655,"What do they change?"],[185.735,188.281,"Raise content moderation up to Highest?"],[188.361,190.801,"Turn on Use information from the web?"],[190.881,193.62,"Or switch off Allow ungrounded responses?"],[193.7,195.436,"Decide before I answer."],[199.016,201.52,"Switch off Allow ungrounded responses."],[201.6,206.109,"Moderation filters harmful content, and the web only adds sources."],[206.189,211.36,"It is not a full guarantee, so the instructions also say: always cite the source."],[212.06,213.775,"Let's do it in the studio."],[213.855,216.657,"Open Nexo and go to the Knowledge page."],[216.737,219.668,"Select Add knowledge and choose Public website."],[219.748,222.6,"Type the address, a name, and a clear description,"],[222.6,225.025,"so the agent can pick the right source."],[225.105,227.311,"Wait until the source shows Ready."],[227.391,231.068,"Then open Settings, Generative AI, and check the two switches."],[231.148,235.183,"Finally, in the test pane, ask something that only your source knows,"],[235.183,237.897,"and look for the citation under the answer."],[238.597,239.907,"Back to week three."],[239.987,242.159,"The IT team added two sources:"],[242.159,246.992,"the IT SharePoint site and the VPN vendor's public support site."],[247.072,249.642,"They turned off Allow ungrounded responses"],[249.642,252.84,"and told Nexo to always cite the source document."],[252.92,255.808,"The same employee asks how to reset their password."],[255.888,261.187,"Nexo answers with the real steps and a citation to the exact SharePoint article."],[261.267,265.252,"Remember: knowledge is looked up, SharePoint respects permissions,"],[265.252,267.867,"and no source means no generated answer."],[267.947,270.195,"Next, the tools Nexo can run."]],"quiz":[{"at":131.784,"question":"Contoso keeps its HR policies in a SharePoint site, with permissions for each department. Every employee must only get answers from documents they can already open. How do they add them?","options":["Upload copies of the documents as files","Add the SharePoint site as knowledge","Paste the policies into the instructions"],"right":1,"trap":0,"answerAt":137.1},{"at":193.7,"question":"Sometimes Nexo still answers with no source at all, straight from the model's general knowledge. IT wants those answers blocked, so the Fallback topic runs instead. What do they change?","options":["Raise content moderation up to Highest","Turn on Use information from the web","Switch off Allow ungrounded responses"],"right":2,"trap":0,"answerAt":199.016}],"poster":"video/F04.jpg"},"F05":{"src":"video/F05.mp4","duration":272.847,"scenes":[{"start":0},{"start":27.533},{"start":53.233},{"start":81.069},{"start":113.107},{"start":149.766},{"start":179.519},{"start":213.578},{"start":238.835}],"cues":[[0.8,2.515,"Week four at Contoso."],[2.595,7.253,"An employee writes: the VPN steps did not work, please open a ticket."],[7.333,10.328,"Nexo found the right guide, but now it is stuck."],[10.408,13.104,"It can only say: please call the help desk."],[13.184,15.581,"The employee closes the chat, annoyed."],[15.661,17.995,"Nexo can read, but it cannot act."],[18.075,20.365,"Knowledge is what the agent reads."],[20.445,22.416,"Tools are what the agent does."],[22.496,27.283,"Today we give Nexo hands, and the adapters that connect them to real systems."],[27.983,30.645,"A tool is a capability the agent can run:"],[30.645,34.156,"read an email, create a ticket, check an inventory."],[34.236,36.825,"Think of the apps installed on the agent's phone."],[36.905,40.163,"The main types are a connector, an agent flow,"],[40.163,44.188,"a prompt, a REST API, an MCP server, and computer use."],[44.268,49.567,"With generative orchestration, the agent chooses a tool by its name and description."],[49.647,52.983,"In classic mode, a tool is only called from a topic."],[53.683,55.781,"The most common tool is a connector."],[55.861,57.832,"Picture a travel plug adapter."],[57.912,63.061,"Your device always has the same plug, and the adapter makes it fit in every country."],[63.141,65.773,"A connector is a wrapper around an API."],[65.853,69.742,"It translates the agent's calls into the language of each service,"],[69.742,74.48,"like SharePoint, Outlook or Salesforce, and it comes with ready-made actions."],[74.56,77.423,"The same connectors work in Copilot Studio,"],[77.423,80.819,"Power Automate, Power Apps and Azure Logic Apps."],[81.519,83.361,"Connectors come in three kinds."],[83.441,88.313,"Standard ones, like SharePoint, are included in every Copilot Studio plan."],[88.393,91.665,"Premium ones are only available in certain plans."],[91.745,96.391,"Custom ones you build yourself, usually from an OpenAPI specification,"],[96.391,99.113,"when a service has no ready connector."],[99.193,104.812,"Watch one trap: the Copilot Studio plan for Teams does not allow premium connectors."],[104.892,109.594,"And administrators use data policies to allow or block connectors,"],[109.594,112.857,"custom connectors and MCP servers included."],[113.557,114.632,"Your turn."],[114.712,120.038,"Contoso's HR team builds an agent with the Copilot Studio plan for Teams,"],[120.038,123.083,"included in Microsoft three sixty five."],[123.163,126.819,"The agent needs a premium connector for the payroll system."],[126.899,128.016,"What happens?"],[128.096,130.408,"They need a plan with premium connectors?"],[130.488,132.992,"It works, as all connectors are included?"],[133.072,136.152,"Or it works once an admin data policy allows it?"],[136.232,137.968,"Decide before I answer."],[141.548,143.924,"They need a plan with premium connectors."],[144.004,146.723,"The Teams plan does not allow premium ones,"],[146.723,149.516,"and a data policy cannot grant a license."],[150.216,154.149,"A connector needs a connection: saved credentials for a service."],[154.229,157.845,"By default, it uses the credentials of the person chatting,"],[157.845,162.152,"so each employee signs in once and acts with their own permissions."],[162.232,167.403,"The alternative is maker provided credentials, which need an authenticated channel."],[167.483,169.702,"Use them with care: every user then acts"],[169.702,172.952,"with the permissions of the person who set up the tool."],[173.032,176.022,"Connections can be shared from the Power Apps portal,"],[176.022,179.269,"in Connections, with the Can use and share permission."],[179.969,181.044,"Your turn."],[181.124,184.652,"IT purchase approvals live in an internal system."],[184.732,189.924,"It has its own API and an OpenAPI description, but no ready connector."],[190.004,191.975,"How does Nexo get a tool for it?"],[192.055,194.58,"Use computer use to click through its screens?"],[194.66,197.591,"Build a custom connector from its OpenAPI?"],[197.671,200.452,"Or add the system's website as a knowledge source?"],[200.532,202.268,"Decide before I answer."],[205.848,207.52,"Build a custom connector."],[207.6,209.848,"The API exists, so you wrap it."],[209.928,213.328,"Computer use is for systems that only have a screen."],[214.028,215.743,"Let's add one in the studio."],[215.823,218.476,"Open Nexo and go to the Tools page."],[218.556,220.74,"Select Add a tool, then Connector."],[220.82,224.433,"Search for the service and choose the action, like create a ticket."],[224.513,228.767,"If there is no connection yet, select Create new connection and sign in."],[228.847,233.143,"Select Add and configure, then improve the tool's name and description."],[233.223,235.543,"Finally, test a request in the test pane"],[235.543,238.585,"and watch the activity map show the tool running."],[239.285,240.659,"Back to week four."],[240.739,243.77,"The team added the help desk's premium connector,"],[243.77,248.981,"and a developer built a custom connector for purchase approvals from its OpenAPI."],[249.061,252.589,"The admins checked the data policies, so both are allowed."],[252.669,254.576,"The same employee writes again."],[254.656,259.144,"Nexo signs them in once and opens the ticket with their own credentials."],[259.224,263.805,"Remember: premium needs the right plan, no connector means a custom one,"],[263.805,266.613,"and data policies decide what is allowed."],[266.693,269.347,"Next, where all of this lives: environments."]],"quiz":[{"at":136.232,"question":"Contoso's HR team builds an agent with the Copilot Studio plan for Teams, included in Microsoft 365. The agent needs a premium connector for the payroll system. What happens?","options":["They need a plan with premium connectors","It works, as all connectors are included","It works once an admin data policy allows it"],"right":0,"trap":1,"answerAt":141.548},{"at":200.532,"question":"IT purchase approvals live in an internal system. It has its own API and an OpenAPI description, but no ready connector. How does Nexo get a tool for it?","options":["Use computer use to click through its screens","Build a custom connector from its OpenAPI","Add the system's website as a knowledge source"],"right":1,"trap":0,"answerAt":205.848}],"poster":"video/F05.jpg"},"F06":{"src":"video/F06.mp4","duration":265.324,"scenes":[{"start":0},{"start":28.079},{"start":53.91},{"start":83.434},{"start":110.425},{"start":143.289},{"start":171.615},{"start":204.543},{"start":233.425}],"cues":[[0.8,2.493,"Week five at Contoso."],[2.573,6.741,"A maker tries a new incident topic directly on the live Nexo."],[6.821,9.901,"For an hour, employees get half finished questions."],[9.981,12.86,"Then a colleague opens Copilot Studio to help,"],[12.86,15.877,"and Nexo is not even in their list of agents."],[15.957,19.593,"Two problems, one cause: nobody planned where Nexo lives,"],[19.593,22.792,"or how changes travel to the people who use it."],[22.872,27.829,"Today we fix that with three ideas: environments, Dataverse, and solutions."],[28.529,32.548,"An environment is a space where your apps, agents and flows live."],[32.628,35.877,"Picture separate office buildings: one for development,"],[35.877,38.204,"one for testing, one for production."],[38.284,42.473,"What you build in one building does not appear in another until you move it."],[42.553,45.015,"That is why the colleague could not see Nexo."],[45.095,49.092,"Each environment belongs to one Entra tenant and one region."],[49.172,53.66,"And an agent only uses connections and data from its own environment."],[54.36,56.053,"Environments come in types."],[56.133,61.24,"Default: one per tenant, shared by everyone, for experiments, not for production."],[61.32,63.696,"Production: permanent, for real work."],[63.776,68.52,"Sandbox: for development and testing, with options to copy and reset it."],[68.6,71.723,"Developer: a personal one, with the Developer Plan."],[71.803,75.992,"Trial: for trying things out, and it expires after thirty days."],[76.072,80.326,"Two built in roles matter: Environment Admin manages everything,"],[80.326,83.184,"and Environment Maker creates resources."],[83.884,87.647,"Inside each building there can be one database: Dataverse."],[87.727,90.081,"Each environment has zero or one."],[90.161,93.732,"It stores information in tables, with rows and columns."],[93.812,96.721,"It matters to Copilot Studio for three reasons."],[96.801,98.964,"Its tables can be a knowledge source."],[99.044,101.548,"It stores the files you upload as knowledge."],[101.628,103.428,"And solutions depend on it."],[103.508,107.932,"One trap: being Environment Admin does not give you access to the data."],[108.012,110.175,"That access is granted separately."],[110.875,111.949,"Your turn."],[112.029,117.243,"A team wants a place to develop and test a new agent before real employees use it."],[117.323,120.893,"They also want to copy it and reset it when tests go wrong."],[120.973,122.795,"Which environment type fits?"],[122.875,124.483,"The default environment?"],[124.563,126.256,"A production environment?"],[126.336,128.2,"Or a sandbox environment?"],[128.28,130.016,"Decide before I answer."],[133.596,134.799,"A sandbox."],[134.879,138.727,"It is made for development and testing, with copy and reset."],[138.807,143.039,"The default one is shared by everyone, and production is for real work."],[143.739,148.013,"To move work between buildings, you use a moving box: a solution."],[148.093,150.557,"It groups components, like agents, flows,"],[150.557,154.544,"environment variables and connections, so they travel together."],[154.624,157.42,"Agents are always created inside a solution:"],[157.42,160.989,"the default one, unless you set a preferred solution."],[161.069,164.427,"In development the box is unmanaged, so you can edit it."],[164.507,168.376,"For test and production you export it managed, a sealed package."],[168.456,171.365,"Power Platform Pipelines can automate the trip."],[172.065,173.14,"Your turn."],[173.22,176.193,"Nexo works well in the Nexo Dev environment."],[176.273,180.783,"Now the team must take it to Nexo Prod, where real employees will use it."],[180.863,182.193,"How do they move it?"],[182.273,184.351,"Package it in a managed solution?"],[184.431,186.7,"Rebuild the agent by hand in Prod?"],[186.78,189.007,"Or share the Dev agent with everyone?"],[189.087,190.823,"Decide before I answer."],[194.403,195.84,"A managed solution."],[195.92,198.829,"You export it from Dev and import it into Prod."],[198.909,204.293,"Rebuilding by hand invites mistakes, and Dev is for building, not for real users."],[204.993,206.665,"Let's look at it on screen."],[206.745,210.7,"In Copilot Studio, find the environment picker in the top bar."],[210.78,214.009,"Switch environments, and the list of agents changes."],[214.089,217.809,"If you have permission, the Power Platform admin center shows"],[217.809,221.607,"every environment and its type, under Manage, Environments."],[221.687,223.631,"Then, in the Power Apps portal,"],[223.631,228.159,"open Solutions and create a solution called Nexo, with its publisher."],[228.239,233.175,"Use Add existing to add the agent, and export it as unmanaged or managed."],[233.875,235.269,"Back to week five."],[235.349,240.904,"Contoso now has three environments: Nexo Dev, Nexo Test and Nexo Prod."],[240.984,245.088,"Makers build Nexo in Dev, inside a solution called Nexo."],[245.168,247.66,"When it is ready, they export it as managed,"],[247.66,250.125,"import it into Test, and then into Prod."],[250.205,253.77,"Each building has its own Dataverse and its own connections,"],[253.77,255.931,"so real data stays in production."],[256.011,259.24,"An admin sets different data policies for each one."],[259.32,261.824,"Next: how to test and publish Nexo."]],"quiz":[{"at":128.28,"question":"A team wants a place to develop and test a new agent before real employees use it. They also want to copy it and reset it when tests go wrong. Which environment type fits?","options":["The default environment","A production environment","A sandbox environment"],"right":2,"trap":0,"answerAt":133.596},{"at":189.087,"question":"Nexo works well in the Nexo Dev environment. Now the team must take it to Nexo Prod, where real employees will use it. How do they move it?","options":["Package it in a managed solution","Rebuild the agent by hand in Prod","Share the Dev agent with everyone"],"right":0,"trap":1,"answerAt":194.403}],"poster":"video/F06.jpg"},"F07":{"src":"video/F07.mp4","duration":284.109,"scenes":[{"start":0},{"start":25.519},{"start":50.347},{"start":76.842},{"start":105.579},{"start":137.59},{"start":166.394},{"start":194.297},{"start":229.23},{"start":254.703}],"cues":[[0.8,2.515,"Week six at Contoso."],[2.595,6.571,"On Friday, the team fixed Nexo's answer about locked accounts."],[6.651,10.136,"On Monday, employees in Teams still get the old answer."],[10.216,14.209,"Meanwhile, an eager maker wants to share Nexo with the whole company,"],[14.209,16.261,"without ever trying it in Teams."],[16.341,17.991,"Two mistakes from the same gap:"],[17.991,21.277,"not knowing the difference between testing and publishing."],[21.357,25.269,"Today we rehearse on an empty stage, and then we open the doors."],[25.969,27.727,"Testing is the rehearsal."],[27.807,31.778,"The Test your agent pane lets you chat with the version you are editing,"],[31.778,33.191,"without publishing it."],[33.271,35.213,"Select one of the agent's replies,"],[35.213,38.612,"and you jump to the topic and the node that produced it."],[38.692,40.748,"The nodes that ran get a checkmark."],[40.828,45.145,"Turn on Track between topics, and the canvas follows the conversation."],[45.225,50.097,"And use Reset to start clean, because saving a topic does not clear the test chat."],[50.797,54.176,"With generative orchestration, open the activity map."],[54.256,57.49,"It shows the agent's plan in real time: which topics,"],[57.49,60.557,"tools or knowledge it chose, and in what order."],[60.637,63.376,"The team types: I can't get into my email."],[63.456,66.323,"The map shows Knowledge first, then the tickets tool."],[66.403,68.267,"Exactly the plan they wanted."],[68.347,71.165,"Next to it, the Variables panel, on its Test tab,"],[71.165,73.837,"shows each variable's value while you chat."],[73.917,76.592,"When something looks wrong, these two tell you why."],[77.292,79.177,"Publishing opens the doors."],[79.257,82.977,"Publish applies your current version to every connected channel."],[83.057,87.396,"If you change something and do not publish, users keep the previous version."],[87.476,89.084,"It can take a few minutes."],[89.164,91.817,"Conversations in progress are not cut off."],[91.897,94.67,"The new content arrives when a new session starts,"],[94.67,98.753,"and most channels end a session after thirty minutes without activity."],[98.833,101.465,"In Teams, a user can type start over."],[101.545,105.329,"One more limit: a trial account can test, but cannot publish."],[106.029,107.104,"Your turn."],[107.184,110.328,"The team fixed a wrong answer in a topic and saved it."],[110.408,115.792,"A day later, employees in Teams still get the old answer, even in brand new chats."],[115.872,117.032,"What is missing?"],[117.112,119.445,"Reset the conversation in the test pane?"],[119.525,121.859,"Publish the agent so channels update?"],[121.939,124.4,"Or wait for the old sessions to expire?"],[124.48,126.216,"Decide before I answer."],[129.796,131.169,"Publish the agent."],[131.249,133.327,"Saving only changes the draft."],[133.407,137.34,"Channels see a change after you publish, and waiting changes nothing."],[138.04,140.715,"A channel is where people talk to the agent."],[140.795,142.936,"Teams and Microsoft Copilot."],[143.016,144.133,"SharePoint."],[144.213,145.181,"WhatsApp."],[145.261,147.936,"A website, either the demo site or your own."],[148.016,151.714,"A mobile app, Facebook, and the Azure Bot Service channels,"],[151.714,154.296,"like Slack, Telegram, Twilio or email."],[154.376,157.136,"Pick the places where your users already chat."],[157.216,160.125,"Administrators can block channels with policies."],[160.205,164.332,"And remember: the demo website is only for showing stakeholders,"],[164.332,166.144,"never for real customers."],[166.844,169.305,"Every channel needs to know who is at the door."],[169.385,172.209,"The default is Authenticate with Microsoft."],[172.289,177.716,"Teams, SharePoint, Power Apps and Microsoft Copilot work with no extra setup."],[177.796,181.793,"Authenticate manually is for other channels that need a sign in."],[181.873,184.996,"No authentication lets anyone with the link chat."],[185.076,189.244,"It also means tools cannot run with each user's own credentials."],[189.324,194.047,"So for an internal IT helper like Nexo, the default is usually right."],[194.747,195.821,"Your turn."],[195.901,198.776,"In Teams, Nexo must identify each employee"],[198.776,202.331,"and run tools with that person's own credentials."],[202.411,204.424,"The team wants no extra setup."],[204.504,206.603,"Which authentication do they choose?"],[206.683,208.995,"Authenticate manually in each channel?"],[209.075,211.429,"No authentication, open to the link?"],[211.509,214.312,"Or authenticate with Microsoft in Teams?"],[214.392,216.128,"Decide before I answer."],[219.708,221.679,"Authenticate with Microsoft."],[221.759,224.177,"It works in Teams with no extra setup."],[224.257,228.98,"Manual is for other channels, and no authentication blocks user credentials."],[229.68,231.971,"Here is the full routine in the studio."],[232.051,234.469,"Open the Test pane and ask a question."],[234.549,236.904,"Select the reply to jump to its node."],[236.984,239.808,"Check the activity map and the Variables tab."],[239.888,243.416,"Then select Publish, confirm, and wait until it finishes."],[243.496,247.152,"Open Channels and choose Teams and Microsoft Copilot."],[247.232,251.101,"First, select Open the agent in Teams and try it yourself."],[251.181,254.453,"Only then select Make the agent available to others."],[255.153,256.548,"Back to week six."],[256.628,259.615,"The team tests the locked account fix in the test pane,"],[259.615,261.607,"and the activity map looks right."],[261.687,266.324,"They publish, open Nexo in Teams just for themselves, and try again."],[266.404,267.564,"Green light."],[267.644,271.961,"They share it with the IT department, and weeks later with the whole company."],[272.041,276.721,"Remember: the test pane tests the draft and never replaces a real channel."],[276.801,279.028,"Every change needs a new publish."],[279.108,280.609,"Next, the exam map."]],"quiz":[{"at":124.48,"question":"The team fixed a wrong answer in a topic and saved it. A day later, employees in Teams still get the old answer, even in brand new chats. What is missing?","options":["Reset the conversation in the test pane","Publish the agent so channels update","Wait for the old sessions to expire"],"right":1,"trap":2,"answerAt":129.796},{"at":214.392,"question":"In Teams, Nexo must identify each employee and run tools with that person's own credentials. The team wants no extra setup. Which authentication do they choose?","options":["Authenticate manually in each channel","No authentication, open to the link","Authenticate with Microsoft in Teams"],"right":2,"trap":0,"answerAt":219.708}],"poster":"video/F07.jpg"},"F08":{"src":"video/F08.mp4","duration":284.077,"scenes":[{"start":0},{"start":25.629},{"start":49.963},{"start":77.351},{"start":110.301},{"start":141.046},{"start":173.313},{"start":201.959},{"start":227.625},{"start":252.541}],"cues":[[0.8,3.56,"Meet Valeria, a developer at Contoso."],[3.64,6.861,"She has watched Nexo grow over the last seven classes,"],[6.861,10.581,"and now she wants the certification herself, in two months."],[10.661,13.805,"She opens the list of skills measured, and it is long."],[13.885,15.259,"Where should she start?"],[15.339,16.861,"Think of planning a trip."],[16.941,20.139,"Before you start walking, you check how heavy each stretch is,"],[20.139,22.453,"and which words you will need on the way."],[22.533,25.379,"That is today: the exam map and the glossary."],[26.079,29.399,"The exam is AB six twenty, Designing and Building"],[29.399,32.444,"Integrated AI Solutions in Copilot Studio."],[32.524,37.055,"Passing it earns the Microsoft Certified AI Agent Builder Associate."],[37.135,39.423,"It lasts one hundred and twenty minutes,"],[39.423,42.711,"it is proctored, and it can include interactive parts."],[42.791,45.828,"You pass with seven hundred points out of one thousand."],[45.908,49.713,"And that number is a scaled score, which matters more than it seems."],[50.413,52.021,"A few rules of the room."],[52.101,55.36,"The exam comes in several languages, including Spanish,"],[55.36,59.768,"but local versions are updated about eight weeks after the English one."],[59.848,63.163,"If you fail, you can retake it after twenty four hours."],[63.243,66.325,"During the exam you can open Microsoft Learn,"],[66.325,70.909,"but not its Q and A, its practice assessments, or profile pages."],[70.989,73.259,"To search a page, use Control F."],[73.339,77.101,"Open Learn only for a quick check, because the clock keeps running."],[77.801,78.876,"Your turn."],[78.956,81.552,"In her practice sessions, Valeria answers about"],[81.552,84.127,"seventy percent of the questions correctly."],[84.207,88.353,"She thinks: seven hundred out of a thousand, so seventy percent is enough."],[88.433,89.551,"Is she right?"],[89.631,92.071,"No, seven hundred is a scaled score?"],[92.151,94.697,"Yes, seven hundred means seventy percent?"],[94.777,97.324,"Or only if each domain reaches seventy?"],[97.404,99.14,"Decide before I answer."],[102.72,103.581,"No."],[103.661,105.867,"Seven hundred is a scaled score."],[105.947,110.051,"It does not equal seventy percent correct, so aim well above the line."],[110.751,111.847,"Now the map."],[111.927,113.748,"The exam has three domains."],[113.828,119.127,"Domain one, plan and configure agent solutions: thirty to thirty five percent."],[119.207,121.54,"Planning, agent flows and topics."],[121.62,126.321,"Domain two, integrate and extend agents: forty to forty five percent."],[126.401,130.612,"Knowledge, tools, multi agent solutions and Azure services."],[130.692,135.159,"Domain three, test and manage agents: twenty to twenty five percent."],[135.239,137.103,"Evaluation and ALM."],[137.183,140.796,"The weights are ranges, so every exam is a little different."],[141.496,142.571,"Your turn."],[142.651,145.453,"Valeria has eight weeks before her exam date."],[145.533,148.933,"She wants to spend most of them where the exam weighs the most."],[149.013,151.133,"Where should most of her study time go?"],[151.213,154.037,"Plan and configure: planning and topics?"],[154.117,157.027,"Test and manage: evaluation and ALM?"],[157.107,160.08,"Or integrate and extend: knowledge, tools?"],[160.16,161.896,"Decide before I answer."],[165.476,167.063,"Integrate and extend."],[167.143,170.201,"It is forty to forty five percent, almost half."],[170.281,173.063,"But all three count, so no domain is skipped."],[173.763,175.861,"This course follows the same map."],[175.941,179.469,"Module zero, the one you are finishing, gives you the basics."],[179.549,185.061,"Modules one to three cover domain one: planning, advanced topics and agent flows."],[185.141,189.388,"Modules four to six cover domain two: knowledge and tools,"],[189.388,192.957,"MCP and multi agent, and Azure and monitoring."],[193.037,197.227,"Module seven covers domain three: evaluation and ALM."],[197.307,201.709,"Every topic has theory, a video, questions, and a hands on challenge."],[202.409,204.956,"Now the glossary, looking back at Nexo."],[205.036,208.137,"An agent is an AI assistant that chats and acts."],[208.217,211.511,"A topic is a conversation you design with nodes."],[211.591,214.351,"A tool is a capability the agent runs."],[214.431,217.063,"A connector is a wrapper around an API."],[217.143,219.945,"Knowledge is the sources the agent looks up."],[220.025,224.172,"Orchestration is the decision about what to use for each message."],[224.252,227.375,"And the harness is the engine that runs the agent."],[228.075,230.237,"And the words about where Nexo lives."],[230.317,234.421,"An environment is a Power Platform space with its apps and data."],[234.501,238.904,"A solution is the container that moves components between environments."],[238.984,241.829,"Dataverse is the Power Platform database."],[241.909,245.373,"DLP means the administrator's data policies."],[245.453,248.299,"A channel is where the user chats with the agent."],[248.379,252.291,"And Copilot Credits are the unit used to bill agent usage."],[252.991,254.257,"Back to Valeria."],[254.337,258.164,"She opens the study guide and books a date with Pearson VUE."],[258.244,262.856,"Most of her weeks go to domain two, with a weekly block for domain one,"],[262.856,265.719,"and evaluation and ALM in the last weeks."],[265.799,267.676,"Her lab environment is ready,"],[267.676,271.695,"and after every topic she rebuilds a piece of Nexo herself."],[271.775,275.943,"One week before the exam, she reviews this glossary and her mistakes."],[276.023,277.759,"Module zero is done."],[277.839,280.577,"Next, module one: planning the solution."]],"quiz":[{"at":97.404,"question":"In her practice sessions, Valeria answers about seventy percent of the questions correctly. She thinks: seven hundred out of a thousand, so seventy percent is enough. Is she right?","options":["No, seven hundred is a scaled score","Yes, seven hundred means seventy percent","Only if each domain reaches seventy"],"right":0,"trap":1,"answerAt":102.72},{"at":160.16,"question":"Valeria has eight weeks before her exam date. She wants to spend most of them where the exam weighs the most. Where should most of her study time go?","options":["Plan and configure: planning and topics","Test and manage: evaluation and ALM","Integrate and extend: knowledge, tools"],"right":2,"trap":0,"answerAt":165.476}],"poster":"video/F08.jpg"},"L01":{"src":"video/L01.mp4","duration":365.751,"scenes":[{"start":0},{"start":26.845},{"start":54.774},{"start":78.511},{"start":108.571},{"start":144.23},{"start":175.754},{"start":208.158},{"start":244.158},{"start":273.149},{"start":306.695},{"start":333.275}],"cues":[[0.8,5.011,"Module one begins, and Valeria is now building Nexo herself."],[5.091,7.424,"Contoso asks for three new jobs."],[7.504,11.693,"Record invoices in an old desktop program that has no API."],[11.773,15.963,"Check live inventory in a system with an OpenAPI file."],[16.043,19.251,"And share those tools with other AI clients in the company."],[19.331,21.984,"Three systems, three very different doors."],[22.064,26.595,"Today you learn to pick the right bridge for each one, the base of every solution."],[27.295,31.996,"An agent that only chats is like an employee with no phone and no computer."],[32.076,36.223,"Integration bridges give it hands to read, create and update data."],[36.303,39.745,"Copilot Studio offers six: Power Platform connectors,"],[39.745,42.412,"already built for well known services."],[42.492,43.908,"Custom connectors."],[43.988,45.511,"The REST API tool."],[45.591,47.177,"MCP servers."],[47.257,50.337,"Agent flows, built inside Copilot Studio."],[50.417,51.769,"And computer use."],[51.849,54.524,"All of them show up in one place: Tools."],[55.224,59.947,"One question sorts almost every case: does the system expose an API?"],[60.027,62.445,"If a connector already exists, use it."],[62.525,68.037,"If you have an OpenAPI file, use the REST API tool or a custom connector."],[68.117,73.288,"If the system speaks the MCP protocol, connect it as an MCP server."],[73.368,78.261,"And if it only has a screen, with no API at all, the answer is computer use."],[78.961,81.935,"When several bridges could work, go down this order."],[82.015,87.207,"A prebuilt connector first: no development, though large results slow the answer."],[87.287,90.665,"No connector, and several agents need the same API?"],[90.745,93.164,"Build a custom connector you can reuse."],[93.244,95.108,"A one off API in a test?"],[95.188,100.487,"The REST API tool, which is in preview and works only inside Copilot Studio."],[100.567,104.713,"Steps that must run in order, with human approval: an agent flow."],[104.793,108.321,"A central tool server for many agents: MCP."],[109.021,110.096,"Your turn."],[110.176,115.432,"Contoso's inventory system has an OpenAPI file, but no ready connector."],[115.512,119.68,"Three different agents need it, and a Power Automate flow needs it too."],[119.76,121.411,"Which bridge do they build?"],[121.491,123.931,"A REST API tool inside each agent?"],[124.011,126.045,"A custom connector they all share?"],[126.125,129.355,"Or a Send HTTP request node per topic?"],[129.435,131.171,"Decide before I answer."],[134.751,136.209,"A custom connector."],[136.289,139.945,"Many agents share it, and it also works in Power Automate."],[140.025,143.98,"The REST API tool lives only inside Copilot Studio."],[144.68,146.373,"Every bridge has a price."],[146.453,150.835,"Agent flows depend on API rate limits, need explicit error paths,"],[150.835,155.485,"limit the size of the response sent back, and use Copilot Credits."],[155.565,159.394,"MCP needs generative orchestration, topics cannot call it,"],[159.394,162.763,"and the tool descriptions are set on the server."],[162.843,167.864,"The Send HTTP request node is quick for one call, but you cannot share it."],[167.944,171.971,"And Bot Framework skills reuse pro code, but need C sharp,"],[171.971,175.504,"Azure costs, and sit outside Power Platform ALM."],[176.204,178.324,"Two bridges deserve a closer look."],[178.404,181.702,"MCP is an open protocol, so the same server"],[181.702,185.431,"can serve Copilot Studio and other AI clients."],[185.511,189.935,"In Copilot Studio its transport must be Streamable HTTP."],[190.015,193.607,"The older SSE transport is no longer supported."],[193.687,197.906,"Computer use operates websites and desktop apps with vision and reasoning,"],[197.906,200.5,"as if a person were looking at the screen."],[200.58,203.105,"Both need generative orchestration."],[203.185,207.908,"Computer use costs five Copilot Credits per step with standard models."],[208.608,209.683,"Your turn."],[209.763,215.552,"A maker connects an MCP server to an agent that still uses classic orchestration."],[215.632,219.331,"They want a topic to call its tools, but the tools never run."],[219.411,220.635,"What must change?"],[220.715,223.624,"Call the MCP tools from inside a topic?"],[223.704,226.123,"Switch the server transport to SSE?"],[226.203,228.621,"Or switch to generative orchestration?"],[228.701,230.437,"Decide before I answer."],[234.017,236.223,"Switch to generative orchestration."],[236.303,239.937,"MCP only works when the agent plans for itself."],[240.017,243.908,"Topics cannot call it, and SSE is no longer supported."],[244.608,246.301,"Keep two ideas apart."],[246.381,248.117,"Tools are for doing things."],[248.197,250.531,"Knowledge is for answering questions."],[250.611,255.439,"One knowledge type is unstructured data: files from OneDrive or SharePoint,"],[255.439,257.95,"synced and vector indexed in Dataverse,"],[257.95,261.819,"plus third party articles that arrive through connectors."],[261.899,266.173,"And when the agent picks a tool, it reads the tool's name and description."],[266.253,269.589,"A vague description makes it choose badly, or choose nothing."],[269.669,272.899,"Write it as if you were explaining the tool to a new teammate."],[273.599,274.673,"Your turn."],[274.753,278.345,"Contoso records invoices in an old desktop program."],[278.425,281.664,"It has no API and nobody can reach its database,"],[281.664,284.833,"but Nexo must type each new invoice into it."],[284.913,286.265,"Which bridge fits?"],[286.345,288.38,"Computer use, working its screen?"],[288.46,290.559,"A custom connector to the program?"],[290.639,293.335,"Or an MCP server running on the program?"],[293.415,295.151,"Decide before I answer."],[298.731,299.933,"Computer use."],[300.013,303.136,"There is only a screen, so Nexo works it with vision."],[303.216,306.445,"A connector and MCP both assume an API."],[307.145,309.159,"Here is how it looks in the studio."],[309.239,311.785,"Open Nexo and go to the Tools tab."],[311.865,315.215,"Select Add a tool and look at the categories:"],[315.215,319.212,"connectors, MCP, REST API, flows, and computer use."],[319.292,321.391,"Pick the bridge that fits the system."],[321.471,325.724,"For inventory, that is REST API with the OpenAPI file."],[325.804,327.647,"Write a clear name and description."],[327.727,333.025,"Create or select the connection, select Add to agent, and try it in the test pane."],[333.725,335.696,"Back to Valeria's three jobs."],[335.776,340.221,"The old invoice program gets computer use, which works its screen with vision."],[340.301,344.725,"Inventory, with its OpenAPI file, gets a REST API tool."],[344.805,349.027,"And because other AI clients in Contoso need the same tools,"],[349.027,352.323,"the team also exposes them as an MCP server."],[352.403,355.077,"Remember the question: does it have an API?"],[355.157,356.68,"Then follow the order."],[356.76,362.251,"Next, who the agent is when it reaches those systems: identity and authentication."]],"quiz":[{"at":129.435,"question":"Contoso's inventory system has an OpenAPI file, but no ready connector. Three different agents need it, and a Power Automate flow needs it too. Which bridge do they build?","options":["A REST API tool inside each agent","A custom connector they all share","A Send HTTP request node per topic"],"right":1,"trap":0,"answerAt":134.751},{"at":228.701,"question":"A maker connects an MCP server to an agent that still uses classic orchestration. They want a topic to call its tools, but the tools never run. What must change?","options":["Call the MCP tools from inside a topic","Switch the server transport to SSE","Switch to generative orchestration"],"right":2,"trap":0,"answerAt":234.017},{"at":293.415,"question":"Contoso records invoices in an old desktop program. It has no API and nobody can reach its database, but Nexo must type each new invoice into it. Which bridge fits?","options":["Computer use, working its screen","A custom connector to the program","An MCP server running on the program"],"right":0,"trap":1,"answerAt":298.731}],"poster":"video/L01.jpg"},"L03":{"src":"video/L03.mp4","duration":279.809,"scenes":[{"start":0},{"start":22.77},{"start":42.926},{"start":63.661},{"start":94.413},{"start":116.683},{"start":147.713},{"start":171.669},{"start":195.905},{"start":228.321},{"start":251.253}],"cues":[[0.8,3.9,"Valeria fixes Nexo's answer about returns."],[3.981,6.442,"She selects Publish and goes home happy."],[6.523,11.116,"The next morning, Marta from sales opens Teams and asks about returns."],[11.197,12.804,"She gets the old answer."],[12.885,14.364,"Is Nexo broken?"],[14.445,15.306,"No."],[15.387,19.491,"Today you learn what Publish really does, where your users meet the agent,"],[19.491,22.519,"and why some of them still see yesterday's version."],[23.22,25.382,"Think of the agent as a manual."],[25.463,28.499,"While you edit, your changes are a draft on your desk."],[28.58,31.979,"Publish prints the new edition and hands it out to everyone."],[32.06,34.588,"But someone still reading the old edition won't"],[34.588,37.315,"see the changes until they pick up the new one."],[37.396,40.304,"And the places where users pick it up are called channels."],[40.385,42.675,"Teams, a website, a mobile app."],[43.376,44.492,"First rule."],[44.573,46.351,"Saving is not publishing."],[46.432,50.855,"Your saved changes stay in your draft, and only you see them in the test pane."],[50.936,54.996,"When you select Publish, every connected channel is updated at once."],[55.077,59.351,"Teams, the website and the mobile app get the same new edition together."],[59.432,61.828,"So you never republish channel by channel."],[61.909,63.41,"One Publish is enough."],[64.111,65.184,"Your turn."],[65.265,68.622,"Valeria saved a change, and it works in the test pane."],[68.703,73.744,"But users on Teams and on the website don't see it, even in new conversations."],[73.825,74.984,"What is missing?"],[75.065,77.206,"Republish each channel one by one?"],[77.287,79.384,"Select Publish once for the agent?"],[79.465,81.606,"Or wait for the save to reach channels?"],[81.687,83.422,"Decide before I answer."],[87.003,88.567,"Select Publish once."],[88.648,90.724,"Saving only updates the draft."],[90.805,94.162,"One Publish updates every connected channel together."],[94.863,96.406,"Now Marta's mystery."],[96.487,99.096,"A session is a conversation in progress."],[99.177,102.384,"New content only applies when a new session starts."],[102.465,106.398,"In most channels, that happens after thirty minutes of inactivity."],[106.479,110.731,"Teams keeps conversations open, so the old session can stay alive."],[110.812,114.126,"There, the user can type start over to force a new session."],[114.207,116.432,"Otherwise, it can take up to an hour."],[117.133,118.207,"Your turn."],[118.288,122.362,"The fix is published, but Marta's conversation in Teams is still open,"],[122.362,124.716,"and she keeps getting the old answer."],[124.797,127.343,"Valeria wants her to see the fix right now."],[127.424,128.839,"What should Marta do?"],[128.92,130.612,"Type start over in the chat?"],[130.693,132.514,"Publish again just for Teams?"],[132.595,134.628,"Or reinstall the app in Teams?"],[134.709,136.444,"Decide before I answer."],[140.025,141.355,"Type start over."],[141.436,145.368,"It forces a new session, and new sessions get the published content."],[145.449,147.462,"Publishing again changes nothing."],[148.163,150.154,"So where can users meet the agent?"],[150.235,153.186,"There is Teams and Microsoft three sixty five."],[153.267,156.9,"There is the Demo website, a quick page to try the agent."],[156.981,159.762,"And there are others, such as WhatsApp and Facebook."],[159.843,163.05,"One family deserves a name: Direct Line channels."],[163.131,167.063,"It covers the Demo website, custom websites and mobile apps."],[167.144,171.418,"And watch out: some channels require authentication before they work."],[172.119,174.6,"Who decides which channels makers may use?"],[174.681,176.011,"The administrator."],[176.092,179.619,"Each channel has its own connector in the data policies."],[179.7,182.758,"Teams and Microsoft three sixty five has one."],[182.839,184.744,"Direct Line channels has one."],[184.825,186.838,"WhatsApp and Facebook have their own."],[186.919,190.804,"So if the administrator blocks the WhatsApp and Facebook connectors,"],[190.804,193.518,"makers can no longer use those two channels."],[193.599,195.654,"Teams and the website keep working."],[196.355,197.428,"Your turn."],[197.509,200.8,"Contoso's administrator puts the Direct Line channels"],[200.8,203.98,"connector in the Blocked group of a data policy."],[204.061,206.522,"Makers ask which channels they just lost."],[206.603,208.764,"Which channels can they no longer use?"],[208.845,210.772,"Every channel, even Teams?"],[210.853,212.546,"The Demo website alone?"],[212.627,214.49,"Or websites and mobile apps?"],[214.571,216.306,"Decide before I answer."],[219.887,221.622,"Websites and mobile apps."],[221.703,226.126,"Direct Line covers the Demo website, custom websites and mobile apps."],[226.207,228.07,"Teams has its own connector."],[228.771,230.783,"Here is how it looks in the studio."],[230.864,233.986,"Open Nexo and check that your changes are saved."],[234.067,235.93,"Select Publish and confirm."],[236.011,239.026,"Then go to Channels to see which ones are available."],[239.107,244.255,"Pick one, for example Teams or the Demo website, and follow its connection steps."],[244.336,246.818,"Check whether it requires authentication."],[246.899,251.002,"Finally, open a new conversation in the channel to see your change."],[251.703,253.16,"Back at Contoso."],[253.241,257.302,"Marta types start over, and Nexo gives her the new returns answer."],[257.383,258.819,"Nothing was broken."],[258.9,261.723,"Her session had simply started before the fix."],[261.804,263.24,"Remember three things."],[263.321,265.504,"One Publish updates every channel."],[265.585,267.704,"Only a new session sees the change."],[267.785,271.547,"And each channel has its own connector in the data policies."],[271.628,276.307,"Next, keeping the agent safe and fair: responsible AI and moderation."]],"quiz":[{"at":81.687,"question":"Valeria saved a change, and it works in the test pane. But users on Teams and on the website don't see it, even in new conversations. What is missing?","options":["Republish each channel one by one","Select Publish once for the agent","Wait for the save to reach channels"],"right":1,"trap":0,"answerAt":87.003},{"at":134.709,"question":"The fix is published, but Marta's conversation in Teams is still open, and she keeps getting the old answer. Valeria wants her to see the fix right now. What should Marta do?","options":["Type start over in the chat","Publish again just for Teams","Reinstall the app in Teams"],"right":0,"trap":1,"answerAt":140.025},{"at":214.571,"question":"Contoso's administrator puts the Direct Line channels connector in the Blocked group of a data policy. Makers ask which channels they just lost. Which channels can they no longer use?","options":["Every channel, even Teams","The Demo website alone","Websites and mobile apps"],"right":2,"trap":1,"answerAt":219.887}],"poster":"video/L03.jpg"},"L07":{"src":"video/L07.mp4","duration":289.438,"scenes":[{"start":0},{"start":22.642},{"start":40.089},{"start":62.421},{"start":78.819},{"start":115.097},{"start":140.589},{"start":174.711},{"start":200.481},{"start":234.689},{"start":258.773}],"cues":[[0.8,3.367,"Contoso wants Nexo in two places."],[3.448,5.396,"On the intranet, for employees."],[5.477,7.959,"And on the public website, for customers."],[8.04,10.266,"Valeria connects the website fast."],[10.347,13.148,"She pastes the secret straight into the page code."],[13.229,17.119,"That afternoon, a visitor opens the page source and copies it."],[17.2,20.416,"Today you learn how to protect an agent for each audience,"],[20.416,22.391,"and where that secret must live."],[23.092,24.955,"Think of the Contoso office."],[25.036,28.883,"Employees enter through the staff door, and the door asks for a badge."],[28.964,32.726,"Customers go to the public desk, which is open to everyone."],[32.807,35.331,"Same building, two very different doors."],[35.412,37.36,"Your agent works the same way."],[37.441,39.838,"Who uses it decides how you protect it."],[40.539,43.618,"For employees, use Authenticate with Microsoft."],[43.699,44.986,"That is the badge."],[45.067,46.823,"The user always signs in."],[46.904,51.732,"Then the Share option controls who in the organization can chat with the agent."],[51.813,56.044,"So Marta from sales gets in, because the agent is shared with her team."],[56.125,58.981,"And remember: the Teams and Microsoft three"],[58.981,62.17,"sixty five channels support only this option."],[62.871,66.056,"For the anonymous public, there is No authentication."],[66.137,67.744,"That is the open desk."],[67.825,71.779,"Anyone with the link can talk to the agent, and nobody signs in."],[71.86,73.062,"Use it with care."],[73.143,76.646,"Only choose it when the agent does not touch internal data,"],[76.646,78.568,"like a public returns policy."],[79.269,80.343,"Your turn."],[80.424,83.823,"Nexo now answers questions about salaries and leave."],[83.904,87.712,"Compliance says only members of the HR security group may chat,"],[87.712,89.906,"controlled with the Share option."],[89.987,91.892,"Which setting makes this possible?"],[91.973,94.306,"Authenticate with Microsoft and Share?"],[94.387,96.783,"No authentication with a private link?"],[96.864,99.538,"Or Require secured access with one secret?"],[99.619,101.354,"Decide before I answer."],[104.935,108.12,"Authenticate with Microsoft and Share it with the group."],[108.201,112.838,"Users always sign in, and Share decides who in the organization can chat."],[112.919,114.846,"A private link protects nothing."],[115.547,117.175,"Now the public website."],[117.256,120.389,"By default, anyone who knows the agent's ID can"],[120.389,123.855,"use the Demo website and Custom website channels."],[123.936,126.93,"To close that, turn on Require secured access."],[127.011,129.885,"Now the client must authenticate with a secret,"],[129.885,132.714,"or with a token generated from that secret."],[132.795,135.063,"Careful: this protects the web channel."],[135.144,137.498,"It does not make each customer sign in."],[137.579,140.338,"And the change can take up to two hours to apply."],[141.039,142.112,"Your turn."],[142.193,146.702,"Contoso turns on Require secured access for its public website."],[146.783,150.672,"Marketing worries that every customer must now create an account."],[150.753,151.891,"What is true?"],[151.972,154.71,"Every customer must sign in with Microsoft?"],[154.791,157.443,"It only applies to users outside the network?"],[157.524,160.646,"Or the page client needs a secret or a token?"],[160.727,162.462,"Decide before I answer."],[166.043,169.036,"The page client needs a secret or a token."],[169.117,172.111,"Require secured access protects the web channel."],[172.192,174.46,"Customers still chat without signing in."],[175.161,177.003,"Here is Valeria's mistake."],[177.084,180.376,"Code that runs in the browser can be read by anyone."],[180.457,182.534,"So the secret must never be there."],[182.615,187.464,"Instead, Contoso's own server keeps the secret, like a safe in the back room."],[187.545,192.331,"When a visitor opens the page, the server exchanges the secret for a token."],[192.412,197.667,"The token is valid for a single conversation, and it expires if it isn't refreshed."],[197.748,200.23,"The page only ever receives the token."],[200.931,202.004,"Your turn."],[202.085,206.551,"The secret sits in the website's JavaScript, and any visitor can copy it."],[206.632,209.946,"Valeria must fix this and keep the agent protected."],[210.027,211.271,"What should she do?"],[211.352,214.132,"Move the secret into an HTML comment?"],[214.213,216.93,"Turn off Require secured access entirely?"],[217.011,219.428,"Or have the server send the page a token?"],[219.509,221.244,"Decide before I answer."],[224.825,227.072,"Have the server send the page a token."],[227.153,229.123,"The secret stays on the server."],[229.204,234.438,"An HTML comment is still readable, and turning security off opens the channel."],[235.139,237.151,"Here is how it looks in the studio."],[237.232,240.354,"Open Nexo and go to Settings, then Security."],[240.435,244.964,"Open Web channel security and turn on Require secured access."],[245.045,248.807,"Look at the secrets it generates, and store them only on your server."],[248.888,253.375,"On the server, create a service that uses the secret to request a token."],[253.456,256.087,"Make the web page receive only the token."],[256.168,258.522,"Then test a conversation from the page."],[259.223,260.68,"Back at Contoso."],[260.761,262.647,"Marta signs in on the intranet,"],[262.647,266.742,"and the web visitor chats with a token, never seeing the secret."],[266.823,268.259,"Remember three things."],[268.34,272.806,"Employees: Authenticate with Microsoft, and Share decides who chats."],[272.887,277.267,"Anonymous public: No authentication, only without internal data."],[277.348,282.198,"Your own website: Require secured access, with the token made on the server."],[282.279,284.035,"That closes module one."],[284.116,285.936,"Next, variables and scope."]],"quiz":[{"at":99.619,"question":"Nexo now answers questions about salaries and leave. Compliance says only members of the HR security group may chat, controlled with the Share option. Which setting makes this possible?","options":["Authenticate with Microsoft and Share","No authentication with a private link","Require secured access with one secret"],"right":0,"trap":1,"answerAt":104.935},{"at":160.727,"question":"Contoso turns on Require secured access for its public website. Marketing worries that every customer must now create an account. What is true?","options":["Every customer must sign in with Microsoft","It only applies to users outside the network","The page client needs a secret or a token"],"right":2,"trap":0,"answerAt":166.043},{"at":219.509,"question":"The secret sits in the website's JavaScript, and any visitor can copy it. Valeria must fix this and keep the agent protected. What should she do?","options":["Move the secret into an HTML comment","Turn off Require secured access entirely","Have the server send the page a token"],"right":2,"trap":0,"answerAt":224.825}],"poster":"video/L07.jpg"},"L08":{"src":"video/L08.mp4","duration":285.314,"scenes":[{"start":0},{"start":16.709},{"start":36.009},{"start":56.482},{"start":92.226},{"start":109.115},{"start":126.623},{"start":161.13},{"start":195.987},{"start":234.803},{"start":259.482}],"cues":[[0.8,3.858,"Marta opens Nexo to ask about her vacation."],[3.939,7.146,"Nexo asks for her employee number, and she types it."],[7.227,9.154,"Then she asks about her payslip."],[9.235,11.503,"Nexo asks for the same number again."],[11.584,12.786,"Marta sighs."],[12.867,16.458,"Today you learn where an agent keeps data, and who can use it."],[17.159,20.387,"Think of a variable as a small box with a name on it."],[20.468,23.919,"Inside, the agent keeps one piece of data to use later,"],[23.919,26.064,"like a name or a ticket number."],[26.145,28.414,"The scope says who can open the box."],[28.495,31.019,"Only one topic, or the whole agent."],[31.1,35.758,"Contoso's problem is simple: the box was locked inside one topic."],[36.459,40.178,"When you create a variable, it is a topic variable by default."],[40.259,43.06,"It lives only in the topic where you created it."],[43.141,46.306,"The payroll topic cannot see it, so it asks again."],[46.387,51.194,"A global variable carries the prefix Global dot, and it works in all topics."],[51.275,56.231,"So Global dot EmployeeId is filled once, and every topic reuses it."],[56.932,58.006,"Your turn."],[58.087,63,"Contoso's vacation topic saves the employee number in a topic variable."],[63.081,67.675,"The payroll and benefits topics need the same number without asking again."],[67.756,68.958,"What should you do?"],[69.039,71.435,"Copy the question into every topic?"],[71.516,73.742,"Change the variable scope to global?"],[73.823,76.24,"Or make it a new system variable instead?"],[76.321,78.056,"Decide before I answer."],[81.637,83.863,"Change the variable scope to global."],[83.944,86.575,"You do it in the variable's properties panel."],[86.656,89.426,"Copying the question only asks the user again,"],[89.426,91.975,"and you cannot create system variables."],[92.676,94.752,"Some boxes come already filled."],[94.833,97.891,"Copilot Studio creates system variables for you."],[97.972,102.352,"System dot Activity dot Text holds the last thing the user typed."],[102.433,106.259,"System dot User dot DisplayName holds the user's name."],[106.34,108.864,"You read them, but you do not create them."],[109.565,112.367,"Each box also has a shape, called its type."],[112.448,115.335,"A variable takes its type from its first assignment."],[115.416,118.068,"If it starts with a number, it stays a Number."],[118.149,121.1,"Later, if you try to put text in it, you get an error."],[121.181,123.677,"The types include String, Boolean, Number,"],[123.677,126.372,"Table, Record, DateTime, Choice and Blank."],[127.073,128.147,"Your turn."],[128.228,133.611,"Valeria first sets Global dot EmployeeId to the number four two one five."],[133.692,138.499,"Later, a node saves the text E four two one five in the same variable."],[138.58,139.696,"What happens?"],[139.777,141.982,"An error: the type is already Number?"],[142.063,144.331,"It quietly converts itself to a String?"],[144.412,146.83,"Or the text is stored as the number zero?"],[146.911,148.646,"Decide before I answer."],[152.227,154.516,"An error: the type is already Number."],[154.597,158.039,"The type comes from the first assignment, and it does not change."],[158.12,160.879,"If an ID can have letters, start it as text."],[161.58,163.571,"Now the inventory interface."],[163.652,167.883,"In development it must call a test server, and in production the real one."],[167.964,173.923,"Contoso keeps that address in an environment variable, Env dot ApiBaseUrl."],[174.004,177.248,"Environment variables are created in Power Platform,"],[177.248,180.006,"and they are read-only in Copilot Studio."],[180.087,184.552,"The administrator changes their values in Power Apps, not in the topic."],[184.633,189.355,"So the same agent moves between environments without touching a single node."],[189.436,192.147,"If a value changes, you republish the agent,"],[192.147,195.736,"except for secret-type ones, which are read at runtime."],[196.437,197.511,"Your turn."],[197.592,202.783,"Nexo calls an inventory address that is different in development and in production."],[202.864,206.455,"Contoso wants to move the agent without editing any node."],[206.536,207.823,"What should you use?"],[207.904,210.428,"A global variable set in every topic?"],[210.509,212.948,"A system variable that holds the address?"],[213.029,215.554,"Or an environment variable for the address?"],[215.635,217.37,"Decide before I answer."],[220.951,223.262,"An environment variable for the address."],[223.343,225.83,"It separates the parameter from the logic,"],[225.83,229.11,"and the administrator sets each value in Power Apps."],[229.191,232.038,"A global variable still means editing the agent,"],[232.038,234.552,"and you cannot create system variables."],[235.253,237.266,"Here is how it looks in the studio."],[237.347,242.41,"Open the vacation topic and add a Question node that asks for the employee number."],[242.491,246.914,"Under Save user response as, create a variable called EmployeeId."],[246.995,251.268,"Select it, open Variable properties, and change its scope to global."],[251.349,256.05,"In the payroll topic, add a Message and insert Global dot EmployeeId."],[256.131,259.231,"Test in the test chat and watch the variables panel."],[259.932,261.155,"Back to Marta."],[261.236,265.019,"She types her number once, and the payroll topic greets her with it."],[265.1,266.664,"Remember four boxes."],[266.745,270.635,"Topic is the default, and Global dot works in all topics."],[270.716,273.475,"System variables come from Copilot Studio."],[273.556,277.04,"Env dot comes from Power Platform and is read-only here."],[277.121,279.24,"And the first value fixes the type."],[279.321,281.312,"Next, formatted responses."]],"quiz":[{"at":76.321,"answerAt":81.637,"question":"Contoso's vacation topic saves the employee number in a topic variable. The payroll and benefits topics need the same number without asking again. What should you do?","options":["Copy the question into every topic","Change the variable scope to global","Make it a new system variable instead"],"right":1,"trap":0},{"at":146.911,"answerAt":152.227,"question":"Valeria first sets Global.EmployeeId to the number 4215. Later, a node saves the text E4215 in the same variable. What happens?","options":["An error: the type is already Number","It quietly converts itself to a String","The text is stored as the number zero"],"right":0,"trap":1},{"at":215.635,"answerAt":220.951,"question":"Nexo calls an inventory address that is different in development and in production. Contoso wants to move the agent without editing any node. What should you use?","options":["A global variable set in every topic","A system variable that holds the address","An environment variable for the address"],"right":2,"trap":0}],"poster":"video/L08.jpg"},"L09":{"src":"video/L09.mp4","duration":275.686,"scenes":[{"start":0},{"start":21.637},{"start":38.035},{"start":54.029},{"start":86.893},{"start":106.003},{"start":137.566},{"start":161.306},{"start":181.739},{"start":219.574},{"start":248.351}],"cues":[[0.8,3.58,"Contoso's help desk agent looks up a ticket."],[3.661,6.228,"On Monday it says the ticket is in progress."],[6.309,10.519,"On Tuesday, same ticket, it says someone is probably working on it."],[10.6,14.148,"The service manager wants the exact status, every time."],[14.229,18.14,"And when users must pick a request type, they type whatever they like."],[18.221,21.386,"Today you learn how to give each answer the right shape."],[22.087,24.312,"Think of two ways to answer a customer."],[24.393,27.43,"A handwritten note can say anything, in any words."],[27.511,31.187,"A form with checkboxes only accepts the boxes you print."],[31.268,33.792,"A good agent chooses the shape on purpose."],[33.873,37.784,"Sometimes exact text, sometimes buttons, sometimes a card."],[38.485,41.266,"The Message node sends a message to the user."],[41.347,45.3,"It can carry basic formatting and variables, like the user's name."],[45.381,48.055,"It can show images, videos and cards."],[48.136,51.194,"It can add quick replies and message variations."],[51.275,53.778,"The Question node can do all of this too."],[54.479,55.552,"Your turn."],[55.633,60.142,"Contoso's greeting uses exactly the same words every single time."],[60.223,64.56,"Users say the agent sounds robotic, and the meaning must stay the same."],[64.641,65.843,"What should you add?"],[65.924,67.766,"Quick replies under the greeting?"],[67.847,69.859,"Message variations on the node?"],[69.94,72.059,"Or an adaptive card with the greeting?"],[72.14,73.875,"Decide before I answer."],[77.456,79.554,"Message variations on the node."],[79.635,83.162,"The agent picks one of several wordings at random each time."],[83.243,86.642,"Quick replies and cards change the shape, not the wording."],[87.343,88.907,"Now the request type."],[88.988,92.686,"Valeria adds quick replies: hardware, software, access."],[92.767,95.483,"They look like a choice, but they only suggest."],[95.564,98.6,"The user can ignore them and type anything at all."],[98.681,103.126,"To make the user pick from a list, use a Question node with multiple choice."],[103.207,105.752,"Then the answer is always one of your options."],[106.453,107.527,"Your turn."],[107.608,112.138,"A ticket must be labelled hardware, software or access, and nothing else."],[112.219,115.084,"Users must not be able to type a different type."],[115.165,116.815,"What should Contoso use?"],[116.896,118.951,"A multiple choice Question node?"],[119.032,121.087,"Quick replies on a Message node?"],[121.168,123.564,"Or message variations for each type?"],[123.645,125.38,"Decide before I answer."],[128.961,130.995,"A multiple choice Question node."],[131.076,133.302,"The user must pick one of your options."],[133.383,137.315,"Quick replies only suggest, and the user can still type freely."],[138.016,139.26,"Next, tools."],[139.341,144.148,"When a tool finishes, the After running option decides how the agent responds."],[144.229,149.1,"Don't respond is the default: the agent folds the output into its own answer."],[149.181,153.69,"Write the response with generative AI lets the AI write the reply."],[153.771,157.682,"Send specific response uses your own template with variables."],[157.763,161.055,"And Send an adaptive card shows an interactive card."],[161.756,163.064,"Back to the ticket."],[163.145,167.935,"With Send specific response, Valeria writes a template with two output variables,"],[167.935,170.086,"the ticket number and the status."],[170.167,172.627,"She can even use Power Fx formulas."],[172.708,174.486,"The model does not rewrite it."],[174.567,177.665,"So the user always sees Ticket four eight two one,"],[177.665,179.971,"status In progress, word for word."],[180.052,181.488,"Every single time."],[182.189,183.263,"Your turn."],[183.344,186.883,"After the ticket lookup tool runs, the service manager wants"],[186.883,190.327,"the same exact sentence with the number and the status."],[190.408,192.164,"No rewording by the model."],[192.245,194.236,"Which After running option fits?"],[194.317,196.756,"Write the response with generative AI?"],[196.837,198.871,"Don't respond, the default setting?"],[198.952,201.434,"Or Send specific response, a template?"],[201.515,203.25,"Decide before I answer."],[206.831,209.184,"Send specific response, a template."],[209.265,213.411,"The model does not rewrite it, so the text is exactly what you defined."],[213.492,215.563,"Generative AI rewords the reply,"],[215.563,219.323,"and Don't respond folds it into the agent's own answer."],[220.024,222.036,"Here is how it looks in the studio."],[222.117,225.708,"Open a topic, select Add node, and add a Message node."],[225.789,229.85,"Type the text and use the variable icon to insert a value."],[229.931,233.308,"On the node toolbar, select Add, then Quick reply."],[233.389,237.535,"To force a choice, add a Question node with multiple choice instead."],[237.616,242.722,"Then open the ticket tool, find After running, and choose Send specific response."],[242.803,245.074,"Write the template with output variables,"],[245.074,248.1,"and compare it in the test chat with Don't respond."],[248.801,250.28,"Back at the help desk."],[250.361,255.51,"Every user now sees the exact ticket status, and every ticket has a valid type."],[255.591,257.091,"Remember three shapes."],[257.172,260.23,"Message variations change the wording at random."],[260.311,265.203,"Quick replies only suggest, and a multiple choice Question forces the choice."],[265.284,269.878,"After a tool, Send specific response gives exact text from your template."],[269.959,272.184,"Next, the generative answers node."]],"quiz":[{"at":72.14,"answerAt":77.456,"question":"Contoso's greeting uses exactly the same words every single time. Users say the agent sounds robotic, and the meaning must stay the same. What should you add?","options":["Quick replies under the greeting","Message variations on the node","An adaptive card with the greeting"],"right":1,"trap":0},{"at":123.645,"answerAt":128.961,"question":"A ticket must be labelled hardware, software or access, and nothing else. Users must not be able to type a different type. What should Contoso use?","options":["A multiple choice Question node","Quick replies on a Message node","Message variations for each type"],"right":0,"trap":1},{"at":201.515,"answerAt":206.831,"question":"After the ticket lookup tool runs, the service manager wants the same exact sentence with the number and the status. No rewording by the model. Which After running option fits?","options":["Write the response with generative AI","Don't respond, the default setting","Send specific response, a template"],"right":2,"trap":0}],"poster":"video/L09.jpg"},"L10":{"src":"video/L10.mp4","duration":274.692,"scenes":[{"start":0},{"start":18.455},{"start":35.689},{"start":54.986},{"start":72.814},{"start":112.889},{"start":130.055},{"start":166.439},{"start":185.014},{"start":222.977},{"start":246.29}],"cues":[[0.8,4.519,"Contoso's HR agent is asked about parental leave."],[4.6,7.764,"The answer sounds sure, but it quotes a marketing page."],[7.845,11.564,"Valeria wants answers only from the HR policies site."],[11.645,14.81,"And she wants to show them in a card with the company style."],[14.891,18.204,"Today you learn how the Generative answers node does it."],[18.905,20.406,"Think of a librarian."],[20.487,21.902,"You ask a question."],[21.983,24.462,"The librarian goes to the shelves you point to,"],[24.462,27.088,"reads what is there, and writes you an answer."],[27.169,28.755,"You never choose the words."],[28.836,30.251,"You choose the shelves."],[30.332,35.438,"That is the Generative answers node: a librarian that works inside one topic."],[36.139,40.775,"With this node, the agent answers from knowledge sources inside a topic."],[40.856,43.459,"The sources can be documents in Dataverse,"],[43.459,46.324,"SharePoint sites, public websites and more."],[46.405,48.736,"And when no topic matches a question,"],[48.736,52.087,"the agent uses generative answers as its fallback."],[52.168,54.735,"The answer can also be saved to a variable."],[55.436,57.448,"Here is the setting that fixes it."],[57.529,60.453,"By default, Search only selected sources is off,"],[60.453,63.638,"and the node searches all of the agent's sources."],[63.719,67.352,"Turn it on, and the node searches only the sources you select."],[67.433,70.107,"They replace the agent's sources for that node."],[70.188,72.563,"There is no fallback to the agent's sources."],[73.264,74.338,"Your turn."],[74.419,79.237,"Contoso's HR topic answers leave questions with a Generative answers node,"],[79.237,82.106,"but marketing documents keep slipping in."],[82.187,85.671,"The answers must come only from the policies SharePoint site."],[85.752,87.444,"What should Valeria turn on?"],[87.525,89.644,"Moderation level set to Highest?"],[89.725,91.546,"A separate fallback topic?"],[91.627,93.895,"Or Search only selected sources?"],[93.976,95.711,"Decide before I answer."],[99.292,101.368,"Search only selected sources."],[101.449,104.158,"Then the node uses only the sources you choose,"],[104.158,107.067,"and other departments cannot affect the answer."],[107.148,109.62,"Moderation sets how strict the answers are,"],[109.62,112.638,"and a fallback topic does not choose the sources."],[113.339,115.116,"Next, the look of the answer."],[115.197,118.852,"Valeria wants it in an adaptive card with the company style."],[118.933,121.692,"So she saves the answer in a global variable."],[121.773,124.34,"Then she clears the Send a message checkbox."],[124.421,127.463,"Now the agent no longer returns the answer right away,"],[127.463,129.804,"and she presents it however she likes."],[130.505,131.579,"Your turn."],[131.66,136.446,"Valeria turned on Search only selected sources and chose the policies site."],[136.527,139.243,"A user asks something that site does not cover."],[139.324,140.888,"Which statement is true?"],[140.969,143.835,"It still falls back to all of the agent's sources?"],[143.916,146.867,"The selected sources replace the agent's sources?"],[146.948,149.75,"Or the chosen sources are added to the agent's?"],[149.831,151.566,"Decide before I answer."],[155.147,158.247,"The selected sources replace the agent's sources."],[158.328,162.068,"For that node, there is no fallback to the agent's other sources."],[162.149,166.188,"So a question outside the chosen site is not rescued by the rest."],[166.889,168.283,"But there is a catch."],[168.364,171.33,"In Teams, citations are returned automatically"],[171.33,174.302,"only for responses you have not customized."],[174.383,179.147,"If you customize the answer, you must include the citation rendering yourself."],[179.228,183.246,"The node also has its own moderation level, from Lowest to Highest."],[183.327,184.763,"The default is High."],[185.464,186.538,"Your turn."],[186.619,190.89,"Contoso clears Send a message, saves the answer in a global variable,"],[190.89,193.132,"and shows it in an adaptive card."],[193.213,195.759,"The agent is also published in Teams."],[195.84,197.959,"What must Contoso add to the card?"],[198.04,200.244,"The citation rendering in the card?"],[200.325,203.042,"Nothing, Teams adds citations by itself?"],[203.123,205.348,"Or a second Generative answers node?"],[205.429,207.164,"Decide before I answer."],[210.745,213.014,"The citation rendering in the card."],[213.095,215.899,"In Teams, citations come back automatically"],[215.899,218.904,"only for responses you have not customized."],[218.985,222.726,"Once you customize, you must include the citations yourself."],[223.427,225.439,"Here is how it looks in the studio."],[225.52,228.322,"Open the Topics page and enter your topic."],[228.403,232.378,"Select Add node, point to Advanced, and choose Generative answers."],[232.459,237.564,"Open the node properties, and under Input select the System Activity Text variable."],[237.645,241.343,"Turn on Search only selected sources and choose your source."],[241.424,246.039,"Then test with a question that only another source knows, and see what happens."],[246.74,248.454,"Back in the records archive."],[248.535,251.105,"Answers now come only from the policies site,"],[251.105,253.875,"and the card shows them in the company style."],[253.956,255.392,"Remember three things."],[255.473,260.387,"Search only selected sources replaces the agent's sources, with no fallback."],[260.468,264.187,"Clearing Send a message means you add the citations yourself."],[264.268,268.414,"And moderation goes from Lowest to Highest, with High as the default."],[268.495,271.19,"Next, custom data and your own sources."]],"quiz":[{"at":93.976,"answerAt":99.292,"question":"Contoso's HR topic answers leave questions with a Generative answers node, but marketing documents keep slipping in. The answers must come only from the policies SharePoint site. What should Valeria turn on?","options":["Moderation level set to Highest","A separate fallback topic","Search only selected sources"],"right":2,"trap":0},{"at":149.831,"answerAt":155.147,"question":"Valeria turned on Search only selected sources and chose the policies site. A user asks something that site does not cover. Which statement is true?","options":["It still falls back to all of the agent's sources","The selected sources replace the agent's sources","The chosen sources are added to the agent's"],"right":1,"trap":0},{"at":205.429,"answerAt":210.745,"question":"Contoso clears Send a message, saves the answer in a global variable, and shows it in an adaptive card. The agent is also published in Teams. What must Contoso add to the card?","options":["The citation rendering in the card","Nothing, Teams adds citations by itself","A second Generative answers node"],"right":0,"trap":1}],"poster":"video/L10.jpg"},"L11":{"src":"video/L11.mp4","duration":265.044,"scenes":[{"start":0},{"start":18.626},{"start":38.057},{"start":56.095},{"start":74.71},{"start":94.138},{"start":129.157},{"start":147.366},{"start":182.577},{"start":205.591},{"start":239.586}],"cues":[[0.8,4.156,"Contoso's support team keeps an incident database."],[4.237,8.575,"Marta asks about a printer fault, and the agent gives a general answer."],[8.656,11.635,"Valeria wants answers built only from the articles"],[11.635,14.039,"her own flow picks, each with a link."],[14.12,15.983,"Today you learn Custom data."],[16.064,18.375,"It is how you hand the node your own data."],[19.076,21.323,"Picture a kitchen with a serving hatch."],[21.404,22.84,"Nexo is the cook."],[22.921,25.958,"Usually it takes ingredients from the pantry shelves."],[26.039,28.883,"With Custom data, you hand it a tray instead."],[28.964,32.107,"The information is not in a file or on a website."],[32.188,35.04,"You calculate it yourself, with a flow or a query,"],[35.04,37.806,"and the cook serves only what is on the tray."],[38.507,42.168,"The option is in the properties of the Generative answers node,"],[42.168,44.402,"in the section called Classic data."],[44.483,46.751,"There you put a variable of type Table."],[46.832,50.972,"Use it when the source is a private API or the result of a flow,"],[50.972,52.983,"not a public site or a file."],[53.064,55.844,"At Contoso, the table comes out of a flow."],[56.545,58.835,"Each row in the table needs Content."],[58.916,61.931,"It is required, and it holds the article text."],[62.012,64.807,"Optionally, a row can have ContentLocation,"],[64.807,69.166,"the address used for the citation, and Title, the article title."],[69.247,71.075,"With ContentLocation filled in,"],[71.075,74.459,"the agent can cite the link of each article for Marta."],[75.16,76.319,"Now the limit."],[76.4,80.034,"Only the first three records are used to generate the answer."],[80.115,84.708,"So there is no point sending hundreds of rows and hoping the node reads them all."],[84.789,89.767,"Filter and sort the table before you pass it, with the most relevant rows on top."],[89.848,93.887,"Contoso's flow does exactly that, and returns three articles."],[94.588,95.662,"Your turn."],[95.743,99.846,"Contoso's incident flow finds hundreds of matching articles."],[99.927,101.662,"Valeria must pass them on."],[101.743,103.904,"What should she do with the table first?"],[103.985,106.766,"Send every row and let the node read them all?"],[106.847,109.67,"Filter and sort first, best rows on top?"],[109.751,112.04,"Or pass the first three rows as they come?"],[112.121,113.856,"Decide before I answer."],[117.437,120.282,"Filter and sort first, best rows on top."],[120.363,124.466,"Only the first three records are used, so the best rows go on top."],[124.547,128.906,"More rows do not raise the limit, and unsorted rows can miss the best."],[129.607,131.649,"To answer only from your table,"],[131.649,135.736,"turn on Search only selected sources and select no sources."],[135.817,138.171,"Then put your variable in Custom data."],[138.252,142.611,"Turn off Web search and Allow the AI to use its own general knowledge."],[142.692,147.115,"Now the agent answers only from the three articles and cites each link."],[147.816,148.89,"Your turn."],[148.971,153.906,"Contoso's flow returns a table of three articles, already in Custom data."],[153.987,156.81,"The agent must answer only from that table."],[156.891,160.183,"What should Valeria do with Search only selected sources?"],[160.264,162.575,"Turn it on and select no sources?"],[162.656,164.988,"Turn it on and select all sources?"],[165.069,167.53,"Or leave it off and let the agent decide?"],[167.611,169.346,"Decide before I answer."],[172.927,175.259,"Turn it on and select no sources."],[175.34,179.656,"Then the node searches no knowledge sources, so only your table is left."],[179.737,182.326,"Selecting all sources brings them back in."],[183.027,185.039,"Here is how it looks in the studio."],[185.12,188.626,"Open the Generative answers node and go to Properties."],[188.707,192.831,"Turn on Search only selected sources and select no sources."],[192.912,196.226,"Under Classic data, put your variable in Custom data."],[196.307,200.666,"Turn off Web search and Allow the AI to use its own general knowledge."],[200.747,205.34,"Then test a question and check that the citation uses ContentLocation."],[206.041,207.115,"Your turn."],[207.196,212.302,"Contoso is checking the table its flow returns before sending it to Custom data."],[212.383,215.76,"Valeria wants to know which field no row can be missing."],[215.841,217.171,"Which field is it?"],[217.252,219.904,"ContentLocation, because it holds the link?"],[219.985,222.296,"Title, because the answer needs a heading?"],[222.377,224.859,"Or Content, because it holds the text?"],[224.94,226.675,"Decide before I answer."],[230.256,232.46,"Content, because it holds the text."],[232.541,235.002,"Content is the only required field."],[235.083,239.335,"ContentLocation and Title are optional, so a row can leave them out."],[240.036,241.366,"Back in the kitchen."],[241.447,243.95,"Marta asks again, and the answer comes only"],[243.95,246.595,"from the three articles, each with a link."],[246.676,248.112,"Remember three things."],[248.193,250.654,"Content is the only required field."],[250.735,254.475,"Only the first three records count, so filter and sort first."],[254.556,259.79,"And to answer only from your data, use Search only selected sources with no sources."],[259.871,261.542,"Next, Adaptive Cards."]],"quiz":[{"at":112.121,"answerAt":117.437,"question":"Contoso's incident flow finds hundreds of matching articles. Valeria must pass them to Custom data. What should she do with the table first?","options":["Send every row and let the node read them all","Filter and sort first, best rows on top","Pass the first three rows as they come"],"right":1,"trap":0},{"at":167.611,"answerAt":172.927,"question":"Contoso's flow returns a table of three articles, already in Custom data. The agent must answer only from that table. What should Valeria do with Search only selected sources?","options":["Turn it on and select no sources","Turn it on and select all sources","Leave it off and let the agent decide"],"right":0,"trap":1},{"at":224.94,"answerAt":230.256,"question":"Contoso is checking the table its flow returns before sending it to Custom data. Valeria wants to know which field no row can be missing. Which field is it?","options":["ContentLocation, because it holds the link","Title, because the answer needs a heading","Content, because it holds the text"],"right":2,"trap":0}],"poster":"video/L11.jpg"},"L18":{"src":"video/L18.mp4","duration":332.125,"scenes":[{"start":0},{"start":22.53},{"start":45.265},{"start":68.983},{"start":103.725},{"start":123.838},{"start":143.818},{"start":171.763},{"start":208.83},{"start":235.749},{"start":265.035},{"start":300.075}],"cues":[[0.8,4.207,"Marta writes to Nexo that her laptop will not turn on,"],[4.207,6.994,"and CreateTicket must open a ticket fast."],[7.075,9.791,"Valeria opens the flow to add more steps."],[9.872,14.786,"Actions are the steps a flow performs, like the ingredients and tools of a kitchen."],[14.867,19.332,"Some come grouped by type, and others come from connectors to other systems."],[19.413,22.279,"Knowing the groups helps you find what you need quickly."],[22.98,25.931,"The actions of an agent flow come in four groups."],[26.012,29.747,"AI capabilities holds generate text, process documents,"],[29.747,33.614,"Run a prompt, call an agent, and respond to the agent."],[33.695,37.627,"Human in the loop is for approvals or for asking for information."],[37.708,43.112,"Built-in tools holds loops, conditions, data operations, dates, and child flows."],[43.193,45.014,"The fourth group is Connectors."],[45.715,49.412,"Connectors bring actions from other systems, such as Dataverse."],[49.493,53.66,"CreateTicket uses the Dataverse connector to add the ticket row."],[53.741,56.388,"Run a prompt lives inside AI capabilities,"],[56.388,59.487,"and it runs a prompt at one point in the flow."],[59.568,63.138,"Valeria selects Insert new action where she wants the step."],[63.219,66.063,"Then she chooses an existing prompt or a new one."],[66.144,68.732,"Here, the prompt summarizes Marta's text."],[69.433,70.507,"Your turn."],[70.588,74.563,"Valeria wants a step that summarizes Marta's text with a prompt."],[74.644,77.446,"She selects Insert new action in CreateTicket."],[77.527,79.496,"Where should she look for Run a prompt?"],[79.577,81.398,"Look under the Connectors group?"],[81.479,83.512,"Look under AI capabilities?"],[83.593,85.392,"Or look under Built-in tools?"],[85.473,87.208,"Decide before I answer."],[90.789,92.866,"Look under AI capabilities."],[92.947,95.741,"Run a prompt is one of the AI capabilities,"],[95.741,98.799,"next to generate text and process documents."],[98.88,103.474,"Connectors bring actions from other systems, such as Dataverse, not prompts."],[104.175,105.312,"Now speed."],[105.393,110.094,"By default, a flow that takes more than two minutes to respond to the agent fails."],[110.175,113.36,"Marta would be left waiting, and Nexo would get an error."],[113.441,115.048,"Express mode helps here."],[115.129,118.714,"It speeds up flows with heavy processing and low data volume,"],[118.714,121.558,"so they finish inside that two-minute window."],[121.639,123.587,"Express mode is in preview."],[124.288,128.071,"Two figures appear in Microsoft's pages, so keep them apart."],[128.152,132.404,"One hundred seconds is the action limit for a flow used as a tool."],[132.485,137.217,"Two minutes is the default window for an agent flow to respond to the agent,"],[137.217,140.343,"and that is the window express mode helps with."],[140.424,143.567,"When your flow is a tool, plan for one hundred seconds."],[144.268,146.302,"Express mode has requirements."],[146.383,149.672,"The flow needs the When an agent calls a flow trigger,"],[149.672,153.344,"a Respond to the agent action, and a Copilot Studio plan."],[153.425,155.118,"It has no extra cost."],[155.199,156.763,"It also has limits."],[156.844,159.176,"It does not support Delay or webhooks."],[159.257,163.223,"It works poorly with lots of data, so keep each run under about"],[163.223,167.264,"one hundred actions and avoid very large connector responses."],[167.345,171.512,"Long processes are not for express mode; they work asynchronously."],[172.213,173.287,"Your turn."],[173.368,178.538,"Contoso also has a long reconciliation process that moves a lot of data."],[178.619,182.892,"The service manager asks Valeria whether express mode should handle it."],[182.973,184.474,"What should Valeria do?"],[184.555,186.332,"Turn on express mode for it?"],[186.413,188.148,"Add a Delay action to it?"],[188.229,190.028,"Or let it run asynchronously?"],[190.109,191.844,"Decide before I answer."],[195.425,197.075,"Let it run asynchronously."],[197.156,200.247,"Long processes with lots of data are asynchronous,"],[200.247,204.032,"and express mode is for heavy processing with little data."],[204.113,208.579,"Express mode for it is the trap, because it would not fit the two-minute window."],[209.28,211.463,"Here is the whole Contoso case."],[211.544,214.772,"CreateTicket starts with When an agent calls a flow."],[214.853,217.689,"A Dataverse connector inserts the ticket row,"],[217.689,220.599,"and a Run a prompt summarizes Marta's text."],[220.68,223.247,"The flow ends with Respond to the agent."],[223.328,227.712,"It does quite a lot of processing but moves little data, so Contoso turns"],[227.712,232.295,"on express mode, in preview, and it answers within the two-minute window."],[232.376,235.498,"The long reconciliation process does not use it."],[236.199,238.574,"Here are the steps in Copilot Studio."],[238.655,240.24,"Open the agent flow."],[240.321,244.509,"Select Insert new action at the point where you want a step, and review"],[244.509,249.31,"the groups AI capabilities, Human in the loop, Built-in tools, and Connectors."],[249.391,252.467,"Add an action from a connector, such as Dataverse,"],[252.467,255.435,"then add a Run a prompt from AI capabilities."],[255.516,258.077,"Open Overview, select Edit under Details,"],[258.077,261.774,"and turn on Express mode, if your environment offers it."],[261.855,264.784,"Test that the flow responds in under two minutes."],[265.485,266.559,"Your turn."],[266.64,270.146,"Valeria's new flow does heavy processing on little data."],[270.227,274.052,"But it never sends an answer back, and express mode cannot help it."],[274.133,275.634,"What must the flow have?"],[275.715,277.748,"A Respond to the agent action?"],[277.829,279.82,"A Delay action before the end?"],[279.901,282.084,"Or a webhook that calls the agent?"],[282.165,283.9,"Decide before I answer."],[287.481,289.515,"A Respond to the agent action."],[289.596,292.261,"Express mode requires the agent trigger,"],[292.261,296.259,"a Respond to the agent action, and a Copilot Studio plan."],[296.34,299.824,"Delay and webhooks are not supported in express mode at all."],[300.525,304.735,"Back at the market, Marta reads her ticket ID, and Nexo moves on."],[304.816,307.348,"Remember the four groups: AI capabilities,"],[307.348,310.562,"Human in the loop, Built-in tools, and Connectors."],[310.643,313.316,"Run a prompt is in AI capabilities."],[313.397,316.348,"Express mode, in preview, is for heavy processing"],[316.348,319.378,"with little data, inside the two-minute window."],[319.459,324.372,"It needs the agent trigger, Respond to the agent, and a Copilot Studio plan."],[324.453,326.551,"Long processes stay asynchronous."],[326.632,328.623,"Next, error handling in flows."]],"quiz":[{"at":85.473,"answerAt":90.789,"question":"Valeria wants a step that summarizes Marta's text with a prompt. She selects Insert new action in CreateTicket. Where should she look for Run a prompt?","options":["Look under the Connectors group","Look under AI capabilities","Look under Built-in tools"],"right":1,"trap":0},{"at":190.109,"answerAt":195.425,"question":"Contoso has a long reconciliation process that moves a lot of data. The service manager asks whether express mode should handle it. What should Valeria do?","options":["Turn on express mode for it","Add a Delay action to it","Let it run asynchronously"],"right":2,"trap":0},{"at":282.165,"answerAt":287.481,"question":"Valeria's new flow does heavy processing on little data, but it never sends an answer back, and express mode cannot help it. What must the flow have?","options":["A Respond to the agent action","A Delay action before the end","A webhook that calls the agent"],"right":0,"trap":2}],"poster":"video/L18.jpg"},"L19":{"src":"video/L19.mp4","duration":329.53,"scenes":[{"start":0},{"start":23.493},{"start":44.243},{"start":67.749},{"start":100.122},{"start":121.747},{"start":145.829},{"start":182.213},{"start":203.753},{"start":234.511},{"start":264.187},{"start":299.718}],"cues":[[0.8,3.357,"Marta asks Nexo for help with her laptop,"],[3.357,6.738,"and CreateTicket must save her ticket in Dataverse."],[6.819,10.004,"Today the insert fails, and the flow stays silent."],[10.085,13.89,"Valeria knows that errors in a flow are not an if, they are a when."],[13.971,16.41,"Handling them is like having a plan B."],[16.491,20.892,"If the main path fails, the flow knows what to do instead of staying silent."],[20.973,23.242,"The classic pattern is called try catch."],[23.943,28.216,"A scope is a container that groups actions, so they can be handled together."],[28.297,30.522,"Valeria adds a scope, names it Try,"],[30.522,34.982,"and moves the main actions inside it, such as the Dataverse insert."],[35.063,38.675,"Then she adds another scope called Catch, right after the Try."],[38.756,40.534,"The Try is the main path."],[40.615,43.992,"The Catch is the plan B, and it only handles the error."],[44.693,46.343,"So when does the Catch run?"],[46.424,50.944,"That is decided by run after, a setting that defines when an action runs,"],[50.944,53.62,"based on the result of the previous one."],[53.701,58.871,"Run after can check whether an action failed, timed out, was skipped, or succeeded."],[58.952,62.223,"Valeria sets it on the Catch, relative to the Try."],[62.304,64.828,"She selects has failed and has timed out."],[64.909,67.498,"Now the Catch runs only when the Try fails."],[68.199,69.272,"Your turn."],[69.353,73.136,"Valeria has put the Dataverse insert inside the Try scope."],[73.217,75.635,"Now she opens the settings of the Catch scope."],[75.716,78.027,"Which run after options should she select?"],[78.108,79.886,"Is successful and is skipped?"],[79.967,81.744,"Is skipped and has timed out?"],[81.825,83.902,"Or has failed or has timed out?"],[83.983,85.718,"Decide before I answer."],[89.299,91.226,"Has failed or has timed out."],[91.307,94.727,"The Catch must run when the Try fails or runs out of time."],[94.808,97.185,"Is successful is the trap, because the Catch"],[97.185,99.871,"would then run only when everything went well."],[100.572,103.928,"Inside the Catch, Valeria needs to know what went wrong."],[104.009,108.774,"The result function returns the results of the actions inside the Try scope."],[108.855,110.867,"Some succeeded and one failed."],[110.948,112.635,"With the Filter array action,"],[112.635,116.267,"she keeps only the one that failed, with its exact message."],[116.348,121.496,"With that data she can log the error, or notify someone, such as the IT team."],[122.197,123.996,"Some failures are transient."],[124.077,127.199,"The network fails for a moment, and a later try works."],[127.28,130.423,"A retry policy helps the flow recover from them."],[130.504,132.498,"It is set in the action settings,"],[132.498,136.143,"with an initial interval and a maximum number of retries."],[136.224,138.144,"Exponential retries are preferred,"],[138.144,141.223,"because they increase the interval between retries."],[141.304,145.578,"Each wait is longer than the last, so the problem has more time to clear."],[146.279,147.352,"Your turn."],[147.433,150.491,"CreateTicket also calls an external service."],[150.572,154.334,"Sometimes the network fails for a moment, and a later try works."],[154.415,156.491,"What should Valeria set on that call?"],[156.572,158.734,"An exponential retry policy?"],[158.815,160.699,"A Terminate with status Failed?"],[160.78,162.6,"Or a Catch with is successful?"],[162.681,164.416,"Decide before I answer."],[167.997,170.159,"An exponential retry policy."],[170.24,173.349,"A retry policy recovers from transient failures,"],[173.349,177.564,"and exponential retries increase the interval between retries."],[177.645,181.962,"Terminate is the trap here, because it stops the flow instead of trying again."],[182.663,184.398,"The Catch has one more job."],[184.479,187.092,"When the error is logged and someone is notified,"],[187.092,189.798,"the flow should not pretend that all went well."],[189.879,194.088,"Terminate is an action that stops the flow with a status and a message."],[194.169,196.85,"Valeria adds Terminate at the end of the Catch,"],[196.85,199.275,"with status Failed and a short message."],[199.356,203.502,"The run stops, and it leaves a diagnosis that anyone can read."],[204.203,206.386,"Here is the whole Contoso case."],[206.467,210.591,"In CreateTicket, the Dataverse insert goes inside the Try scope."],[210.672,215.543,"If it fails, the Catch scope runs, with run after on has failed and has timed out."],[215.624,220.218,"It uses the result function and Filter array to get the exact message."],[220.299,225.618,"It logs it, notifies the IT team, and ends with Terminate in status Failed."],[225.699,229.609,"The call to the external service has an exponential retry policy,"],[229.609,234.26,"because sometimes the network fails for a moment, and a later retry works."],[234.961,236.27,"Here are the steps."],[236.351,238.662,"Open your agent flow in the designer."],[238.743,242.632,"Add a scope, name it Try, and move the main actions inside it."],[242.713,245.814,"Add another scope called Catch, right after the Try."],[245.895,250.318,"In the Catch settings, configure run after with has failed and has timed out."],[250.399,254.182,"Inside the Catch, use Filter array on the result of the Try."],[254.263,259.624,"Log the error or notify IT, and add Terminate with status Failed and a message."],[259.705,263.936,"Last, set an exponential retry policy on sensitive actions."],[264.637,265.711,"Your turn."],[265.792,270.279,"The service manager wants each Try error logged with its exact message."],[270.36,272.223,"Valeria must read it first."],[272.304,274.146,"What should she add to read the error?"],[274.227,276.73,"An exponential retry on every action?"],[276.811,279.122,"Filter array on the result function?"],[279.203,281.62,"Or a Catch that runs after is successful?"],[281.701,283.436,"Decide before I answer."],[287.017,289.307,"Filter array on the result function."],[289.388,294.408,"The result function returns the Try results, and Filter array keeps the failed one."],[294.489,296.594,"A Catch on is successful is the trap,"],[296.594,299.467,"because it only runs when everything went well."],[300.168,302.713,"Back at Contoso, Marta's ticket is saved,"],[302.713,305.892,"and when something fails, the IT team knows why."],[305.973,307.324,"Remember the pattern."],[307.405,309.674,"A Try scope holds the main actions."],[309.755,314.284,"A Catch scope runs after has failed and has timed out, never is successful."],[314.365,317.423,"The result function and Filter array give you the error."],[317.504,320.668,"Exponential retry handles transient failures."],[320.749,324.276,"Terminate with status Failed leaves a status and a message."],[324.357,326.028,"Next, human in the loop."]],"quiz":[{"at":83.983,"answerAt":89.299,"question":"Valeria has put the Dataverse insert inside the Try scope. Now she opens the settings of the Catch scope. Which run after options should she select?","options":["Is successful and is skipped","Is skipped and has timed out","Has failed or has timed out"],"right":2,"trap":0},{"at":162.681,"answerAt":167.997,"question":"CreateTicket also calls an external service. Sometimes the network fails for a moment, and a later try works. What should Valeria set on that call?","options":["An exponential retry policy","A Terminate with status Failed","A Catch with is successful"],"right":0,"trap":1},{"at":281.701,"answerAt":287.017,"question":"The service manager wants each Try error logged with its exact message. Valeria must read it first. What should she add to read the error?","options":["An exponential retry on every action","Filter array on the result function","A Catch that runs after is successful"],"right":1,"trap":2}],"poster":"video/L19.jpg"},"L20":{"src":"video/L20.mp4","duration":347.802,"scenes":[{"start":0},{"start":26.138},{"start":50.985},{"start":73.765},{"start":94.75},{"start":133.075},{"start":154.853},{"start":177.931},{"start":213.142},{"start":245.058},{"start":273.561},{"start":309.582}],"cues":[[0.8,3.078,"Marta asks Nexo for a new laptop,"],[3.078,7.143,"and Contoso handles laptop purchases with an agent flow."],[7.224,10.495,"But someone must say yes before the purchase goes ahead."],[10.576,13.42,"Valeria knows the answer is human in the loop."],[13.501,16.717,"It means a person takes part in the automatic process,"],[16.717,19.716,"like a boss who signs before something is sent."],[19.797,23.26,"The flow can ask someone for an approval or a piece of data."],[23.341,25.887,"Then it waits for the answer before moving on."],[26.588,32.398,"For an approval in several steps, Valeria uses the Run a multistage approval action."],[32.479,36.091,"It comes from the Human review connector, and it is in preview."],[36.172,41.235,"It combines manual stages, AI stages, and conditions between the stages."],[41.316,44.822,"Multistage approvals exist only in agent flows."],[44.903,47.898,"People respond through the Approvals app in Teams,"],[47.898,50.734,"in Outlook, or in the Power Automate portal."],[51.435,54.62,"A manual stage is a step where a person decides."],[54.701,56.756,"Valeria picks the approval type."],[56.837,60.386,"First to respond ends with the first response received."],[60.467,63.93,"Everyone must approve needs every approver to say yes."],[64.011,68.348,"She also sets the title, who the stage is assigned to, and the details."],[68.429,73.514,"One rule matters: you cannot assign the same approver to several manual stages."],[74.215,77.038,"An AI stage is a step where a model decides."],[77.119,80.299,"Valeria writes its instructions and gives it inputs,"],[80.299,83.312,"such as documents, images, text, or knowledge."],[83.393,85.768,"She chooses the model and selects Test."],[85.849,89.846,"The stage returns Approve or Reject, together with a rationale."],[89.927,94.499,"So anyone can read why the stage decided, and not only what it decided."],[95.2,96.274,"Your turn."],[96.355,100.308,"Valeria builds the laptop approval with two manual stages."],[100.389,102.911,"The service manager approves the first one,"],[102.911,106.455,"and Valeria wants the same manager on the second one too."],[106.536,107.78,"What should she do?"],[107.861,110.087,"Assign the manager to both stages?"],[110.168,112.138,"Use a second approver instead?"],[112.219,114.594,"Or turn both stages into conditions?"],[114.675,116.41,"Decide before I answer."],[119.991,121.96,"Use a second approver instead."],[122.041,125.554,"You cannot assign the same approver to several manual stages,"],[125.554,128,"so the second stage needs someone else."],[128.081,132.824,"Assigning the manager to both stages is the trap, because the rule forbids it."],[133.525,136.626,"Between the stages, Valeria can add conditions."],[136.707,142.047,"A condition lets her route, approve, reject, or skip stages based on criteria."],[142.128,144.482,"Without conditions, the path is simple."],[144.563,147.642,"If a stage is approved, it moves to the next one."],[147.723,150.14,"If it is rejected, the process ends."],[150.221,154.602,"One detail: on the left side of a condition, you can only use an input."],[155.303,159.598,"Sometimes the flow does not need a yes or a no, only a piece of data."],[159.679,162.758,"For that, Valeria uses Request for information."],[162.839,165.52,"It pauses the flow and asks one or more people"],[165.52,168.051,"through Outlook, inside the same tenant."],[168.132,169.803,"The first response wins."],[169.884,174.008,"Input types include text, yes or no, email, number, and date."],[174.089,177.68,"The answers come back as dynamic content for the next steps."],[178.381,179.455,"Your turn."],[179.536,182.892,"Marta's laptop request arrives without a cost center."],[182.973,186.138,"The flow cannot continue until someone types it in."],[186.219,187.719,"What should Valeria add?"],[187.8,189.748,"A new manual approval stage?"],[189.829,191.65,"A condition on the cost center?"],[191.731,193.636,"Or a Request for information?"],[193.717,195.452,"Decide before I answer."],[199.033,200.747,"A Request for information."],[200.828,204.178,"It pauses the flow, asks for the data through Outlook,"],[204.178,206.488,"and returns it as dynamic content."],[206.569,208.889,"A manual approval stage is the trap,"],[208.889,212.891,"because it returns Approve or Reject, not the missing data."],[213.592,215.775,"Here is the whole Contoso case."],[215.856,218.712,"Marta's laptop request first goes through an AI"],[218.712,221.708,"stage that checks the amount is within budget."],[221.789,224.826,"It returns Approve or Reject with its rationale."],[224.907,226.663,"Then a condition decides."],[226.744,228.296,"Above a certain threshold,"],[228.296,232.554,"the request goes to a manual management stage with First to respond."],[232.635,234.455,"If not, it ends approved."],[234.536,238.148,"A missing cost center is asked with Request for information."],[238.229,241.817,"One more fact: advanced approvals have no ALM support,"],[241.817,244.807,"so you must recreate them after importing."],[245.508,246.816,"Here are the steps."],[246.897,249.144,"Open the designer of an agent flow."],[249.225,252.001,"Select the plus sign where you want the approval,"],[252.001,254.523,"and search for Run a multistage approval."],[254.604,257.79,"Select Set up the approval to open the stage editor."],[257.871,261.782,"Create a manual stage with a title, Assigned to, and Details."],[261.863,266.222,"Add an AI stage with instructions, choose the model, and select Test."],[266.303,268.443,"Add a condition between the stages."],[268.524,273.31,"To collect a piece of data, also try Request for information with a text field."],[274.011,275.084,"Your turn."],[275.165,277.668,"The laptop approval works in development."],[277.749,281.511,"Valeria exports the solution and imports it into production."],[281.592,284.244,"What must she do with the multistage approval?"],[284.325,286.615,"Recreate the approval after import?"],[286.696,288.964,"Nothing, it travels with the solution?"],[289.045,291.74,"Or export it again as unmanaged first?"],[291.821,293.556,"Decide before I answer."],[297.137,299.512,"Recreate the approval after import."],[299.593,304.742,"Advanced approvals have no ALM support, so you must recreate them after importing."],[304.823,309.331,"Doing nothing is the trap, because the approval does not travel with the solution."],[310.032,312.88,"Back at Contoso, Marta's laptop is approved,"],[312.88,315.927,"and the service manager signed in one stage."],[316.008,317.295,"Remember the rules."],[317.376,322.546,"Stages with AI and humans mean a multistage approval, only in agent flows."],[322.627,326.694,"Manual stages use First to respond or Everyone must approve,"],[326.694,328.927,"never the same approver twice."],[329.008,332.684,"AI stages return Approve or Reject with a rationale."],[332.765,335.546,"Conditions route, approve, reject, or skip."],[335.627,338.642,"A piece of data means Request for information."],[338.723,341.524,"Recreate advanced approvals after import."],[341.605,344.3,"Next, monitor agent flows and their cost."]],"quiz":[{"at":114.675,"answerAt":119.991,"question":"Valeria builds the laptop approval with two manual stages. The service manager approves the first one, and Valeria wants the same manager on the second one too. What should she do?","options":["Assign the manager to both stages","Use a second approver instead","Turn both stages into conditions"],"right":1,"trap":0},{"at":193.717,"answerAt":199.033,"question":"Marta's laptop request arrives without a cost center. The flow cannot continue until someone types it in. What should Valeria add?","options":["A new manual approval stage","A condition on the cost center","A Request for information"],"right":2,"trap":0},{"at":291.821,"answerAt":297.137,"question":"The laptop approval works in development. Valeria exports the solution and imports it into production. What must she do with the multistage approval?","options":["Recreate the approval after import","Nothing, it travels with the solution","Export it again as unmanaged first"],"right":0,"trap":1}],"poster":"video/L20.jpg"},"L12":{"src":"video/L12.mp4","duration":305.149,"scenes":[{"start":0},{"start":20.482},{"start":37.003},{"start":58.223},{"start":91.791},{"start":113.87},{"start":138.159},{"start":160.169},{"start":196.275},{"start":214.613},{"start":251.615},{"start":276.833}],"cues":[[0.8,4.348,"Marta wants to report a problem to Contoso's help team."],[4.429,9.492,"Her agent asks for the title, waits, then asks for the urgency, and waits again."],[9.573,14.508,"The service manager wants both details in every ticket, without the back and forth."],[14.589,18.18,"Valeria wants to hand Marta one sheet to fill in all at once."],[18.261,20.231,"Today you learn Adaptive Cards."],[20.932,25.974,"An Adaptive Card is a mini form inside the chat, with text, fields, and buttons."],[26.055,29.436,"It is the difference between asking for details one by one over"],[29.436,32.91,"the phone and handing someone a sheet to fill in all at once."],[32.991,36.752,"The agent gets everything together when the user selects submit."],[37.453,41.62,"To collect data with a card, you use the Ask with Adaptive Card node."],[41.701,45.868,"The card needs at least one submit button, and it can have input fields."],[45.949,50.756,"What the user types is saved in variables you can use later in the conversation."],[50.837,55.068,"A card inside a Message or Question node is only informational."],[55.149,57.972,"It shows data, but it collects no response."],[58.673,59.747,"Your turn."],[59.828,64.251,"Contoso wants a ticket form in the chat, with a title and an urgency."],[64.332,66.942,"The user must send both together with a button."],[67.023,68.843,"Which node should Valeria use?"],[68.924,70.702,"A Message node with a card?"],[70.783,72.454,"Ask with Adaptive Card?"],[72.535,74.462,"Or a Question node with a card?"],[74.543,76.278,"Decide before I answer."],[79.859,81.53,"Ask with Adaptive Card."],[81.611,86.204,"It is the node that needs at least one submit button and collects the response."],[86.285,91.54,"A card in a Message or Question node is only informational, so it collects nothing."],[92.241,94.467,"A card can have six input elements."],[94.548,96.944,"Input Text, which can be multiline."],[97.025,100.147,"Input Number, with an optional minimum and maximum."],[100.228,102.112,"Input Date and Input Time."],[102.193,104.974,"Input Toggle, which returns true or false."],[105.055,108.411,"And Input ChoiceSet, a dropdown or radio buttons."],[108.492,111.235,"Mark a field as Required in the properties panel,"],[111.235,113.619,"and the form cannot be sent without it."],[114.32,115.875,"When you save the design,"],[115.875,120.428,"Copilot Studio automatically creates output variables from the inputs."],[120.509,124.442,"If they are not right, you fix the list and its types with Edit Schema."],[124.523,130.034,"Give each input a clear camel case ID, such as leave type, instead of a default one."],[130.115,132.513,"For a dropdown with dynamic choices,"],[132.513,137.908,"use a Power Fx expression that points to a table with title and value columns."],[138.609,141.991,"Copilot Studio supports schema one point six and earlier,"],[141.991,143.971,"but it depends on the channel."],[144.052,147.899,"Web Chat supports one point six, without Action Execute."],[147.98,151.571,"The live chat widget and Teams go up to one point five."],[151.652,155.627,"The test chat renders one point six, so everything looks fine there."],[155.708,159.918,"The authoring canvas does not render version one point six cards at all."],[160.619,161.692,"Your turn."],[161.773,165.211,"Valeria designed the ticket card with schema one point six,"],[165.211,167.626,"and it looks perfect in the test chat."],[167.707,169.932,"Contoso's employees use Teams."],[170.013,171.258,"What should she do?"],[171.339,173.628,"Keep schema one point six everywhere?"],[173.709,175.828,"Check it only in the authoring canvas?"],[175.909,178.37,"Or design with schema one point five?"],[178.451,180.186,"Decide before I answer."],[183.767,186.014,"Design with schema one point five."],[186.095,187.932,"Teams stops at one point five,"],[187.932,191.499,"but the test chat shows one point six, so it fools you."],[191.58,196.024,"One point six fails in Teams, and the authoring canvas cannot render it."],[196.725,200.274,"What if the user closes the card without selecting submit?"],[200.355,202.644,"Then the output variables stay empty."],[202.725,206.636,"So add a Condition node after the Ask with Adaptive Card node."],[206.717,209.534,"And when cards are consecutive or retried,"],[209.534,214.362,"put a unique ID in each Action Submit data, such as action Submit ID."],[215.063,216.136,"Your turn."],[216.217,219.872,"A user closes the ticket card without selecting submit."],[219.953,221.71,"Its outputs stay empty."],[221.791,224.315,"What should Valeria add right after the node?"],[224.396,226.344,"A Condition node that checks them?"],[226.425,229.099,"A Message that uses the title variable?"],[229.18,231.491,"Or Edit Schema with a new variable?"],[231.572,233.307,"Decide before I answer."],[236.888,238.858,"A Condition node that checks them."],[238.939,243.055,"If the card is closed without submit, the output variables stay empty,"],[243.055,245.666,"and the Condition node handles that case."],[245.747,249.277,"A Message that uses the title variable would show nothing,"],[249.277,251.364,"because that variable is empty."],[252.065,253.672,"Here it is in the studio."],[253.753,257.344,"Open a topic and select Add node under the node you want."],[257.425,259.395,"Choose Ask with Adaptive Card."],[259.476,264.688,"Select the three dots on the node, open Properties, and select Edit adaptive card."],[264.769,268.979,"Add inputs and a submit button, or paste the card JSON."],[269.06,272.672,"Save, and Copilot Studio creates the output variables."],[272.753,274.51,"Review them with Edit Schema."],[274.591,276.582,"Then use one of them in a Message."],[277.283,279.167,"Back to Marta and her ticket."],[279.248,281.562,"Marta fills in one card and sends it,"],[281.562,284.951,"and the agent confirms the ticket with its urgency."],[285.032,286.468,"Remember three things."],[286.549,289.991,"Ask with Adaptive Card collects several fields with buttons."],[290.072,295.242,"Teams stops at schema one point five, even if the test chat shows one point six."],[295.323,299.874,"And a closed card leaves empty variables, so add a Condition node after it."],[299.955,301.647,"Next, custom prompts."]],"quiz":[{"at":74.543,"answerAt":79.859,"question":"Contoso wants a ticket form in the chat, with a title and an urgency. The user must send both together with a button. Which node should Valeria use?","options":["A Message node with a card","Ask with Adaptive Card","A Question node with a card"],"right":1,"trap":0},{"at":178.451,"answerAt":183.767,"question":"Valeria designed the ticket card with schema one point six, and it looks perfect in the test chat. Contoso's employees use Teams. What should she do?","options":["Keep schema one point six everywhere","Check it only in the authoring canvas","Design with schema one point five"],"right":2,"trap":0},{"at":231.572,"answerAt":236.888,"question":"A user closes the ticket card without selecting submit. The output variables stay empty. What should Valeria add right after the node?","options":["A Condition node that checks them","A Message that uses the title variable","Edit Schema with a new variable"],"right":0,"trap":1}],"poster":"video/L12.jpg"},"L13":{"src":"video/L13.mp4","duration":294.738,"scenes":[{"start":0},{"start":19.351},{"start":39.483},{"start":59.554},{"start":75.59},{"start":110.395},{"start":130.866},{"start":150.913},{"start":191.222},{"start":213.573},{"start":233.11},{"start":266.678}],"cues":[[0.8,3.836,"The service desk at Contoso has a new problem."],[3.917,6.579,"Marta sends two tickets that are almost the same,"],[6.579,9.386,"and the agent puts them in different categories."],[9.467,11.778,"The service manager is not happy."],[11.859,16.922,"Valeria has an idea: a saved recipe for the model, called a custom prompt."],[17.003,19.1,"Nexo gets it as a new badge."],[19.801,22.624,"Think of a recipe with variable ingredients."],[22.705,26.851,"The recipe is the instructions, and it stays the same every time."],[26.932,30.715,"What changes is the input, for example the text of a ticket."],[30.796,33.625,"The model reads the instructions and the input,"],[33.625,36.414,"does the task once, and returns one result."],[36.495,39.232,"The recipe is saved, so you can reuse it."],[39.933,43.098,"A prompt is a single-turn tool based on a model."],[43.179,47.218,"It has instructions, inputs and, if you want, knowledge to consult."],[47.299,51.508,"Unlike a conversation, it does one task and returns the result."],[51.589,54.178,"It does not keep a dialogue going with the user."],[54.259,56.207,"A child agent is heavier."],[56.288,59.303,"For one small task, a prompt is the lighter choice."],[60.004,62.592,"You can use the same prompt in three places."],[62.673,65.198,"As an agent tool, from the Tools tab."],[65.279,68.87,"As a node inside a topic, with Add a tool and New prompt."],[68.951,72.371,"Or as the Run a prompt action inside an agent flow."],[72.452,75.339,"Same instructions, same inputs, three doors."],[76.04,77.114,"Your turn."],[77.195,80.7,"Valeria explains custom prompts to the service manager."],[80.781,84.18,"She compares a prompt with a long chat about the same ticket."],[84.261,86.231,"How many turns does a prompt have?"],[86.312,88.431,"As many turns as the user needs?"],[88.512,90.631,"Two, it asks for missing input?"],[90.712,92.788,"Or only one, then it returns?"],[92.869,94.604,"Decide before I answer."],[98.185,100.07,"Only one, then it returns."],[100.151,104.51,"A prompt does one task and returns the result, and that is its whole run."],[104.591,107.013,"A conversation keeps a dialogue going,"],[107.013,110.144,"and a child agent is heavier for a small task."],[110.845,114.888,"Inside the prompt editor, Valeria writes the instructions by hand,"],[114.888,117.722,"with help from Copilot, or from a template."],[117.803,120.668,"She defines the inputs, such as the ticket text."],[120.749,124.874,"Good instructions are clear and short, and they include a fallback output."],[124.955,127.106,"If the text has too little information,"],[127.106,130.615,"the prompt answers not found instead of guessing a category."],[131.316,135.035,"Temperature goes from zero to one, and zero is the default."],[135.116,137.854,"At zero the responses are more predictable."],[137.935,142.294,"With the GPT five reasoning model the slider appears disabled."],[142.375,145.859,"It is set in the prompt settings, not in the agent settings."],[145.94,150.662,"Valeria leaves the temperature at zero whenever she wants consistent results."],[151.363,152.436,"Your turn."],[152.517,154.739,"Contoso's prompt classifies tickets,"],[154.739,158.519,"but two nearly identical tickets got different categories."],[158.6,163.407,"The service manager wants similar tickets to always get the same classification."],[163.488,165.138,"What should Valeria change?"],[165.219,167.082,"Lower the temperature to zero?"],[167.163,168.962,"Raise the temperature near one?"],[169.043,171.439,"Or move the slider into agent settings?"],[171.52,173.255,"Decide before I answer."],[176.836,178.72,"Lower the temperature to zero."],[178.801,181.458,"At zero the responses are more predictable,"],[181.458,184.995,"so similar tickets always get the same classification."],[185.076,187.654,"A high temperature is for creative results,"],[187.654,190.971,"and it is set in the prompt settings, not the agent."],[191.672,194.708,"Contoso builds the prompt called Classify ticket."],[194.789,196.802,"Its input is the ticket text."],[196.883,200.398,"Its instructions ask for one category out of hardware,"],[200.398,204.698,"software or access, and one urgency out of high, medium or low."],[204.779,208.732,"If a ticket has too little information, the prompt answers not found."],[208.813,213.322,"With temperature zero, five similar tickets get the same classification."],[214.023,216.44,"Adding it as a tool takes a few steps."],[216.521,219.238,"Open the agent and go to the Tools tab."],[219.319,222.419,"Select Add a tool, then New tool, and choose Prompt."],[222.5,224.58,"Write the instructions, add the input,"],[224.58,227.627,"choose the model, and leave the temperature at zero."],[227.708,230.019,"Type sample data and select Test."],[230.1,232.859,"Then select Save, and Add and configure."],[233.56,234.634,"Your turn."],[234.715,236.834,"The service manager likes prompts."],[236.915,239.29,"Now he asks where a prompt can be attached."],[239.371,241.468,"Which place does not take a prompt?"],[241.549,243.242,"As a tool of your agent?"],[243.323,244.908,"As a publishing channel?"],[244.989,247.066,"Or as a node inside a topic?"],[247.147,248.882,"Decide before I answer."],[252.463,254.048,"As a publishing channel."],[254.129,259.477,"A prompt is used as an agent tool, as a topic node with Add a tool and New prompt,"],[259.477,262.286,"or as the Run a prompt action in a flow."],[262.367,266.427,"Channels are how users reach the agent, so a prompt never goes there."],[267.128,268.65,"Back to the two tickets."],[268.731,270.564,"The prompt is saved as a tool,"],[270.564,274.37,"and now similar requests get the same category and urgency."],[274.451,275.887,"Remember three things."],[275.968,280.54,"A prompt is a recipe: same instructions, changing inputs, one result."],[280.621,283.615,"It is single-turn, lighter than a child agent."],[283.696,288.311,"Clear instructions and temperature zero give consistent classifications."],[288.392,291.236,"Next, the Send HTTP request node."]],"quiz":[{"at":92.869,"answerAt":98.185,"question":"How many turns does a prompt have?","options":["As many turns as the user needs","Two, it asks for missing input","Only one, then it returns"],"right":2,"trap":0},{"at":171.52,"answerAt":176.836,"question":"Contoso's new prompt classifies tickets, but two nearly identical tickets got different categories. The service manager wants the same ticket to always get the same classification. What should Valeria change?","options":["Lower the temperature to zero","Raise the temperature near one","Move the slider into agent settings"],"right":0,"trap":1},{"at":247.147,"answerAt":252.463,"question":"The service manager asks where a prompt can be attached. Which place does not take a prompt?","options":["As a tool of your agent","As a publishing channel","As a node inside a topic"],"right":1,"trap":0}],"poster":"video/L13.jpg"}};
